import React, { useState } from 'react';
import { Platform, StatusBar, 
  View,
  Text,
  StyleSheet,
  ScrollView,
  TouchableOpacity,
  TextInput,
  Alert,
  ActivityIndicator
} from 'react-native';
import Ionicons from 'react-native-vector-icons/Ionicons';
import AsyncStorage from '@react-native-async-storage/async-storage';
import axios from 'axios';
import Config from './Config';
import { useTheme } from '../context/ThemeContext.js';
import {  useThemedStyles } from '../hooks/useThemedStyles';

const ProfessionalAccess = () => {
  const { isDarkMode } = useTheme();
  const { createThemedStyles, theme } = useThemedStyles();
  const styles = createThemedStyles(themedStyles);
  
  const [formData, setFormData] = useState({
    companyName: '',
    registrationNumber: '',
    phone: '',
    address: '',
    description: ''
  });
  const [loading, setLoading] = useState(false);

  const handleSubmit = async () => {
    if (!formData.companyName || !formData.registrationNumber || !formData.phone) {
      Alert.alert('Erreur', 'Veuillez remplir tous les champs obligatoires');
      return;
    }

    setLoading(true);
    try {
      const token = await AsyncStorage.getItem('access_token');
      await axios.post(`${Config.BASE_URL}/api/users/become-professional/`, formData, {
        headers: { Authorization: `Bearer ${token}` }
      });
      
      Alert.alert(
        'Demande envoyée',
        'Votre demande a été envoyée avec succès. Nous vous contacterons sous 48h.',
        [{ text: 'OK' }]
      );
    } catch (error) {
      Alert.alert('Erreur', 'Impossible d\'envoyer votre demande');
    } finally {
      setLoading(false);
    }
  };

  const benefits = [
    { icon: 'star', title: 'Visibilité premium', desc: 'Vos annonces sont mises en avant' },
    { icon: 'trending-up', title: 'Statistiques avancées', desc: 'Analysez vos performances' },
    { icon: 'people', title: 'Support prioritaire', desc: 'Assistance 24/7 dédiée' },
    { icon: 'checkbox', title: 'Badge professionnel', desc: 'Gagnez la confiance des clients' }
  ];

  return (
    <ScrollView style={[styles.container, isDarkMode && styles.darkContainer]}>
      <View style={styles.header}>
        <Text style={[styles.headerTitle, isDarkMode && styles.darkText]}>Devenir Professionnel</Text>
        <Text style={[styles.headerSubtitle, isDarkMode && styles.darkSubText]}>
          Rejoignez notre réseau d'experts immobiliers
        </Text>
      </View>

      <View style={styles.benefitsSection}>
        <Text style={[styles.sectionTitle, isDarkMode && styles.darkText]}>Avantages</Text>
        <View style={styles.benefitsGrid}>
          {benefits.map((benefit, index) => (
            <View key={index} style={styles.benefitCard}>
              <View style={[styles.benefitIcon, { backgroundColor: theme.primary + '20' }]}>
                <Ionicons name={benefit.icon} size={30} color={theme.primary} />
              </View>
              <Text style={[styles.benefitTitle, isDarkMode && styles.darkText]}>{benefit.title}</Text>
              <Text style={[styles.benefitDesc, isDarkMode && styles.darkSubText]}>{benefit.desc}</Text>
            </View>
          ))}
        </View>
      </View>

      <View style={styles.formSection}>
        <Text style={[styles.sectionTitle, isDarkMode && styles.darkText]}>Formulaire d'inscription</Text>
        
        <View style={styles.formGroup}>
          <Text style={[styles.label, isDarkMode && styles.darkText]}>Nom de l'entreprise *</Text>
          <View style={[styles.inputContainer, isDarkMode && styles.darkCard]}>
            <Ionicons name="business" size={20} color={theme.subText} />
            <TextInput
              style={[styles.input, isDarkMode && styles.darkText]}
              placeholder="Nom de votre agence"
              placeholderTextColor={theme.subText}
              value={formData.companyName}
              onChangeText={(text) => setFormData({...formData, companyName: text})}
            />
          </View>
        </View>

        <View style={styles.formGroup}>
          <Text style={[styles.label, isDarkMode && styles.darkText]}>Numéro d'enregistrement *</Text>
          <View style={[styles.inputContainer, isDarkMode && styles.darkCard]}>
            <Ionicons name="document-text" size={20} color={theme.subText} />
            <TextInput
              style={[styles.input, isDarkMode && styles.darkText]}
              placeholder="Numéro RCCM / NINEA"
              placeholderTextColor={theme.subText}
              value={formData.registrationNumber}
              onChangeText={(text) => setFormData({...formData, registrationNumber: text})}
            />
          </View>
        </View>

        <View style={styles.formGroup}>
          <Text style={[styles.label, isDarkMode && styles.darkText]}>Téléphone *</Text>
          <View style={[styles.inputContainer, isDarkMode && styles.darkCard]}>
            <Ionicons name="call" size={20} color={theme.subText} />
            <TextInput
              style={[styles.input, isDarkMode && styles.darkText]}
              placeholder="Votre numéro de téléphone"
              placeholderTextColor={theme.subText}
              keyboardType="phone-pad"
              value={formData.phone}
              onChangeText={(text) => setFormData({...formData, phone: text})}
            />
          </View>
        </View>

        <View style={styles.formGroup}>
          <Text style={[styles.label, isDarkMode && styles.darkText]}>Adresse</Text>
          <View style={[styles.inputContainer, isDarkMode && styles.darkCard]}>
            <Ionicons name="location" size={20} color={theme.subText} />
            <TextInput
              style={[styles.input, isDarkMode && styles.darkText]}
              placeholder="Adresse de votre agence"
              placeholderTextColor={theme.subText}
              value={formData.address}
              onChangeText={(text) => setFormData({...formData, address: text})}
            />
          </View>
        </View>

        <View style={styles.formGroup}>
          <Text style={[styles.label, isDarkMode && styles.darkText]}>Description</Text>
          <View style={[styles.textAreaContainer, isDarkMode && styles.darkCard]}>
            <TextInput
              style={[styles.textArea, isDarkMode && styles.darkText]}
              placeholder="Présentez votre entreprise..."
              placeholderTextColor={theme.subText}
              multiline
              numberOfLines={4}
              value={formData.description}
              onChangeText={(text) => setFormData({...formData, description: text})}
            />
          </View>
        </View>

        <TouchableOpacity 
          style={[styles.submitButton, loading && styles.buttonDisabled]}
          onPress={handleSubmit}
          disabled={loading}
        >
          {loading ? (
            <ActivityIndicator color="#fff" />
          ) : (
            <Text style={styles.submitButtonText}>Envoyer la demande</Text>
          )}
        </TouchableOpacity>
      </View>
    </ScrollView>
  );
};

const themedStyles = (theme, isDarkMode, Platform, StatusBar) => StyleSheet.create({
  container: {
          flex: 1,
          backgroundColor: theme.background,
          paddingTop: Platform.OS === 'android' ? StatusBar.currentHeight : 0,
        },
  darkContainer: { backgroundColor: '#1a1a1a' },
  darkText: { color: '#fff' },
  darkSubText: { color: '#aaa' },
  darkCard: { backgroundColor: '#2d2d2d' },
  
  header: { padding: 20, backgroundColor: theme.card, marginBottom: 15 },
  headerTitle: { fontSize: 28, fontWeight: 'bold', color: theme.text, marginBottom: 5 },
  headerSubtitle: { fontSize: 14, color: theme.subText },
  
  benefitsSection: { padding: 20 },
  sectionTitle: { fontSize: 20, fontWeight: 'bold', color: theme.text, marginBottom: 15 },
  benefitsGrid: { gap: 15 },
  benefitCard: { backgroundColor: theme.card, padding: 15, borderRadius: 12, alignItems: 'center' },
  benefitIcon: { width: 60, height: 60, borderRadius: 30, justifyContent: 'center', alignItems: 'center', marginBottom: 10 },
  benefitTitle: { fontSize: 16, fontWeight: 'bold', color: theme.text, marginBottom: 5 },
  benefitDesc: { fontSize: 12, color: theme.subText, textAlign: 'center' },
  
  formSection: { padding: 20 },
  formGroup: { marginBottom: 20 },
  label: { fontSize: 14, fontWeight: '600', color: theme.text, marginBottom: 8 },
  inputContainer: { flexDirection: 'row', alignItems: 'center', backgroundColor: theme.card, borderRadius: 10, paddingHorizontal: 15, borderWidth: 1, borderColor: theme.border },
  input: { flex: 1, paddingVertical: 12, marginLeft: 10, fontSize: 16 },
  textAreaContainer: { backgroundColor: theme.card, borderRadius: 10, borderWidth: 1, borderColor: theme.border, padding: 15 },
  textArea: { fontSize: 16, textAlignVertical: 'top', minHeight: 100 },
  
  submitButton: { backgroundColor: theme.primary, padding: 15, borderRadius: 10, alignItems: 'center', marginTop: 10 },
  buttonDisabled: { opacity: 0.6 },
  submitButtonText: { color: '#fff', fontSize: 16, fontWeight: 'bold' },
});

export default ProfessionalAccess;


