import React, { useState, useEffect } from 'react';
import { Platform, StatusBar, 
  StyleSheet,
  Text,
  View,
  TouchableOpacity,
  FlatList,
  Image,
  ScrollView,
  Alert,
  SafeAreaView,
  RefreshControl,
  ActivityIndicator
} from 'react-native';
import FontAwesome from 'react-native-vector-icons/FontAwesome';
import MaterialIcons from 'react-native-vector-icons/MaterialIcons';
import { useNavigation, useIsFocused } from '@react-navigation/native';
import axios from 'axios';
import AsyncStorage from '@react-native-async-storage/async-storage';
import Config from './Config';
import {useThemedStyles } from '../hooks/useThemedStyles';

const FavoritesScreen = () => {
  const navigation = useNavigation();
  const isFocused = useIsFocused();
  const { createThemedStyles, isDarkMode, theme } = useThemedStyles();
  const [favorites, setFavorites] = useState({
    maisons: [],
    parcelles: [],
    hotels: [],
    residences: []
  });
  const [activeCategory, setActiveCategory] = useState('tous');
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [user, setUser] = useState(null);
  const [error, setError] = useState(null);
 const styles = createThemedStyles(themedStyles);
  useEffect(() => {
    if (isFocused) {
      loadUserData();
    }
  }, [isFocused]);

  const loadUserData = async () => {
    try {
      const userData = await AsyncStorage.getItem('user');
      const token = await AsyncStorage.getItem('access_token');
      if (userData && token) {
        setUser({ ...JSON.parse(userData), token });
        fetchAllFavorites(token);
      } else {
        setLoading(false);
        Alert.alert(
          'Connexion requise',
          'Veuillez vous connecter pour voir vos favoris',
          [
            { text: 'Annuler', style: 'cancel' },
            { text: 'Se connecter', onPress: () => navigation.navigate('LoginScreen') }
          ]
        );
      }
    } catch (error) {
      console.error('Erreur chargement utilisateur:', error);
      setLoading(false);
      setError('Erreur de chargement');
    }
  };

  const fetchAllFavorites = async (token) => {
    try {
      setLoading(true);
      setError(null);
      
      // ✅ Récupérer UNIQUEMENT les maisons favorites
      const maisonsResponse = await axios.get(`${Config.BASE_URL}/maisons/mes_favoris/`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      
      console.log('🔍 Maisons favorites reçues:', maisonsResponse.data);
      
      // ✅ Extraire correctement les données
      let maisonsData = [];
      if (maisonsResponse.data) {
        if (Array.isArray(maisonsResponse.data)) {
          maisonsData = maisonsResponse.data;
        } else if (maisonsResponse.data.results && Array.isArray(maisonsResponse.data.results)) {
          maisonsData = maisonsResponse.data.results;
        }
      }
      
      // ✅ Filtrage : ne garder que les maisons qui sont vraiment des favoris
      const filteredMaisons = maisonsData.filter(maison => maison.is_favori === true);
      
      console.log('✅ Maisons après filtrage:', filteredMaisons.length);
      
      // ✅ Pour les autres types, on récupère tous les biens (temporairement)
      // Dans une version finale, il faudra des endpoints spécifiques
      const parcellesResponse = await axios.get(`${Config.BASE_URL}/parcelles/`, {
        headers: { Authorization: `Bearer ${token}` }
      }).catch(() => ({ data: [] }));
      
      const hotelsResponse = await axios.get(`${Config.BASE_URL}/hotels/`, {
        headers: { Authorization: `Bearer ${token}` }
      }).catch(() => ({ data: [] }));
      
      const residencesResponse = await axios.get(`${Config.BASE_URL}/residences/`, {
        headers: { Authorization: `Bearer ${token}` }
      }).catch(() => ({ data: [] }));
      
      // ✅ Extraction des données pour les autres types
      let parcellesData = [];
      let hotelsData = [];
      let residencesData = [];
      
      if (parcellesResponse.data) {
        parcellesData = Array.isArray(parcellesResponse.data) ? parcellesResponse.data : (parcellesResponse.data.results || []);
      }
      if (hotelsResponse.data) {
        hotelsData = Array.isArray(hotelsResponse.data) ? hotelsResponse.data : (hotelsResponse.data.results || []);
      }
      if (residencesResponse.data) {
        residencesData = Array.isArray(residencesResponse.data) ? residencesResponse.data : (residencesResponse.data.results || []);
      }
      
      setFavorites({
        maisons: filteredMaisons,
        parcelles: parcellesData,
        hotels: hotelsData,
        residences: residencesData
      });
      
    } catch (error) {
      console.error('❌ Erreur chargement favoris:', error);
      setError('Impossible de charger vos favoris');
      
      if (error.response?.status === 401) {
        Alert.alert(
          'Session expirée',
          'Votre session a expiré, veuillez vous reconnecter',
          [{ text: 'Se reconnecter', onPress: () => navigation.navigate('Login') }]
        );
      }
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  const onRefresh = () => {
    setRefreshing(true);
    if (user?.token) {
      fetchAllFavorites(user.token);
    } else {
      setRefreshing(false);
    }
  };

  const removeFromFavorites = async (itemId, type) => {
    if (!user?.token) return;
    
    Alert.alert(
      'Confirmation',
      'Voulez-vous retirer ce bien de vos favoris ?',
      [
        { text: 'Annuler', style: 'cancel' },
        {
          text: 'Retirer',
          style: 'destructive',
          onPress: async () => {
            try {
              let endpoint = '';
              
              switch(type) {
                case 'maison':
                  endpoint = `${Config.BASE_URL}/maisons/${itemId}/favori/`;
                  break;
                case 'parcelle':
                  endpoint = `${Config.BASE_URL}/parcelles/${itemId}/`;
                  break;
                case 'hotel':
                  endpoint = `${Config.BASE_URL}/hotels/${itemId}/`;
                  break;
                default:
                  endpoint = `${Config.BASE_URL}/maisons/${itemId}/favori/`;
              }
              
              if (type === 'maison') {
                await axios.post(endpoint, {}, {
                  headers: { Authorization: `Bearer ${user.token}` }
                });
              } else {
                await axios.delete(endpoint, {
                  headers: { Authorization: `Bearer ${user.token}` }
                });
              }
              
              // ✅ Mettre à jour l'état local
              setFavorites(prev => ({
                ...prev,
                [type + 's']: prev[type + 's'].filter(item => item.id !== itemId)
              }));
              
              Alert.alert('Succès', 'Retiré des favoris');
              
            } catch (deleteError) {
              console.error('Erreur suppression:', deleteError);
              Alert.alert('Erreur', 'Impossible de retirer des favoris');
            }
          }
        }
      ]
    );
  };

  const clearAllFavorites = async () => {
    if (favorites.maisons.length === 0) {
      Alert.alert('Info', 'Aucun favori à supprimer');
      return;
    }
    
    Alert.alert(
      'Confirmation',
      'Voulez-vous retirer tous vos favoris ?',
      [
        { text: 'Annuler', style: 'cancel' },
        {
          text: 'Tout retirer',
          style: 'destructive',
          onPress: async () => {
            try {
              if (!user?.token) return;
              
              // ✅ Supprimer tous les favoris maison
              for (const item of favorites.maisons) {
                try {
                  await axios.post(`${Config.BASE_URL}/maisons/${item.id}/favori/`, {}, {
                    headers: { Authorization: `Bearer ${user.token}` }
                  });
                } catch (error) {
                  console.log(`Erreur sur ${item.id}:`, error.message);
                }
              }
              
              setFavorites(prev => ({ ...prev, maisons: [] }));
              Alert.alert('Succès', 'Tous vos favoris ont été retirés');
              
            } catch (error) {
              console.error('Erreur suppression favoris:', error);
              Alert.alert('Erreur', 'Impossible de retirer tous les favoris');
            }
          }
        }
      ]
    );
  };

  const getImageUri = (item) => {
    if (item.photos && Array.isArray(item.photos) && item.photos.length > 0) {
      const firstPhoto = item.photos[0];
      if (typeof firstPhoto === "object" && firstPhoto.photos) {
        return firstPhoto.photos;
      }
      return firstPhoto;
    }
    return null;
  };

  const getItemDetails = (item, type) => {
    switch(type) {
      case 'maison':
        return {
          title: item.titre || 'Maison sans titre',
          location: `${item.quartier || ''}, ${item.ville || ''}`,
          price: `${item.prix || 0} fCfa`,
          features: [
            { icon: 'bed', text: `${item.nombre_chambres || 0} ch.` },
            { icon: 'bath', text: `${item.nombre_salles_de_bain || 0} sdb` },
            ...(item.surface ? [{ icon: 'expand', text: `${item.surface} m²` }] : [])
          ]
        };
      case 'parcelle':
        return {
          title: item.titre || 'Terrain sans titre',
          location: `${item.quartier || ''}, ${item.ville || ''}`,
          price: `${item.prix || 0} fCfa`,
          features: [
            { icon: 'expand', text: `${item.surface || 0} m²` },
            { icon: 'map', text: item.type_parcelle || 'Terrain' }
          ]
        };
      case 'hotel':
        return {
          title: item.titre || 'Hôtel sans titre',
          location: `${item.ville || ''}, ${item.pays || ''}`,
          price: `${item.prix_nuit || 0} fCfa/nuit`,
          features: [
            { icon: 'star', text: `${item.categorie || 0} étoiles` },
            { icon: 'bed', text: `${item.chambres_disponibles || 0} ch. dispo` }
          ]
        };
      default:
        return {
          title: 'Bien immobilier',
          location: '',
          price: '',
          features: []
        };
    }
  };

  const renderFavoriteItem = ({ item, type }) => {
    const imageUri = getImageUri(item);
    const details = getItemDetails(item, type);

    const handlePress = () => {
      if (type === 'maison') {
        navigation.navigate('MaisonDetail', { maisonId: item.id });
      } else if (type === 'parcelle') {
        navigation.navigate('ParcelleDetail', { parcelleId: item.id });
      } else if (type === 'hotel') {
        navigation.navigate('HotelDetail', { hotelId: item.id });
      }
    };

    const typeLabels = {
      'maison': 'Maison',
      'parcelle': 'Terrain',
      'hotel': 'Hôtel',
      'residence': 'Résidence'
    };

    if (!details) return null;

    return (
      <TouchableOpacity style={styles.favoriteCard} onPress={handlePress}>
        <Image
          source={imageUri ? { uri: imageUri } : require('../assets/placeholder.png')}
          style={styles.favoriteImage}
          defaultSource={require('../assets/placeholder.png')}
        />
        
        <View style={styles.favoriteInfo}>
          <View style={styles.headerRow}>
            <Text style={styles.favoriteType}>{typeLabels[type] || type}</Text>
            <Text style={styles.favoriteTitle} numberOfLines={1}>
              {details.title}
            </Text>
          </View>
          
          <Text style={styles.favoriteLocation} numberOfLines={1}>
            <FontAwesome name="map-marker" size={12} color={theme.subText} />
            {' '}{details.location}
          </Text>
          
          <Text style={styles.favoritePrice}>
            <FontAwesome name="money" size={12} color={theme.primary} />
            {' '}{details.price}
          </Text>
          
          <View style={styles.propertyFeatures}>
            {details.features.map((feature, index) => (
              <Text key={index} style={styles.featureText}>
                <FontAwesome name={feature.icon} size={12} /> {feature.text}
              </Text>
            ))}
          </View>
        </View>
        
        <TouchableOpacity
          style={styles.removeButton}
          onPress={() => removeFromFavorites(item.id, type)}
        >
          <FontAwesome name="trash" size={18} color={theme.error} />
        </TouchableOpacity>
      </TouchableOpacity>
    );
  };

  const renderCategoryTabs = () => {
    const totalFavorites = favorites.maisons.length;
    
    const categories = [
      { id: 'tous', label: `Tous (${totalFavorites})`, icon: 'th-large' },
      { id: 'maisons', label: `Maisons (${favorites.maisons.length})`, icon: 'home' },
    ];

    return (
      <View style={styles.categoriesContainer}>
        <ScrollView horizontal showsHorizontalScrollIndicator={false}>
          {categories.map((category) => (
            <TouchableOpacity
              key={category.id}
              style={[
                styles.categoryTab,
                activeCategory === category.id && styles.categoryTabActive
              ]}
              onPress={() => setActiveCategory(category.id)}
            >
              <FontAwesome 
                name={category.icon} 
                size={16} 
                color={activeCategory === category.id ? '#fff' : theme.subText} 
              />
              <Text style={[
                styles.categoryText,
                activeCategory === category.id && styles.categoryTextActive
              ]}>
                {category.label}
              </Text>
            </TouchableOpacity>
          ))}
        </ScrollView>
      </View>
    );
  };

  const getCurrentFavorites = () => {
    if (activeCategory === 'tous') {
      return favorites.maisons.map(item => ({ ...item, _type: 'maison' }));
    }
    return favorites.maisons.map(item => ({ ...item, _type: 'maison' }));
  };

  const renderEmptyState = () => (
    <View style={styles.emptyContainer}>
      <FontAwesome name="heart" size={60} color={theme.subText} />
      <Text style={styles.emptyTitle}>Aucun favori</Text>
      <Text style={styles.emptyText}>
        {!user ? 'Connectez-vous pour ajouter des favoris' : 'Ajoutez des biens à vos favoris ❤️'}
      </Text>
      {!user ? (
        <TouchableOpacity 
          style={styles.loginButton}
          onPress={() => navigation.navigate('Login')}
        >
          <Text style={styles.loginButtonText}>Se connecter</Text>
        </TouchableOpacity>
      ) : (
        <TouchableOpacity 
          style={styles.browseButton}
          onPress={() => navigation.navigate('Accueil')}
        >
          <Text style={styles.browseButtonText}>Parcourir les biens</Text>
        </TouchableOpacity>
      )}
    </View>
  );

  const renderErrorState = () => (
    <View style={styles.emptyContainer}>
      <FontAwesome name="exclamation-triangle" size={60} color={theme.error} />
      <Text style={styles.emptyTitle}>Erreur de chargement</Text>
      <Text style={styles.emptyText}>{error}</Text>
      <TouchableOpacity 
        style={styles.retryButton}
        onPress={() => user?.token && fetchAllFavorites(user.token)}
      >
        <Text style={styles.retryButtonText}>Réessayer</Text>
      </TouchableOpacity>
    </View>
  );

  const renderLoading = () => (
    <View style={styles.loadingContainer}>
      <ActivityIndicator size="large" color={theme.primary} />
      <Text style={styles.loadingText}>Chargement de vos favoris...</Text>
    </View>
  );

  if (loading && !refreshing) {
    return (
      <SafeAreaView style={styles.container}>
        <StatusBar barStyle={isDarkMode ? 'light-content' : 'dark-content'} backgroundColor={theme.background} translucent />
        <View style={styles.header}>
          <Text style={styles.headerTitle}>Mes Favoris</Text>
        </View>
        {renderLoading()}
      </SafeAreaView>
    );
  }

  const currentFavorites = getCurrentFavorites();

  return (
    <SafeAreaView style={styles.container}>
      <StatusBar barStyle={isDarkMode ? 'light-content' : 'dark-content'} backgroundColor={theme.background} translucent />
      
      <View style={styles.header}>
        <Text style={styles.headerTitle}>Mes Favoris</Text>
        
        {currentFavorites.length > 0 && (
          <TouchableOpacity onPress={clearAllFavorites}>
            <Text style={styles.clearAllText}>Tout retirer</Text>
          </TouchableOpacity>
        )}
      </View>

      {error ? renderErrorState() : currentFavorites.length > 0 ? (
        <FlatList
          data={currentFavorites}
          keyExtractor={(item, index) => `${item._type}-${item.id || index}`}
          renderItem={({ item }) => renderFavoriteItem({ 
            item, 
            type: item._type 
          })}
          contentContainerStyle={styles.favoritesList}
          ListHeaderComponent={renderCategoryTabs()}
          refreshControl={
            <RefreshControl
              refreshing={refreshing}
              onRefresh={onRefresh}
              colors={[theme.primary]}
              tintColor={theme.primary}
            />
          }
          ListEmptyComponent={renderEmptyState}
        />
      ) : (
        <View style={styles.mainContainer}>
          {renderEmptyState()}
        </View>
      )}
    </SafeAreaView>
  );
};

