import React, { useState, useEffect } from 'react';
import { Platform, StatusBar, 
  StyleSheet,
  Text,
  View,
  TouchableOpacity,
  FlatList,
  Alert,
  SafeAreaView,

  RefreshControl,
  ActivityIndicator
} from 'react-native';
import FontAwesome from 'react-native-vector-icons/FontAwesome';
import Ionicons from 'react-native-vector-icons/Ionicons';
import {useNavigation, useIsFocused } from '@react-navigation/native';
import axios from 'axios';
import AsyncStorage from '@react-native-async-storage/async-storage';
import Config from './Config';
import { useThemedStyles } from '../hooks/useThemedStyles';
import { useTheme } from '../context/ThemeContext.js';
const NotificationsScreen = () => {
  const navigation = useNavigation();
  const isFocused = useIsFocused();
  const { createThemedStyles, theme } = useThemedStyles();
  const styles = createThemedStyles(themedStyles);
  const { isDarkMode } = useTheme();
  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [user, setUser] = useState(null);

  useEffect(() => {
    if (isFocused) {
      loadUserData();
    }
  }, [isFocused]);

  const loadUserData = async () => {
    try {
      const userData = await AsyncStorage.getItem('user');
      const token = await AsyncStorage.getItem('access_token');
      if (userData && token) {
        setUser({ ...JSON.parse(userData), token });
        fetchNotifications(token);
      } else {
        setLoading(false);
        Alert.alert(
          'Connexion requise',
          'Veuillez vous connecter pour voir vos notifications',
          [
            { text: 'Annuler', style: 'cancel' },
            { text: 'Se connecter', onPress: () => navigation.navigate('LoginScreen') }
          ]
        );
      }
    } catch (error) {
      console.error('Erreur chargement utilisateur:', error);
      setLoading(false);
    }
  };

  const fetchNotifications = async (token) => {
    try {
      setLoading(true);
      
      const response = await axios.get(`${Config.BASE_URL}/notifications/`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      
      // ✅ GESTION ROBUSTE : extraire le tableau des notifications
      let notificationsData = [];
      if (response.data) {
        if (Array.isArray(response.data)) {
          notificationsData = response.data;
        } else if (response.data.results && Array.isArray(response.data.results)) {
          notificationsData = response.data.results;
        } else if (response.data.notifications && Array.isArray(response.data.notifications)) {
          notificationsData = response.data.notifications;
        }
      }
      
      console.log('✅ Notifications chargées:', notificationsData.length);
      setNotifications(notificationsData);
      
    } catch (error) {
      console.error('Erreur chargement notifications:', error);
      setNotifications(getDemoNotifications());
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  const getDemoNotifications = () => {
    return [
      {
        id: 1,
        title: "Nouveau message",
        body: "John Doe vous a envoyé un message concernant votre propriété",
        type: "message",
        is_read: false,
        created_at: new Date().toISOString(),
        data: { maisonId: 123, senderId: 456 }
      },
      {
        id: 2,
        title: "Votre bien a été liké",
        body: "15 personnes ont aimé votre maison à Niamey",
        type: "like",
        is_read: true,
        created_at: new Date(Date.now() - 3600000).toISOString(),
        data: { maisonId: 123 }
      },
      {
        id: 3,
        title: "Nouveau commentaire",
        body: "Alice a commenté votre publication: 'Superbe propriété!'",
        type: "comment",
        is_read: false,
        created_at: new Date(Date.now() - 7200000).toISOString(),
        data: { maisonId: 123, commentId: 789 }
      }
    ];
  };

  const onRefresh = () => {
    setRefreshing(true);
    if (user?.token) {
      fetchNotifications(user.token);
    } else {
      setRefreshing(false);
    }
  };

  const markAsRead = async (notificationId) => {
    try {
      if (user?.token) {
        await axios.patch(`${Config.BASE_URL}/notifications/${notificationId}/marquer_lu/`, {}, {
          headers: { Authorization: `Bearer ${user.token}` }
        });
      }
      
      setNotifications(prev =>
        prev.map(notif =>
          notif.id === notificationId ? { ...notif, is_read: true } : notif
        )
      );
    } catch (error) {
      console.error('Erreur marquage lu:', error);
    }
  };

  const markAllAsRead = async () => {
    try {
      if (user?.token) {
        await axios.post(`${Config.BASE_URL}/notifications/tout_marquer_lu/`, {}, {
          headers: { Authorization: `Bearer ${user.token}` }
        });
      }
      
      setNotifications(prev =>
        prev.map(notif => ({ ...notif, is_read: true }))
      );
      
      Alert.alert('Succès', 'Toutes les notifications ont été marquées comme lues');
    } catch (error) {
      console.error('Erreur marquage tout lu:', error);
    }
  };

  const clearAllNotifications = () => {
    if (notifications.length === 0) {
      Alert.alert('Info', 'Aucune notification à supprimer');
      return;
    }
    
    Alert.alert(
      'Confirmation',
      'Voulez-vous supprimer toutes les notifications ?',
      [
        { text: 'Annuler', style: 'cancel' },
        {
          text: 'Supprimer tout',
          style: 'destructive',
          onPress: async () => {
            setNotifications([]);
            Alert.alert('Succès', 'Toutes les notifications ont été supprimées');
          }
        }
      ]
    );
  };

  const handleNotificationPress = (notification) => {
    if (!notification.is_read) {
      markAsRead(notification.id);
    }
    
    switch (notification.type) {
      case 'message':
        if (notification.data?.senderId) {
          navigation.navigate('TextoScreen', { userId: notification.data.senderId });
        }
        break;
      case 'like':
      case 'comment':
        if (notification.data?.maisonId) {
          navigation.navigate('MaisonDetail', { maisonId: notification.data.maisonId });
        }
        break;
      default:
        break;
    }
  };

  const getNotificationIcon = (type) => {
    switch (type) {
      case 'message':
        return { icon: 'envelope', color: '#2196F3' };
      case 'like':
        return { icon: 'heart', color: '#FF3B30' };
      case 'comment':
        return { icon: 'comment', color: '#4CAF50' };
      case 'alert':
        return { icon: 'bell', color: '#9C27B0' };
      case 'reminder':
        return { icon: 'calendar', color: '#FF9800' };
      case 'payment':
        return { icon: 'credit-card', color: '#00C853' };
      default:
        return { icon: 'info', color: '#666' };
    }
  };

  const formatDate = (dateString) => {
    if (!dateString) return '';
    const date = new Date(dateString);
    const now = new Date();
    const diffMs = now - date;
    const diffMins = Math.floor(diffMs / 60000);
    const diffHours = Math.floor(diffMs / 3600000);
    const diffDays = Math.floor(diffMs / 86400000);

    if (diffMins < 1) return 'À l\'instant';
    if (diffMins < 60) return `Il y a ${diffMins} min`;
    if (diffHours < 24) return `Il y a ${diffHours} h`;
    if (diffDays < 7) return `Il y a ${diffDays} j`;
    if (diffDays < 30) return `Il y a ${Math.floor(diffDays/7)} sem`;
    
    return date.toLocaleDateString('fr-FR', { day: 'numeric', month: 'short' });
  };

  const renderNotificationItem = ({ item }) => {
    const icon = getNotificationIcon(item.type);

    return (
      <TouchableOpacity
        style={[
          styles.notificationCard,
          !item.is_read && styles.unreadNotification
        ]}
        onPress={() => handleNotificationPress(item)}
        activeOpacity={0.7}
      >
        <View style={[
          styles.notificationIconContainer,
          { backgroundColor: `${icon.color}15` }
        ]}>
          <FontAwesome name={icon.icon} size={22} color={icon.color} />
        </View>

        <View style={styles.notificationContent}>
          <View style={styles.notificationHeader}>
            <Text style={styles.notificationTitle} numberOfLines={1}>
              {item.title}
            </Text>
            <Text style={styles.notificationTime}>
              {formatDate(item.created_at)}
            </Text>
          </View>
          <Text style={styles.notificationBody} numberOfLines={3}>
            {item.body}
          </Text>
        </View>

        {!item.is_read && <View style={styles.unreadDot} />}
      </TouchableOpacity>
    );
  };

  const renderEmptyState = () => (
    <View style={styles.emptyContainer}>
      <Ionicons name="notifications-off-outline" size={70} color={theme.subText} />
      <Text style={styles.emptyTitle}>Aucune notification</Text>
      <Text style={styles.emptyText}>
        {!user ? 'Connectez-vous pour voir vos notifications' : 'Vous êtes à jour !'}
      </Text>
      {!user && (
        <TouchableOpacity 
          style={styles.loginButton}
          onPress={() => navigation.navigate('LoginScreen')}
        >
          <Text style={styles.loginButtonText}>Se connecter</Text>
        </TouchableOpacity>
      )}
    </View>
  );

  const renderLoading = () => (
    <View style={styles.loadingContainer}>
      <ActivityIndicator size="large" color={theme.primary} />
      <Text style={styles.loadingText}>Chargement des notifications...</Text>
    </View>
  );

  const unreadCount = Array.isArray(notifications) ? notifications.filter(n => !n.is_read).length : 0;

  if (loading) {
    return (
      <SafeAreaView style={styles.container}>
        <StatusBar barStyle={isDarkMode ? 'light-content' : 'dark-content'} backgroundColor={theme.background} translucent />
        <View style={styles.header}>
          <Text style={styles.headerTitle}>Notifications</Text>
        </View>
        {renderLoading()}
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView style={styles.container}>
      <StatusBar barStyle={isDarkMode ? 'light-content' : 'dark-content'} backgroundColor={theme.background} translucent />
      
      <View style={styles.header}>
        <View style={styles.headerTitleContainer}>
          <Text style={styles.headerTitle}>Notifications</Text>
          {unreadCount > 0 && (
            <View style={styles.unreadCountBadge}>
              <Text style={styles.unreadCountText}>{unreadCount}</Text>
            </View>
          )}
        </View>
        
        <View style={styles.headerActions}>
          {notifications.length > 0 && unreadCount > 0 && (
            <TouchableOpacity style={styles.actionButton} onPress={markAllAsRead}>
              <FontAwesome name="check-double" size={18} color={theme.primary} />
              <Text style={styles.actionButtonText}>Tout lire</Text>
            </TouchableOpacity>
          )}
          {notifications.length > 0 && (
            <TouchableOpacity style={styles.actionButton} onPress={clearAllNotifications}>
              <FontAwesome name="trash" size={18} color={theme.error} />
              <Text style={[styles.actionButtonText, { color: theme.error }]}>Vider</Text>
            </TouchableOpacity>
          )}
        </View>
      </View>

      {notifications.length > 0 ? (
        <FlatList
          data={notifications}
          keyExtractor={(item) => item.id.toString()}
          renderItem={renderNotificationItem}
          contentContainerStyle={styles.notificationsList}
          showsVerticalScrollIndicator={false}
          refreshControl={
            <RefreshControl
              refreshing={refreshing}
              onRefresh={onRefresh}
              colors={[theme.primary]}
              tintColor={theme.primary}
            />
          }
        />
      ) : (
        <View style={styles.mainContainer}>
          {renderEmptyState()}
        </View>
      )}
    </SafeAreaView>
  );
};

const themedStyles = (theme, isDarkMode, Platform, StatusBar) => StyleSheet.create({
  container: {  // ← AJOUTER CE NOM DE STYLE
    flex: 1,
    backgroundColor: theme.background,
    paddingTop: Platform.OS === 'android' ? StatusBar.currentHeight : 0,
  },
  header: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'space-between',
    paddingHorizontal: 15,
    paddingVertical: 15,
    backgroundColor: theme.card,
    borderBottomWidth: 1,
    borderBottomColor: theme.border,
  },
  headerTitleContainer: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  headerTitle: {
    fontSize: 22,
    fontWeight: 'bold',
    color: theme.primary,
    marginRight: 10,
  },
  unreadCountBadge: {
    backgroundColor: theme.error,
    width: 24,
    height: 24,
    borderRadius: 12,
    justifyContent: 'center',
    alignItems: 'center',
  },
  unreadCountText: {
    color: '#fff',
    fontSize: 12,
    fontWeight: 'bold',
  },
  headerActions: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  actionButton: {
    alignItems: 'center',
    marginLeft: 15,
  },
  actionButtonText: {
    fontSize: 10,
    color: theme.primary,
    marginTop: 2,
    fontWeight: '500',
  },
  notificationsList: {
    paddingHorizontal: 15,
    paddingTop: 10,
    paddingBottom: 20,
  },
  notificationCard: {
    flexDirection: 'row',
    backgroundColor: theme.card,
    marginBottom: 12,
    padding: 15,
    borderRadius: 12,
    elevation: 2,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 1 },
    shadowOpacity: 0.1,
    shadowRadius: 3,
  },
  unreadNotification: {
    backgroundColor: theme.primary ,
    borderLeftWidth: 3,
    borderLeftColor: theme.primary,
  },
  notificationIconContainer: {
    width: 50,
    height: 50,
    borderRadius: 25,
    justifyContent: 'center',
    alignItems: 'center',
    marginRight: 15,
  },
  notificationContent: {
    flex: 1,
  },
  notificationHeader: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'flex-start',
    marginBottom: 5,
  },
  notificationTitle: {
    fontSize: 16,
    fontWeight: 'bold',
    color: theme.text,
    flex: 1,
    marginRight: 10,
  },
  notificationTime: {
    fontSize: 12,
    color: theme.subText,
  },
  notificationBody: {
    fontSize: 14,
    color: theme.subText,
    lineHeight: 20,
  },
  unreadDot: {
    width: 10,
    height: 10,
    borderRadius: 5,
    backgroundColor: theme.primary,
    marginLeft: 10,
    alignSelf: 'center',
  },
  loadingContainer: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
  },
  loadingText: {
    marginTop: 15,
    color: theme.subText,
    fontSize: 16,
  },
  emptyContainer: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    paddingHorizontal: 40,
  },
  emptyTitle: {
    fontSize: 22,
    fontWeight: 'bold',
    color: theme.subText,
    marginTop: 20,
    marginBottom: 10,
  },
  emptyText: {
    fontSize: 16,
    color: theme.subText,
    textAlign: 'center',
    marginBottom: 30,
    lineHeight: 22,
  },
  loginButton: {
    backgroundColor: theme.primary,
    paddingHorizontal: 35,
    paddingVertical: 14,
    borderRadius: 10,
  },
  loginButtonText: {
    color: '#fff',
    fontSize: 16,
    fontWeight: 'bold',
  },
  mainContainer: {
    flex: 1,
  },
});

export default NotificationsScreen;



