// AddProperty.js - Ajout d'un bien immobilier
import React, { useState } from 'react';
import { Platform, StatusBar, 
  View,
  Text,
  StyleSheet,
  ScrollView,
  TextInput,
  TouchableOpacity,
  Alert,
  ActivityIndicator
} from 'react-native';
import Ionicons from 'react-native-vector-icons/Ionicons';
import AsyncStorage from '@react-native-async-storage/async-storage';
import axios from 'axios';
import Config from './Config';
import { useTheme } from '../context/ThemeContext.js';
import { useThemedStyles } from '../hooks/useThemedStyles.js';

const AddProperty = ({ navigation }) => {
  const { isDarkMode } = useTheme();
  const { createThemedStyles, theme } = useThemedStyles();
  const styles = createThemedStyles(themedStyles);
  
  const [formData, setFormData] = useState({
    title: '',
    description: '',
    price: '',
    area: '',
    location: '',
    bedrooms: '',
    bathrooms: '',
    status: 'available'
  });
  const [loading, setLoading] = useState(false);

  const handleSubmit = async () => {
    if (!formData.title || !formData.price || !formData.location) {
      Alert.alert('Erreur', 'Veuillez remplir tous les champs obligatoires');
      return;
    }

    setLoading(true);
    try {
      const token = await AsyncStorage.getItem('access_token');
      await axios.post(`${Config.BASE_URL}/api/properties/create/`, formData, {
        headers: { Authorization: `Bearer ${token}` }
      });
      
      Alert.alert('Succès', 'Bien ajouté avec succès', [
        { text: 'OK', onPress: () => navigation.goBack() }
      ]);
    } catch (error) {
      Alert.alert('Erreur', 'Impossible d\'ajouter le bien');
    } finally {
      setLoading(false);
    }
  };

  return (
    <ScrollView style={[styles.container, isDarkMode && styles.darkContainer]}>
      <View style={styles.header}>
        <TouchableOpacity onPress={() => navigation.goBack()}>
          <Ionicons name="arrow-back" size={24} color={theme.text} />
        </TouchableOpacity>
        <Text style={[styles.headerTitle, isDarkMode && styles.darkText]}>Ajouter un bien</Text>
        <View style={{ width: 24 }} />
      </View>

      <View style={styles.form}>
        <View style={styles.formGroup}>
          <Text style={[styles.label, isDarkMode && styles.darkText]}>Titre *</Text>
          <TextInput
            style={[styles.input, isDarkMode && styles.darkCard, isDarkMode && styles.darkText]}
            placeholder="Ex: Appartement F3 à Dakar"
            placeholderTextColor={theme.subText}
            value={formData.title}
            onChangeText={(text) => setFormData({...formData, title: text})}
          />
        </View>

        <View style={styles.formGroup}>
          <Text style={[styles.label, isDarkMode && styles.darkText]}>Prix (FCFA) *</Text>
          <TextInput
            style={[styles.input, isDarkMode && styles.darkCard, isDarkMode && styles.darkText]}
            placeholder="Ex: 250000"
            placeholderTextColor={theme.subText}
            keyboardType="numeric"
            value={formData.price}
            onChangeText={(text) => setFormData({...formData, price: text})}
          />
        </View>

        <View style={styles.formGroup}>
          <Text style={[styles.label, isDarkMode && styles.darkText]}>Localisation *</Text>
          <TextInput
            style={[styles.input, isDarkMode && styles.darkCard, isDarkMode && styles.darkText]}
            placeholder="Ex: Dakar, Mermoz"
            placeholderTextColor={theme.subText}
            value={formData.location}
            onChangeText={(text) => setFormData({...formData, location: text})}
          />
        </View>

        <View style={styles.formGroup}>
          <Text style={[styles.label, isDarkMode && styles.darkText]}>Superficie (m²)</Text>
          <TextInput
            style={[styles.input, isDarkMode && styles.darkCard, isDarkMode && styles.darkText]}
            placeholder="Ex: 85"
            placeholderTextColor={theme.subText}
            keyboardType="numeric"
            value={formData.area}
            onChangeText={(text) => setFormData({...formData, area: text})}
          />
        </View>

        <View style={styles.row}>
          <View style={[styles.formGroup, { flex: 1, marginRight: 10 }]}>
            <Text style={[styles.label, isDarkMode && styles.darkText]}>Chambres</Text>
            <TextInput
              style={[styles.input, isDarkMode && styles.darkCard, isDarkMode && styles.darkText]}
              placeholder="Ex: 3"
              keyboardType="numeric"
              value={formData.bedrooms}
              onChangeText={(text) => setFormData({...formData, bedrooms: text})}
            />
          </View>
          <View style={[styles.formGroup, { flex: 1 }]}>
            <Text style={[styles.label, isDarkMode && styles.darkText]}>Salles de bain</Text>
            <TextInput
              style={[styles.input, isDarkMode && styles.darkCard, isDarkMode && styles.darkText]}
              placeholder="Ex: 2"
              keyboardType="numeric"
              value={formData.bathrooms}
              onChangeText={(text) => setFormData({...formData, bathrooms: text})}
            />
          </View>
        </View>

        <View style={styles.formGroup}>
          <Text style={[styles.label, isDarkMode && styles.darkText]}>Description</Text>
          <TextInput
            style={[styles.textArea, isDarkMode && styles.darkCard, isDarkMode && styles.darkText]}
            placeholder="Décrivez votre bien..."
            placeholderTextColor={theme.subText}
            multiline
            numberOfLines={4}
            value={formData.description}
            onChangeText={(text) => setFormData({...formData, description: text})}
          />
        </View>

        <TouchableOpacity 
          style={[styles.submitButton, loading && styles.buttonDisabled]}
          onPress={handleSubmit}
          disabled={loading}
        >
          {loading ? (
            <ActivityIndicator color="#fff" />
          ) : (
            <Text style={styles.submitButtonText}>Publier le bien</Text>
          )}
        </TouchableOpacity>
      </View>
    </ScrollView>
  );
};

const themedStyles = (theme, isDarkMode, Platform, StatusBar) => StyleSheet.create({
  container: {
          flex: 1,
          backgroundColor: theme.background,
          paddingTop: Platform.OS === 'android' ? StatusBar.currentHeight : 0,
        },
  darkContainer: { backgroundColor: '#1a1a1a' },
  darkText: { color: '#fff' },
  darkSubText: { color: '#aaa' },
  darkCard: { backgroundColor: '#2d2d2d' },
  
  header: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', padding: 20, backgroundColor: theme.card },
  headerTitle: { fontSize: 20, fontWeight: 'bold', color: theme.text },
  
  form: { padding: 20 },
  formGroup: { marginBottom: 15 },
  label: { fontSize: 14, fontWeight: '600', color: theme.text, marginBottom: 8 },
  input: { backgroundColor: theme.card, borderRadius: 10, padding: 12, fontSize: 16, borderWidth: 1, borderColor: theme.border },
  textArea: { backgroundColor: theme.card, borderRadius: 10, padding: 12, fontSize: 16, minHeight: 100, textAlignVertical: 'top', borderWidth: 1, borderColor: theme.border },
  row: { flexDirection: 'row' },
  
  submitButton: { backgroundColor: theme.primary, padding: 15, borderRadius: 10, alignItems: 'center', marginTop: 20 },
  buttonDisabled: { opacity: 0.6 },
  submitButtonText: { color: '#fff', fontSize: 16, fontWeight: 'bold' },
});

export default AddProperty;


