import React, { useState, useEffect, useCallback } from 'react';
import {
  StyleSheet,
  View,
  TextInput,
  FlatList,
  TouchableOpacity,
  Text,
  Image,
  ActivityIndicator,
  Alert,
  Keyboard,
  RefreshControl,
  Platform,
  SafeAreaView,
  StatusBar,
} from 'react-native';
import { useNavigation } from '@react-navigation/native';
import FontAwesome from 'react-native-vector-icons/FontAwesome';
import Ionicons from 'react-native-vector-icons/Ionicons';
import MaterialIcons from 'react-native-vector-icons/MaterialIcons';
import AsyncStorage from '@react-native-async-storage/async-storage';
import axios from 'axios';
import Config from './Config';
import { debounce } from 'lodash';
import { useTheme } from '../context/ThemeContext.js';
import { useThemedStyles } from '../hooks/useThemedStyles.js';

const SearchUsersScreen = () => {
  const navigation = useNavigation();
  const { isDarkMode } = useTheme();
  const { createThemedStyles, theme } = useThemedStyles();
  const styles = createThemedStyles(themedStyles);

  const [searchQuery, setSearchQuery] = useState('');
  const [users, setUsers] = useState([]);
  const [filteredUsers, setFilteredUsers] = useState([]);
  const [loading, setLoading] = useState(false);
  const [refreshing, setRefreshing] = useState(false);
  const [token, setToken] = useState('');
  const [recentSearches, setRecentSearches] = useState([]);
  const [searchHistory, setSearchHistory] = useState([]);

  // Charger le token et l'historique de recherche
  useEffect(() => {
    const loadData = async () => {
      const userToken = await AsyncStorage.getItem('userToken');
      setToken(userToken);

      const history = await AsyncStorage.getItem('userSearchHistory');
      if (history) {
        setSearchHistory(JSON.parse(history));
      }

      const recents = await AsyncStorage.getItem('recentUserSearches');
      if (recents) {
        setRecentSearches(JSON.parse(recents));
      }
    };

    loadData();
  }, []);

  // Fonction de recherche débouncée
  const debouncedSearch = useCallback(
    debounce(async (query) => {
      if (query.trim().length >= 2) {
        await searchUsers(query);
      } else {
        setFilteredUsers([]);
      }
    }, 500),
    [token]
  );

  // Effet pour déclencher la recherche
  useEffect(() => {
    debouncedSearch(searchQuery);
    return () => {
      debouncedSearch.cancel();
    };
  }, [searchQuery, debouncedSearch]);

  const searchUsers = async (query) => {
    if (!query.trim() || !token) return;

    try {
      setLoading(true);

      const endpoints = [
        `${Config.BASE_URL}/users/search/?q=${encodeURIComponent(query)}`,
        `${Config.BASE_URL}/users/?search=${encodeURIComponent(query)}`,
        `${Config.BASE_URL}/users/`
      ];

      let searchResults = [];

      for (const endpoint of endpoints) {
        try {
          const response = await axios.get(endpoint, {
            headers: { Authorization: `Bearer ${token}` },
          });

          if (response.data && Array.isArray(response.data)) {
            if (endpoint.includes('search') || endpoint.includes('?q=')) {
              searchResults = response.data;
            } else {
              searchResults = response.data.filter(user =>
                user.username?.toLowerCase().includes(query.toLowerCase()) ||
                user.email?.toLowerCase().includes(query.toLowerCase())
              );
            }
            break;
          }
        } catch (error) {
          console.log(`Endpoint ${endpoint} failed:`, error.message);
          continue;
        }
      }

      setUsers(searchResults);
      setFilteredUsers(searchResults);

      if (searchResults.length > 0) {
        await saveToSearchHistory(query);
      }

    } catch (error) {
      console.error('Erreur recherche utilisateurs:', error);
      Alert.alert('Erreur', 'Impossible de rechercher des utilisateurs');
    } finally {
      setLoading(false);
    }
  };

  const saveToSearchHistory = async (query) => {
    if (!query.trim()) return;

    const newSearch = {
      query,
      timestamp: new Date().toISOString(),
    };

    const updatedHistory = [newSearch, ...searchHistory.filter(item => item.query !== query)].slice(0, 20);
    setSearchHistory(updatedHistory);
    await AsyncStorage.setItem('userSearchHistory', JSON.stringify(updatedHistory));

    const updatedRecentSearches = [
      { query, timestamp: new Date().toISOString() },
      ...recentSearches.filter(item => item.query !== query)
    ].slice(0, 5);

    setRecentSearches(updatedRecentSearches);
    await AsyncStorage.setItem('recentUserSearches', JSON.stringify(updatedRecentSearches));
  };

  const clearSearch = () => {
    setSearchQuery('');
    setFilteredUsers([]);
    Keyboard.dismiss();
  };

  const onRefresh = useCallback(async () => {
    setRefreshing(true);
    if (searchQuery.trim()) {
      await searchUsers(searchQuery);
    }
    setRefreshing(false);
  }, [searchQuery, token]);

  const handleUserPress = (user) => {
    navigation.navigate('ProfilScreen', {
      userId: user.id,
      userName: user.username,
      userData: user
    });
    saveToSearchHistory(user.username);
  };

  const handleSearchFromHistory = (query) => {
    setSearchQuery(query);
  };

  const clearSearchHistory = async () => {
    Alert.alert(
      'Effacer l\'historique',
      'Voulez-vous vraiment effacer tout l\'historique de recherche ?',
      [
        { text: 'Annuler', style: 'cancel' },
        {
          text: 'Effacer',
          style: 'destructive',
          onPress: async () => {
            setRecentSearches([]);
            setSearchHistory([]);
            await AsyncStorage.removeItem('userSearchHistory');
            await AsyncStorage.removeItem('recentUserSearches');
          },
        },
      ]
    );
  };

  const renderUserItem = ({ item }) => (
    <TouchableOpacity
      style={styles.userItem}
      onPress={() => handleUserPress(item)}
      activeOpacity={0.7}
    >
      <View style={styles.userAvatarContainer}>
        {item.avatar ? (
          <Image source={{ uri: item.avatar }} style={styles.userAvatar} />
        ) : (
          <View style={[styles.userAvatarPlaceholder, { backgroundColor: getAvatarColor(item.username) }]}>
            <Text style={styles.avatarInitials}>
              {getInitials(item.username)}
            </Text>
          </View>
        )}

        {item.is_verified_demarcheur && (
          <View style={styles.verifiedBadge}>
            <FontAwesome name="check-circle" size={12} color="#fff" />
          </View>
        )}
      </View>

      <View style={styles.userInfo}>
        <View style={styles.userNameRow}>
          <Text style={styles.userName} numberOfLines={1}>
            {item.username}
          </Text>
          {item.user_type === 'demarcheur' && (
            <View style={[
              styles.userTypeBadge,
              item.is_verified_demarcheur ? styles.verifiedBadgeStyle : styles.demarcheurBadge
            ]}>
              <Text style={styles.userTypeText}>
                {item.is_verified_demarcheur ? '✓ Vérifié' : 'Démarcheur'}
              </Text>
            </View>
          )}
        </View>

        {item.email && (
          <Text style={styles.userEmail} numberOfLines={1}>
            {item.email}
          </Text>
        )}

        {item.bio && (
          <Text style={styles.userBio} numberOfLines={2}>
            {item.bio}
          </Text>
        )}

        <View style={styles.userStats}>
          {item.user_type && (
            <View style={styles.statItem}>
              <FontAwesome name="user" size={12} color={isDarkMode ? '#aaa' : '#666'} />
              <Text style={styles.statText}>
                {item.user_type === 'demarcheur' ? 'Démarcheur' : 'Visiteur'}
              </Text>
            </View>
          )}

          {item.city && (
            <View style={styles.statItem}>
              <FontAwesome name="map-marker" size={12} color={isDarkMode ? '#aaa' : '#666'} />
              <Text style={styles.statText}>{item.city}</Text>
            </View>
          )}
        </View>
      </View>

      <FontAwesome name="chevron-right" size={16} color={isDarkMode ? '#555' : '#ccc'} />
    </TouchableOpacity>
  );

  const renderRecentSearchItem = ({ item }) => (
    <TouchableOpacity
      style={styles.recentSearchItem}
      onPress={() => handleSearchFromHistory(item.query)}
      activeOpacity={0.7}
    >
      <FontAwesome name="history" size={16} color={isDarkMode ? '#aaa' : '#666'} style={styles.recentSearchIcon} />
      <Text style={styles.recentSearchText} numberOfLines={1}>
        {item.query}
      </Text>
      <Text style={styles.recentSearchTime}>
        {formatTimeAgo(item.timestamp)}
      </Text>
    </TouchableOpacity>
  );

  const getInitials = (name) => {
    if (!name) return '??';
    return name
      .split(' ')
      .map(part => part[0])
      .join('')
      .toUpperCase()
      .substring(0, 2);
  };

  const getAvatarColor = (name) => {
    const colors = [
      '#6C63FF', '#FF6B9D', '#4CAF50', '#2196F3',
      '#FF9800', '#9C27B0', '#00BCD4', '#795548'
    ];
    const index = name ? name.charCodeAt(0) % colors.length : 0;
    return colors[index];
  };

  const formatTimeAgo = (timestamp) => {
    const now = new Date();
    const past = new Date(timestamp);
    const diffInMinutes = Math.floor((now - past) / (1000 * 60));

    if (diffInMinutes < 1) return 'À l\'instant';
    if (diffInMinutes < 60) return `Il y a ${diffInMinutes} min`;
    if (diffInMinutes < 1440) return `Il y a ${Math.floor(diffInMinutes / 60)} h`;
    if (diffInMinutes < 10080) return `Il y a ${Math.floor(diffInMinutes / 1440)} j`;
    return past.toLocaleDateString('fr-FR', { day: 'numeric', month: 'short' });
  };

  const renderEmptyState = () => {
    if (loading) return null;

    if (searchQuery.trim().length >= 2) {
      return (
        <View style={styles.emptyState}>
          <FontAwesome name="user-times" size={60} color={isDarkMode ? '#444' : '#E0E0E0'} />
          <Text style={styles.emptyStateTitle}>Aucun utilisateur trouvé</Text>
          <Text style={styles.emptyStateText}>
            Aucun utilisateur ne correspond à "{searchQuery}"
          </Text>
        </View>
      );
    }

    return (
      <View style={styles.emptyState}>
        <FontAwesome name="search" size={60} color={isDarkMode ? '#444' : '#E0E0E0'} />
        <Text style={styles.emptyStateTitle}>Rechercher des utilisateurs</Text>
        <Text style={styles.emptyStateText}>
          Tapez un nom, email ou pseudonyme pour rechercher des utilisateurs
        </Text>

        {recentSearches.length > 0 && (
          <View style={styles.recentSearchesSection}>
            <View style={styles.recentSearchesHeader}>
              <Text style={styles.recentSearchesTitle}>Recherches récentes</Text>
              <TouchableOpacity onPress={clearSearchHistory}>
                <Text style={styles.clearHistoryText}>Effacer</Text>
              </TouchableOpacity>
            </View>
            <FlatList
              data={recentSearches}
              keyExtractor={(item, index) => `recent-${index}`}
              renderItem={renderRecentSearchItem}
              scrollEnabled={false}
            />
          </View>
        )}
      </View>
    );
  };

  return (
    <SafeAreaView style={styles.container}>
      <StatusBar barStyle={isDarkMode ? 'light-content' : 'dark-content'} backgroundColor={theme.background} translucent />

      <View style={styles.header}>
        <TouchableOpacity
          style={styles.backButton}
          onPress={() => navigation.goBack()}
        >
          <Ionicons name="arrow-back" size={24} color={isDarkMode ? '#fff' : '#052c65'} />
        </TouchableOpacity>

        <View style={styles.searchContainer}>
          <FontAwesome name="search" size={18} color={isDarkMode ? '#aaa' : '#666'} style={styles.searchIcon} />
          <TextInput
            style={styles.searchInput}
            placeholder="Rechercher un utilisateur..."
            placeholderTextColor={isDarkMode ? '#666' : '#999'}
            value={searchQuery}
            onChangeText={setSearchQuery}
            autoFocus
            returnKeyType="search"
            onSubmitEditing={() => searchUsers(searchQuery)}
            clearButtonMode="while-editing"
          />

          {searchQuery.length > 0 && (
            <TouchableOpacity onPress={clearSearch} style={styles.clearButton}>
              <FontAwesome name="times-circle" size={18} color={isDarkMode ? '#aaa' : '#666'} />
            </TouchableOpacity>
          )}
        </View>
      </View>

      {loading && filteredUsers.length === 0 ? (
        <View style={styles.loadingContainer}>
          <ActivityIndicator size="large" color={theme.primary || '#052c65'} />
          <Text style={styles.loadingText}>Recherche en cours...</Text>
        </View>
      ) : (
        <FlatList
          data={filteredUsers}
          keyExtractor={(item) => item.id.toString()}
          renderItem={renderUserItem}
          ListEmptyComponent={renderEmptyState}
          refreshControl={
            <RefreshControl
              refreshing={refreshing}
              onRefresh={onRefresh}
              colors={[theme.primary || '#052c65']}
              tintColor={theme.primary || '#052c65'}
            />
          }
          contentContainerStyle={styles.listContent}
          ItemSeparatorComponent={() => <View style={styles.separator} />}
          ListHeaderComponent={
            filteredUsers.length > 0 ? (
              <View style={styles.resultsHeader}>
                <Text style={styles.resultsCount}>
                  {filteredUsers.length} utilisateur{filteredUsers.length > 1 ? 's' : ''} trouvé{filteredUsers.length > 1 ? 's' : ''}
                </Text>
              </View>
            ) : null
          }
          keyboardShouldPersistTaps="handled"
        />
      )}
    </SafeAreaView>
  );
};

