import React, { useEffect, useState, useRef } from 'react';
import { 
  View, 
  Text, 
  Image,
  StatusBar,
  RefreshControl,
  TouchableOpacity, 
  FlatList, 
  Alert, 
  SafeAreaView, 
  StyleSheet,
  Modal,
  BackHandler,
  TextInput,
  KeyboardAvoidingView,
  Platform,
  Keyboard,
  Share,
  Linking,
  ActivityIndicator,
  Dimensions
} from 'react-native';
import axios from 'axios';
import { createMaterialTopTabNavigator } from '@react-navigation/material-top-tabs';
import FontAwesome from 'react-native-vector-icons/FontAwesome';
import Ionicons from 'react-native-vector-icons/Ionicons';
import Video from 'react-native-video';
import AsyncStorage from '@react-native-async-storage/async-storage';
import AppBar from './AppBar';
import Config from './Config';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { useTheme } from '../context/ThemeContext.js';
import { useThemedStyles } from '../hooks/useThemedStyles';

const { width } = Dimensions.get('window');
const Tab = createMaterialTopTabNavigator();

const MaisonList = ({ navigation }) => {
  const insets = useSafeAreaInsets();
  const { isDarkMode } = useTheme();
  const { createThemedStyles, theme } = useThemedStyles();
  const styles = createThemedStyles(themedStyles);
  
  const [maisons, setMaisons] = useState([]);
  const [user, setUser] = useState(null);
  const [favorites, setFavorites] = useState({});
  const [likes, setLikes] = useState({});
  const [isOpen, setIsOpen] = useState(false);
  const [selectedMaison, setSelectedMaison] = useState(null);
  const [commentText, setCommentText] = useState('');
  const [isCommenting, setIsCommenting] = useState(false);
  const [currentMaisonId, setCurrentMaisonId] = useState(null);
  const [comments, setComments] = useState({});
  const [isLoading, setIsLoading] = useState(true);
  const [page, setPage] = useState(1);
  const [hasMore, setHasMore] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [userAvatar, setUserAvatar] = useState(null);
  const [currentImageIndexes, setCurrentImageIndexes] = useState({});
  
  const commentInputRef = useRef();

  useEffect(() => {
    const fetchUserData = async () => {
      try {
        const userData = await AsyncStorage.getItem('user');
        if (userData) {
          const parsedUser = JSON.parse(userData);
          setUser(parsedUser);
          setUserAvatar(parsedUser?.avatar || null);
        }
      } catch (error) {
        console.error('Erreur lors de la récupération des données utilisateur:', error);
      }
    };

    fetchUserData();
  }, []);

  const fetchMaisons = async (pageNum = 1, refresh = false) => {
    try {
      if (refresh) {
        setRefreshing(true);
      } else if (pageNum === 1) {
        setIsLoading(true);
      }

      const response = await axios.get(`${Config.BASE_URL}/maisons/?page=${pageNum}`);
      
      const maisonsData = response.data.results || response.data;
      
      const transformedData = maisonsData.map(maison => ({
        ...maison,
        media: [
          ...(maison.photos || []).map(photo => ({ 
            ...photo, 
            type: 'photo',
            url: photo.photos 
          })),
          ...(maison.videos || []).map(video => ({ 
            ...video, 
            type: 'video',
            url: video.video 
          }))
        ],
        liked: maison.is_liked || false,
        favorited: false
      }));
      
      if (refresh || pageNum === 1) {
        setMaisons(transformedData);
        setPage(1);
      } else {
        setMaisons(prev => [...prev, ...transformedData]);
      }
      
      const initialLikes = {};
      const initialFavorites = {};
      transformedData.forEach(maison => {
        initialLikes[maison.id] = maison.liked || false;
        initialFavorites[maison.id] = false;
      });
      
      setLikes(prev => ({ ...prev, ...initialLikes }));
      setFavorites(prev => ({ ...prev, ...initialFavorites }));
      
      setHasMore(response.data.next ? true : false);
      
    } catch (error) {
      console.error('Erreur lors du fetch des maisons:', error);
    } finally {
      setIsLoading(false);
      setRefreshing(false);
    }
  };

  useEffect(() => {
    fetchMaisons(1);

    const backHandler = BackHandler.addEventListener('hardwareBackPress', () => {
      if (isOpen) {
        setIsOpen(false);
        return true;
      }
      if (isCommenting) {
        cancelComment();
        return true;
      }
      return false;
    });

    return () => backHandler.remove();
  }, []);

  const loadMore = () => {
    if (!isLoading && hasMore) {
      const nextPage = page + 1;
      setPage(nextPage);
      fetchMaisons(nextPage);
    }
  };

  const onRefresh = () => {
    fetchMaisons(1, true);
  };

  const onScrollEnd = (e, maisonId, mediaLength) => {
    const index = Math.round(e.nativeEvent.contentOffset.x / width);
    setCurrentImageIndexes(prev => ({ ...prev, [maisonId]: index }));
  };

  const fetchCommentsForMaison = async (maisonId) => {
    try {
      const response = await axios.get(`${Config.BASE_URL}/maisons/${maisonId}/commentaires/`);
      setComments(prev => ({ ...prev, [maisonId]: response.data }));
    } catch (error) {
      console.log(`Pas de commentaires pour la maison ${maisonId}:`, error.message);
      setComments(prev => ({ ...prev, [maisonId]: [] }));
    }
  };

  const toggleFavorite = async (maisonId) => {
    try {
      const token = await AsyncStorage.getItem('access_token');
      
      if (!token) {
        Alert.alert('Connexion requise', 'Veuillez vous connecter pour ajouter aux favoris');
        return;
      }
      
      await axios.post(
        `${Config.BASE_URL}/maisons/${maisonId}/favori/`,
        {},
        {
          headers: { 'Authorization': `Bearer ${token}` }
        }
      );
      
      setFavorites(prev => ({ ...prev, [maisonId]: !prev[maisonId] }));
      
    } catch (error) {
      console.error('Erreur favori:', error);
      Alert.alert('Erreur', 'Impossible de modifier les favoris');
    }
  };

  const handleLike = async (maisonId) => {
    try {
      const token = await AsyncStorage.getItem('access_token');
      
      if (!token) {
        Alert.alert('Connexion requise', 'Veuillez vous connecter pour liker');
        return;
      }
      
      await axios.post(
        `${Config.BASE_URL}/maisons/${maisonId}/like/`,
        {},
        {
          headers: { 'Authorization': `Bearer ${token}` }
        }
      );
      
      setLikes(prev => ({ 
        ...prev, 
        [maisonId]: !prev[maisonId] 
      }));
      
    } catch (error) {
      console.error('Erreur like:', error);
      Alert.alert('Erreur', 'Impossible de modifier le like');
    }
  };

  const handleShare = async (maison) => {
    try {
      const shareOptions = {
        message: `🏠 ${maison.titre || 'Belle propriété'}\n📍 ${maison.ville}, ${maison.quartier}\n💰 ${maison.prix} FCFA\n\n${maison.description?.substring(0, 100)}...\n\nTéléchargez l'application Villana pour plus de détails!`,
        title: 'Partager cette propriété',
        url: `${Config.BASE_URL}/maisons/${maison.id}/`
      };

      const result = await Share.share(shareOptions);
      
      if (result.action === Share.sharedAction) {
        console.log('Partagé avec succès');
      }
    } catch (error) {
      console.error('Erreur de partage:', error);
      Alert.alert('Erreur', 'Impossible de partager');
    }
  };

  const showMaisonDetails = (maison) => {
    navigation.navigate('MaisonDetail', { maisonId: maison.id, maison: maison });
  };

  const openCommentInput = async (maisonId) => {
    const token = await AsyncStorage.getItem('access_token');
    if (!token) {
      Alert.alert('Connexion requise', 'Veuillez vous connecter pour commenter');
      return;
    }
    
    setCurrentMaisonId(maisonId);
    setIsCommenting(true);
    setCommentText('');
    
    if (!comments[maisonId]) {
      await fetchCommentsForMaison(maisonId);
    }
    
    setTimeout(() => {
      commentInputRef.current?.focus();
    }, 100);
  };

  const cancelComment = () => {
    setIsCommenting(false);
    setCommentText('');
    setCurrentMaisonId(null);
    Keyboard.dismiss();
  };

  const submitComment = async () => {
    if (!commentText.trim() || !currentMaisonId) {
      Alert.alert('Erreur', 'Veuillez saisir un commentaire');
      return;
    }

    try {
      const token = await AsyncStorage.getItem('access_token');
      if (!token) {
        Alert.alert('Connexion requise', 'Veuillez vous connecter pour commenter');
        return;
      }

      const response = await axios.post(
        `${Config.BASE_URL}/maisons/${currentMaisonId}/commenter/`,
        {
          texte: commentText.trim()
        },
        {
          headers: {
            'Authorization': `Bearer ${token}`,
            'Content-Type': 'application/json'
          }
        }
      );

      const newComment = {
        ...response.data,
        user_name: user?.username || 'Utilisateur',
        user_avatar: user?.avatar
      };

      setComments(prev => ({
        ...prev,
        [currentMaisonId]: [newComment, ...(prev[currentMaisonId] || [])]
      }));

      setCommentText('');
      Keyboard.dismiss();
      Alert.alert('Succès', 'Commentaire publié');
      
    } catch (error) {
      console.error('Erreur commentaire:', error);
      Alert.alert('Erreur', 'Impossible de poster le commentaire');
    }
  };

  const renderCommentItem = ({ item }) => (
    <View style={[styles.commentItem, isDarkMode && styles.darkCard]}>
      <View style={styles.commentHeader}>
        {item.user_avatar ? (
          <Image source={{ uri: item.user_avatar }} style={styles.commentAvatar} />
        ) : (
          <View style={[styles.commentAvatar, styles.defaultAvatar]}>
            <FontAwesome name="user" size={16} color="#fff" />
          </View>
        )}
        <Text style={[styles.commentUser, isDarkMode && styles.darkText]}>
          {item.user_name || 'Anonyme'}
        </Text>
      </View>
      <Text style={[styles.commentText, isDarkMode && styles.darkSubText]}>{item.texte}</Text>
      <Text style={[styles.commentDate, isDarkMode && styles.darkSubText]}>
        {new Date(item.date_creation).toLocaleDateString('fr-FR')}
      </Text>
    </View>
  );

  const RenderMaisonMemo = React.memo(({ item }) => {
    const maisonComments = comments[item.id] || [];
    const mediaLength = item.media?.length || 0;
    const currentIndex = currentImageIndexes[item.id] || 0;

    return (
      <View style={[styles.maisonContainer, isDarkMode && styles.darkCard]}>
        <View style={styles.profilContainer}>
          <View style={styles.profilContainer1}>
            <TouchableOpacity 
              style={styles.profilButton}
              onPress={() => navigation.navigate('ProfilScreen', { userId: item.owner })}
            >
              {item.owner?.avatar ? (
                <Image source={{ uri: item.owner.avatar }} style={styles.userImage} />
              ) : (
                <View style={[styles.userImage, styles.defaultAvatar]}>
                  <FontAwesome name="user" size={20} color="#fff" />
                </View>
              )}
            </TouchableOpacity>
            <View>
              <Text style={[styles.title, isDarkMode && styles.darkText]}>
                {item.owner_name || 'Propriétaire'}
              </Text>
              <Text style={[styles.location, isDarkMode && styles.darkSubText]}>
                <FontAwesome name="map-marker" size={12} color={isDarkMode ? '#aaa' : '#666'} />
                {' '}{item.ville}, {item.pays}
              </Text>
            </View>
          </View>
          <TouchableOpacity 
            style={styles.rightIcon} 
            onPress={() => toggleFavorite(item.id)}
          >
            <FontAwesome 
              name={favorites[item.id] ? "bookmark" : "bookmark-o"} 
              size={27} 
              color={favorites[item.id] ? "#FFD700" : (isDarkMode ? '#aaa' : "#052c65")} 
            />
          </TouchableOpacity>
        </View>
        
        <View style={styles.priceContainer}>
          <Text style={[styles.price, isDarkMode && { color: theme.primary }]}>{item.prix} FCFA</Text>
          <View style={[
            styles.typeBadge, 
            item.type_maison === 'vente' ? styles.saleBadge : styles.rentBadge
          ]}>
            <Text style={styles.typeText}>
              {item.type_maison === 'vente' ? 'À VENDRE' : 'À LOUER'}
            </Text>
          </View>
        </View>
        
        {/* Galerie d'images avec indicateurs à points */}
        <View style={styles.mediaContainer}>
          {item.media && item.media.length > 0 ? (
            <>
              <FlatList
                data={item.media}
                keyExtractor={(mediaItem, index) => `media_${item.id}_${index}`}
                horizontal
                pagingEnabled
                showsHorizontalScrollIndicator={false}
                onMomentumScrollEnd={(e) => onScrollEnd(e, item.id, mediaLength)}
                renderItem={({ item: mediaItem }) => (
                  <TouchableOpacity 
                    style={styles.mediaItem}
                    onPress={() => navigation.navigate('MaisonDetail', { maisonId: item.id, maison: item })}
                    activeOpacity={0.9}
                  >
                    {mediaItem.type === 'photo' ? (
                      <Image 
                        source={{ uri: mediaItem.url }} 
                        style={styles.image}
                        resizeMode="cover"
                      />
                    ) : (
                      <Video
                        source={{ uri: mediaItem.url }}
                        style={styles.video}
                        resizeMode="cover"
                        paused={true}
                        repeat={false}
                        controls={true}
                      />
                    )}
                  </TouchableOpacity>
                )}
              />
              
              {/* Indicateurs à points (dots) */}
              {mediaLength > 1 && (
                <View style={styles.dotsContainer}>
                  {item.media.map((_, idx) => (
                    <View
                      key={idx}
                      style={[
                        styles.dot,
                        currentIndex === idx && styles.dotActive,
                        currentIndex === idx && { backgroundColor: theme.primary }
                      ]}
                    />
                  ))}
                </View>
              )}
            </>
          ) : (
            <TouchableOpacity 
              style={styles.noMediaContainer}
              onPress={() => navigation.navigate('MaisonDetail', { maisonId: item.id, maison: item })}
            >
              <FontAwesome name="image" size={50} color="#ccc" />
              <Text style={styles.noMediaText}>Aucune photo disponible</Text>
            </TouchableOpacity>
          )}
        </View>
        
        <View style={[styles.infoContainer, isDarkMode && styles.darkBorder]}>
          <View style={styles.infoItem}>
            <FontAwesome name="bed" size={20} color={isDarkMode ? '#aaa' : "#052c65"} />
            <Text style={[styles.infoText, isDarkMode && styles.darkSubText]}>{item.nombre_chambres} chambres</Text>
          </View>
          <View style={styles.infoItem}>
            <FontAwesome name="bath" size={20} color={isDarkMode ? '#aaa' : "#052c65"} />
            <Text style={[styles.infoText, isDarkMode && styles.darkSubText]}>{item.nombre_salles_de_bain} sdb</Text>
          </View>
          {item.surface && (
            <View style={styles.infoItem}>
              <FontAwesome name="expand" size={20} color={isDarkMode ? '#aaa' : "#052c65"} />
              <Text style={[styles.infoText, isDarkMode && styles.darkSubText]}>{item.surface} m²</Text>
            </View>
          )}
        </View>
        
        <View style={styles.featuresContainer}>
          {item.piscine && (
            <View style={styles.featureBadge}>
              <FontAwesome name="tint" size={14} color="#00BCD4" />
              <Text style={[styles.featureBadgeText, isDarkMode && styles.darkSubText]}>Piscine</Text>
            </View>
          )}
          {item.jardin && (
            <View style={styles.featureBadge}>
              <FontAwesome name="tree" size={14} color="#4CAF50" />
              <Text style={[styles.featureBadgeText, isDarkMode && styles.darkSubText]}>Jardin</Text>
            </View>
          )}
          {item.garage && (
            <View style={styles.featureBadge}>
              <FontAwesome name="car" size={14} color="#FF9800" />
              <Text style={[styles.featureBadgeText, isDarkMode && styles.darkSubText]}>Garage</Text>
            </View>
          )}
          {item.meuble && (
            <View style={styles.featureBadge}>
              <FontAwesome name="couch" size={14} color="#795548" />
              <Text style={[styles.featureBadgeText, isDarkMode && styles.darkSubText]}>Meublé</Text>
            </View>
          )}
        </View>
        
        {maisonComments.length > 0 && (
          <View style={[styles.commentsSection, isDarkMode && styles.darkBorder]}>
            <Text style={[styles.commentsTitle, isDarkMode && styles.darkText]}>
              Commentaires ({maisonComments.length})
            </Text>
            <FlatList
              data={maisonComments.slice(0, 2)}
              keyExtractor={(comment, index) => `comment_${item.id}_${index}`}
              renderItem={renderCommentItem}
              scrollEnabled={false}
            />
            {maisonComments.length > 2 && (
              <TouchableOpacity style={styles.seeMoreButton}>
                <Text style={[styles.seeMoreText, isDarkMode && { color: theme.primary }]}>Voir tous les commentaires</Text>
                <FontAwesome name="chevron-right" size={14} color={theme.primary} />
              </TouchableOpacity>
            )}
          </View>
        )}
        
        <View style={[styles.actionsContainer, isDarkMode && styles.darkBorder]}>
          <View style={styles.leftActions}>
            <TouchableOpacity style={styles.actionButton} onPress={() => handleLike(item.id)}>
              <FontAwesome 
                name={likes[item.id] ? "heart" : "heart-o"} 
                size={24} 
                color={likes[item.id] ? "#FF3B30" : (isDarkMode ? '#aaa' : "#052c65")} 
              />
              <Text style={[styles.actionText, isDarkMode && styles.darkSubText]}>
                {likes[item.id] ? 'Aimé' : 'Like'}
              </Text>
            </TouchableOpacity>
            
            <TouchableOpacity style={styles.actionButton} onPress={() => openCommentInput(item.id)}>
              <FontAwesome name="comment-o" size={24} color={isDarkMode ? '#aaa' : "#052c65"} />
              <Text style={[styles.actionText, isDarkMode && styles.darkSubText]}>Commenter</Text>
            </TouchableOpacity>
            
            <TouchableOpacity style={styles.actionButton} onPress={() => handleShare(item)}>
              <FontAwesome name="share-alt" size={24} color={isDarkMode ? '#aaa' : "#052c65"} />
              <Text style={[styles.actionText, isDarkMode && styles.darkSubText]}>Partager</Text>
            </TouchableOpacity>
          </View>
          
          <TouchableOpacity style={[styles.contactButton, { backgroundColor: theme.primary }]} onPress={() => showMaisonDetails(item)}>
            <Text style={styles.contactButtonText}>Détails</Text>
          </TouchableOpacity>
        </View>
      </View>
    );
  });

  const renderFooter = () => {
    if (!hasMore) {
      return (
        <View style={styles.footerContainer}>
          <Text style={[styles.footerText, isDarkMode && styles.darkSubText]}>Fin des résultats</Text>
        </View>
      );
    }
    
    if (isLoading && page > 1) {
      return (
        <View style={styles.footerContainer}>
          <ActivityIndicator size="small" color={theme.primary} />
          <Text style={[styles.footerText, isDarkMode && styles.darkSubText]}>Chargement...</Text>
        </View>
      );
    }
    
    return null;
  };

  // Composants des onglets - SANS KeyboardAvoidingView
  const AllMaisonsTab = () => (
    <View style={styles.tabContainer}>
      <FlatList
        data={maisons}
        keyExtractor={item => item.id.toString()}
        renderItem={({ item }) => <RenderMaisonMemo item={item} />}
        contentContainerStyle={styles.BlogContainer}
        showsVerticalScrollIndicator={false}
        onEndReached={loadMore}
        onEndReachedThreshold={0.5}
        ListFooterComponent={renderFooter}
        refreshControl={
          <RefreshControl
            refreshing={refreshing}
            onRefresh={onRefresh}
            colors={[theme.primary]}
            tintColor={theme.primary}
          />
        }
        ListEmptyComponent={() => (
          <View style={styles.emptyContainer}>
            {isLoading ? (
              <ActivityIndicator size="large" color={theme.primary} />
            ) : (
              <>
                <FontAwesome name="home" size={60} color="#ccc" />
                <Text style={[styles.emptyTitle, isDarkMode && styles.darkText]}>Aucune maison disponible</Text>
                <Text style={[styles.emptyText, isDarkMode && styles.darkSubText]}>
                  Revenez plus tard pour découvrir de nouvelles propriétés
                </Text>
              </>
            )}
          </View>
        )}
      />
    </View>
  );

  const A_VendreTab = () => {
    const maisonsAVendre = maisons.filter(maison => maison.type_maison === 'vente');
    
    return (
      <View style={styles.tabContainer}>
        <FlatList
          data={maisonsAVendre}
          keyExtractor={item => item.id.toString()}
          renderItem={({ item }) => <RenderMaisonMemo item={item} />}
          contentContainerStyle={styles.BlogContainer}
          showsVerticalScrollIndicator={false}
          ListEmptyComponent={() => (
            <View style={styles.emptyContainer}>
              <FontAwesome name="tag" size={60} color="#ccc" />
              <Text style={[styles.emptyTitle, isDarkMode && styles.darkText]}>Aucune maison à vendre</Text>
              <Text style={[styles.emptyText, isDarkMode && styles.darkSubText]}>
                Aucune propriété n'est actuellement en vente
              </Text>
            </View>
          )}
        />
      </View>
    );
  };

  const A_LouerTab = () => {
    const maisonsALouer = maisons.filter(maison => maison.type_maison === 'location');
    
    return (
      <View style={styles.tabContainer}>
        <FlatList
          data={maisonsALouer}
          keyExtractor={item => item.id.toString()}
          renderItem={({ item }) => <RenderMaisonMemo item={item} />}
          contentContainerStyle={styles.BlogContainer}
          showsVerticalScrollIndicator={false}
          ListEmptyComponent={() => (
            <View style={styles.emptyContainer}>
              <FontAwesome name="key" size={60} color="#ccc" />
              <Text style={[styles.emptyTitle, isDarkMode && styles.darkText]}>Aucune maison à louer</Text>
              <Text style={[styles.emptyText, isDarkMode && styles.darkSubText]}>
                Aucune propriété n'est actuellement à louer
              </Text>
            </View>
          )}
        />
      </View>
    );
  };

  return (
    <SafeAreaView style={[styles.container, isDarkMode && styles.darkContainer]}>
      <View style={[styles.header, isDarkMode && styles.darkHeader]}>
        <View style={styles.headerLeft}>
          <Text style={[styles.headerTitle, isDarkMode && styles.darkText]}>Catégorie Maison</Text>
          <Image source={require('../assets/niger.png')} style={styles.flagImage} />
        </View>

        <View style={styles.headerRight}>
          <TouchableOpacity 
            style={styles.iconButton}
            onPress={() => navigation.navigate('Search')}
          >
            <FontAwesome name="search" size={20} color={isDarkMode ? '#fff' : "#052c65"} />
          </TouchableOpacity>
          <TouchableOpacity 
            style={styles.iconButton}
            onPress={() => navigation.navigate('FavoriScreen')}
          >
            <FontAwesome name="heart" size={20} color="#FF6B6B" />
          </TouchableOpacity>
          <TouchableOpacity 
            style={styles.iconButton}
            onPress={() => navigation.navigate('Menu')}
          >
            {userAvatar ? (
              <Image source={{ uri: userAvatar }} style={styles.profileImage} />
            ) : (
              <View style={[styles.profileImage, styles.defaultAvatar]}>
                <FontAwesome name="user" size={18} color="#fff" />
              </View>
            )}
          </TouchableOpacity>
        </View>
      </View>

      <Tab.Navigator
        screenOptions={{
          tabBarStyle: [styles.tabBar, isDarkMode && styles.darkTabBar],
          tabBarIndicatorStyle: [styles.tabIndicator, { backgroundColor: theme.primary }],
          tabBarLabelStyle: [styles.tabLabel],
          tabBarActiveTintColor: theme.primary,
          tabBarInactiveTintColor: isDarkMode ? '#aaa' : '#666',
        }}
      >
        <Tab.Screen 
          name="Tout" 
          component={AllMaisonsTab}
          options={{ tabBarLabel: 'Tout' }}
        />
        <Tab.Screen 
          name="À vendre" 
          component={A_VendreTab}
          options={{ tabBarLabel: 'À vendre' }}
        />
        <Tab.Screen 
          name="À louer" 
          component={A_LouerTab}
          options={{ tabBarLabel: 'À louer' }}
        />
      </Tab.Navigator>

      {isCommenting && (
        <View style={[styles.commentInputWrapper, { bottom: insets.bottom }, isDarkMode && styles.darkCommentWrapper]}>
          <TextInput
            ref={commentInputRef}
            style={[styles.commentInput, isDarkMode && styles.darkCommentInput]}
            placeholder="Écrire un commentaire..."
            placeholderTextColor={isDarkMode ? '#aaa' : '#999'}
            value={commentText}
            onChangeText={setCommentText}
            multiline
            maxLength={500}
          />
          <View style={styles.commentActions}>
            <TouchableOpacity onPress={cancelComment} style={styles.commentCancel}>
              <Text style={[styles.commentCancelText, isDarkMode && styles.darkSubText]}>Annuler</Text>
            </TouchableOpacity>
            <TouchableOpacity 
              onPress={submitComment} 
              style={[styles.commentSubmit, !commentText.trim() && styles.commentSubmitDisabled, { backgroundColor: theme.primary }]}
              disabled={!commentText.trim()}
            >
              <Text style={styles.commentSubmitText}>Envoyer</Text>
            </TouchableOpacity>
          </View>
        </View>
      )}
    </SafeAreaView>
  );
};

