import React, { useState, useEffect, useCallback } from 'react';
import {
  View,
  Text,
  StyleSheet,
  Image,
  RefreshControl,
  FlatList,
  Animated,
  TouchableOpacity,
  TextInput,
  StatusBar,
  Alert,
  Platform,
} from 'react-native';
import Ionicons from 'react-native-vector-icons/Ionicons';
import MaterialIcons from 'react-native-vector-icons/MaterialIcons';
import MaterialCommunityIcons from 'react-native-vector-icons/MaterialCommunityIcons';
import { useNavigation, useFocusEffect } from '@react-navigation/native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import axios from 'axios';
import LinearGradient from 'react-native-linear-gradient';
import Swipeable from 'react-native-gesture-handler/ReanimatedSwipeable';
import Reanimated, {
  useAnimatedStyle,
  interpolate,
  Extrapolation
} from 'react-native-reanimated';
import Config from './Config';
import { useThemedStyles } from '../hooks/useThemedStyles';

const MessageScreen = () => {
  const navigation = useNavigation();
  const [conversations, setConversations] = useState([]);
  const [filteredConversations, setFilteredConversations] = useState([]);
  const [refreshing, setRefreshing] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [loading, setLoading] = useState(true);
  const [token, setToken] = useState('');
  const { createThemedStyles } = useThemedStyles();
  const styles = createThemedStyles(themedStyles);

  useEffect(() => {
    const getToken = async () => {
      const accessToken = await AsyncStorage.getItem('access_token');
      const userToken = await AsyncStorage.getItem('userToken');
      
      console.log("🔑 access_token:", accessToken);
      console.log("🔑 userToken:", userToken);
      
      setToken(accessToken || userToken);
    };
    getToken();
  }, []);

  const loadConversations = useCallback(async () => {
    if (!token) {
      console.log("❌ Pas de token");
      return;
    }
    
    try {
      setLoading(true);
      console.log("🔍 URL appelée:", `${Config.BASE_URL}/messages/conversations/`);
      
      const response = await axios.get(`${Config.BASE_URL}/messages/conversations/`, {
        headers: { Authorization: `Bearer ${token}` },
      });
      
      console.log("✅ Réponse reçue:", response.data);
      console.log("📊 Nombre de conversations:", response.data.length);
      
      setConversations(response.data);
      setFilteredConversations(response.data);
    } catch (error) {
      console.error("❌ Erreur:", error);
      Alert.alert('Erreur', 'Impossible de charger les conversations');
    } finally {
      setLoading(false);
    }
  }, [token]);

  useFocusEffect(
    useCallback(() => {
      if (token) {
        loadConversations();
      }
    }, [loadConversations, token])
  );

  const onRefresh = useCallback(async () => {
    setRefreshing(true);
    await loadConversations();
    setRefreshing(false);
  }, [loadConversations]);

  useEffect(() => {
    if (searchQuery.trim() === '') {
      setFilteredConversations(conversations);
    } else {
      const filtered = conversations.filter(conv =>
        conv.user?.username?.toLowerCase().includes(searchQuery.toLowerCase()) ||
        conv.last_message?.text?.toLowerCase().includes(searchQuery.toLowerCase())
      );
      setFilteredConversations(filtered);
    }
  }, [searchQuery, conversations]);

  const deleteConversation = async (userId) => {
    Alert.alert(
      'Supprimer la conversation',
      'Êtes-vous sûr de vouloir supprimer cette conversation ?',
      [
        { text: 'Annuler', style: 'cancel' },
        {
          text: 'Supprimer',
          style: 'destructive',
          onPress: async () => {
            const updatedConversations = conversations.filter(conv => conv.user.id !== userId);
            setConversations(updatedConversations);
            setFilteredConversations(updatedConversations);
            Alert.alert('Succès', 'Conversation supprimée');
          },
        },
      ]
    );
  };

  const renderRightActions = (progress, dragX, userId) => {
    return (
      <View style={styles.rightActions}>
        <RightAction progress={progress} dragX={dragX} onPress={() => deleteConversation(userId)} />
      </View>
    );
  };

  const RightAction = ({ progress, dragX, onPress }) => {
    const animatedStyle = useAnimatedStyle(() => {
      const scale = interpolate(
        dragX.value,
        [-100, 0],
        [1, 0],
        Extrapolation.CLAMP
      );
      return {
        transform: [{ scale }],
      };
    });

    return (
      <TouchableOpacity
        style={[styles.actionButton, styles.deleteButton]}
        onPress={onPress}
      >
        <Reanimated.View style={animatedStyle}>
          <MaterialIcons name="delete" size={24} color="#FFF" />
        </Reanimated.View>
        <Text style={styles.actionText}>Supprimer</Text>
      </TouchableOpacity>
    );
  };

  const renderConversationItem = ({ item }) => {
    const lastMessageTime = getTimeAgo(item.last_message?.created_at);
    const isUnread = item.unread_count > 0;

    return (
      <Swipeable
        renderRightActions={(progress, dragX) =>
          renderRightActions(progress, dragX, item.user.id)
        }
        friction={2}
        rightThreshold={40}
      >
        <TouchableOpacity
          style={[styles.messageItem, isUnread && styles.unreadMessage]}
          onPress={() => {
            navigation.navigate('TextoScreen', {
              userName: item.user.username,
              userId: item.user.id,
              userAvatar: item.user.avatar,
            });
          }}
          activeOpacity={0.7}
        >
          <View style={styles.avatarContainer}>
            {/* ✅ TOUJOURS une image, soit l'avatar soit l'image par défaut */}
            <Image
              source={item.user?.avatar ? { uri: item.user.avatar } : require('../assets/profil.jpg')}
              style={styles.avatar}
            />
            {isUnread && <View style={styles.unreadBadge} />}
          </View>

          <View style={styles.messageContent}>
            <View style={styles.messageHeader}>
              <Text style={[styles.senderName, isUnread && styles.unreadText]}>
                {item.user?.username || 'Utilisateur'}
              </Text>
              <Text style={styles.timeText}>{lastMessageTime}</Text>
            </View>

            <Text
              style={[styles.messageText, isUnread && styles.unreadText]}
              numberOfLines={2}
              ellipsizeMode="tail"
            >
              {item.last_message?.text || 'Aucun message'}
            </Text>

            {isUnread && (
              <View style={styles.unreadCounter}>
                <Text style={styles.unreadCounterText}>{item.unread_count}</Text>
              </View>
            )}
          </View>
        </TouchableOpacity>
      </Swipeable>
    );
  };

  const getTimeAgo = (dateString) => {
    if (!dateString) return '';
    const date = new Date(dateString);
    const now = new Date();
    const diffInMinutes = Math.floor((now - date) / (1000 * 60));
    
    if (diffInMinutes < 1) return "À l'instant";
    if (diffInMinutes < 60) return `Il y a ${diffInMinutes} min`;
    if (diffInMinutes < 1440) return `Il y a ${Math.floor(diffInMinutes / 60)} h`;
    return date.toLocaleDateString('fr-FR', { day: 'numeric', month: 'short' });
  };

  const renderHeader = () => (
    <LinearGradient colors={['#6C63FF', '#3A7BD5']} style={styles.header}>
      <View style={styles.headerContent}>
        <View style={styles.headerTop}>
          <Text style={styles.headerTitle}>Messages</Text>
        </View>

        <View style={styles.searchContainer}>
          <Ionicons name="search" size={20} color="#8E8E93" style={styles.searchIcon} />
          <TextInput
            style={styles.searchInput}
            placeholder="Rechercher des conversations..."
            placeholderTextColor="#8E8E93"
            value={searchQuery}
            onChangeText={setSearchQuery}
            clearButtonMode="while-editing"
          />
          {searchQuery.length > 0 && (
            <TouchableOpacity onPress={() => setSearchQuery('')}>
              <Ionicons name="close-circle" size={20} color="#8E8E93" />
            </TouchableOpacity>
          )}
        </View>

        <View style={styles.statsContainer}>
          <View style={styles.statItem}>
            <Text style={styles.statNumber}>{conversations.length}</Text>
            <Text style={styles.statLabel}>Conversations</Text>
          </View>
          <View style={styles.statDivider} />
          <View style={styles.statItem}>
            <Text style={styles.statNumber}>
              {conversations.reduce((total, conv) => total + (conv.unread_count || 0), 0)}
            </Text>
            <Text style={styles.statLabel}>Non lus</Text>
          </View>
        </View>
      </View>
    </LinearGradient>
  );

  const renderEmptyState = () => (
    <View style={styles.emptyState}>
      <MaterialCommunityIcons name="message-outline" size={80} color="#E0E0E0" />
      <Text style={styles.emptyStateTitle}>Aucune conversation</Text>
      <Text style={styles.emptyStateText}>
        Les messages des propriétaires apparaîtront ici
      </Text>
    </View>
  );

  return (
    <View style={styles.container}>
      {renderHeader()}
      
      {loading ? (
        <View style={styles.loadingContainer}>
          <Ionicons name="chatbubbles" size={60} color="#6C63FF" />
          <Text style={styles.loadingText}>Chargement des conversations...</Text>
        </View>
      ) : (
        <FlatList
          data={filteredConversations}
          renderItem={renderConversationItem}
          keyExtractor={item => item.user?.id?.toString() || Math.random().toString()}
          ListEmptyComponent={renderEmptyState}
          refreshControl={
            <RefreshControl
              refreshing={refreshing}
              onRefresh={onRefresh}
              colors={['#6C63FF']}
              tintColor="#6C63FF"
            />
          }
          contentContainerStyle={styles.listContent}
          showsVerticalScrollIndicator={false}
          ItemSeparatorComponent={() => <View style={styles.separator} />}
        />
      )}
    </View>
  );
};

const themedStyles = (theme, isDarkMode, Platform, StatusBar) => StyleSheet.create({
  container: {  // ← AJOUTER CE NOM DE STYLE
    flex: 1,
    backgroundColor: theme.background,
    paddingTop: Platform.OS === 'android' ? StatusBar.currentHeight : 0,
  },
  header: {
    paddingTop: Platform.OS === 'ios' ? 50 : 40,
    paddingBottom: 20,
    borderBottomLeftRadius: 30,
    borderBottomRightRadius: 30,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 4 },
    shadowOpacity: 0.1,
    shadowRadius: 12,
    elevation: 8,
    backgroundColor: theme.primary,
  },
  headerContent: {
    paddingHorizontal: 20,
  },
  headerTop: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 20,
  },
  headerTitle: {
    fontSize: 28,
    fontWeight: '700',
    color: '#FFF',
  },
  searchContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: theme.card + 'E6',
    borderRadius: 15,
    paddingHorizontal: 15,
    paddingVertical: 12,
    marginBottom: 15,
  },
  searchIcon: {
    marginRight: 10,
    color: theme.subText,
  },
  searchInput: {
    flex: 1,
    fontSize: 16,
    color: theme.text,
    padding: 0,
  },
  statsContainer: {
    flexDirection: 'row',
    justifyContent: 'center',
    alignItems: 'center',
  },
  statItem: {
    alignItems: 'center',
    paddingHorizontal: 20,
  },
  statNumber: {
    fontSize: 20,
    fontWeight: '700',
    color: '#FFF',
    marginBottom: 4,
  },
  statLabel: {
    fontSize: 12,
    color: 'rgba(255,255,255,0.8)',
    textTransform: 'uppercase',
    letterSpacing: 0.5,
  },
  statDivider: {
    width: 1,
    height: 30,
    backgroundColor: 'rgba(255,255,255,0.3)',
  },
  listContent: {
    padding: 16,
    paddingBottom: 100,
  },
  messageItem: {
    flexDirection: 'row',
    backgroundColor: theme.card,
    borderRadius: 16,
    padding: 16,
    marginBottom: 8,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.05,
    shadowRadius: 8,
    elevation: 2,
  },
  unreadMessage: {
    backgroundColor: theme.primary + '20',
    borderLeftWidth: 4,
    borderLeftColor: theme.primary,
  },
  avatarContainer: {
    position: 'relative',
    marginRight: 16,
  },
  avatar: {
    width: 56,
    height: 56,
    borderRadius: 28,
  },
  unreadBadge: {
    position: 'absolute',
    top: 0,
    right: 0,
    width: 14,
    height: 14,
    borderRadius: 7,
    backgroundColor: theme.primary,
    borderWidth: 2,
    borderColor: '#FFF',
  },
  messageContent: {
    flex: 1,
    justifyContent: 'center',
  },
  messageHeader: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 6,
  },
  senderName: {
    fontSize: 16,
    fontWeight: '600',
    color: theme.text,
    flex: 1,
    marginRight: 10,
  },
  unreadText: {
    fontWeight: '700',
    color: theme.primary,
  },
  timeText: {
    fontSize: 12,
    color: theme.subText,
  },
  messageText: {
    fontSize: 14,
    color: theme.subText,
    lineHeight: 20,
  },
  unreadCounter: {
    backgroundColor: theme.primary,
    borderRadius: 12,
    paddingHorizontal: 8,
    paddingVertical: 2,
    alignSelf: 'flex-start',
    marginTop: 4,
  },
  unreadCounterText: {
    color: '#FFF',
    fontSize: 10,
    fontWeight: '600',
  },
  rightActions: {
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'flex-end',
    marginVertical: 8,
    borderRadius: 16,
    overflow: 'hidden',
  },
  actionButton: {
    width: 80,
    justifyContent: 'center',
    alignItems: 'center',
    height: '100%',
  },
  deleteButton: {
    backgroundColor: theme.error,
  },
  actionText: {
    color: '#FFF',
    fontSize: 10,
    marginTop: 4,
    fontWeight: '500',
  },
  separator: {
    height: 8,
  },
  loadingContainer: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
  },
  loadingText: {
    marginTop: 16,
    fontSize: 16,
    color: theme.subText,
    fontWeight: '500',
  },
  emptyState: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    paddingTop: 100,
  },
  emptyStateTitle: {
    fontSize: 20,
    fontWeight: '600',
    color: theme.text,
    marginTop: 20,
    marginBottom: 8,
  },
  emptyStateText: {
    fontSize: 16,
    color: theme.subText,
    textAlign: 'center',
    marginBottom: 30,
    paddingHorizontal: 40,
  },
});

export default MessageScreen;
