// hooks/useThemedStyles.js
import { useTheme } from '../context/ThemeContext.js';
import { lightTheme, darkTheme } from '../styles/themeStyles';
import { Platform, StatusBar } from 'react-native'; // ← AJOUTER CETTE LIGNE

export const useThemedStyles = () => {
  const { isDarkMode } = useTheme();
  const theme = isDarkMode ? darkTheme : lightTheme;

  const getThemeColor = (colorKey) => theme[colorKey];

  const createThemedStyles = (stylesCreator) => {
    // Passer Platform et StatusBar au créateur de styles
    return stylesCreator(theme, isDarkMode, Platform, StatusBar);
  };

  return { theme, isDarkMode, getThemeColor, createThemedStyles };
};