import React, { useState, useEffect } from 'react';
import { Platform,
  StyleSheet, 
  View, 
  ScrollView, 
  Text, 
  Image, 
  TouchableOpacity, 
  Alert,
  ActivityIndicator,
  SafeAreaView,
  StatusBar,
  Share,
  Linking
} from 'react-native'; 
import FontAwesome from 'react-native-vector-icons/FontAwesome';
import Ionicons from 'react-native-vector-icons/Ionicons';
import MaterialIcons from 'react-native-vector-icons/MaterialIcons';
import { useNavigation, useRoute } from '@react-navigation/native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import axios from 'axios';
import Config from './Config';
import {useTheme } from '../context/ThemeContext.js';
import {  useThemedStyles } from '../hooks/useThemedStyles';

const HotelsDetails = () => { 
  const navigation = useNavigation();
  const route = useRoute();
  const { hotelId, hotel: initialHotel } = route.params;
  const { isDarkMode } = useTheme();
  const { createThemedStyles, theme } = useThemedStyles();
  const styles = createThemedStyles(themedStyles);
  
  const [hotel, setHotel] = useState(initialHotel);
  const [loading, setLoading] = useState(!initialHotel);
  const [user, setUser] = useState(null);
  const [rating, setRating] = useState(0);
  const [userRating, setUserRating] = useState(0);
  const [comment, setComment] = useState('');
  const [comments, setComments] = useState([]);
  const [showFullDescription, setShowFullDescription] = useState(false);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);

  useEffect(() => {
    loadUserData();
    if (!initialHotel) {
      fetchHotelDetails();
    } else {
      // Initialiser la note moyenne depuis l'hôtel
      const initialRating = initialHotel.note_moyenne || 0;
      setRating(initialRating);
      fetchHotelComments();
    }
  }, []);

  const loadUserData = async () => {
    try {
      const userData = await AsyncStorage.getItem('user');
      if (userData) {
        setUser(JSON.parse(userData));
      }
    } catch (error) {
      console.error('Erreur chargement utilisateur:', error);
    }
  };

  const fetchHotelDetails = async () => {
    try {
      setLoading(true);
      const response = await axios.get(`${Config.BASE_URL}/hotels/${hotelId}/`);
      setHotel(response.data);
      const averageRating = response.data.note_moyenne || 0;
      setRating(averageRating);
      fetchHotelComments();
    } catch (error) {
      console.error('Erreur chargement hôtel:', error);
      Alert.alert('Erreur', 'Impossible de charger les détails de l\'hôtel');
    } finally {
      setLoading(false);
    }
  };

  const fetchHotelComments = async () => {
    try {
      // Utiliser le bon endpoint pour les commentaires
      const response = await axios.get(`${Config.BASE_URL}/hotels/${hotelId}/notes/`);
      if (response.data) {
        setComments(response.data);
        
        // Vérifier si l'utilisateur a déjà noté
        const userData = await AsyncStorage.getItem('user');
        if (userData && response.data) {
          const currentUser = JSON.parse(userData);
          const userNote = response.data.find(note => note.user === currentUser.id);
          if (userNote) {
            setUserRating(userNote.note || 0);
          }
        }
      }
    } catch (error) {
      console.log('Erreur chargement commentaires:', error.message);
      setComments([]);
    }
  };

  const handleRating = async (newRating) => {
    try {
      const token = await AsyncStorage.getItem('access_token');
      if (!token) {
        Alert.alert('Connexion requise', 'Veuillez vous connecter pour noter');
        return;
      }

      await axios.post(
        `${Config.BASE_URL}/hotels/${hotelId}/noter/`,
        {
          note: newRating,
          commentaire: comment
        },
        {
          headers: { Authorization: `Bearer ${token}` }
        }
      );

      setUserRating(newRating);
      Alert.alert('Succès', 'Votre note a été enregistrée');
      
      // Recharger les détails pour mettre à jour la note moyenne
      fetchHotelDetails();
    } catch (error) {
      console.error('Erreur notation:', error);
      Alert.alert('Erreur', 'Impossible d\'enregistrer votre note');
    }
  };

  const handleShare = async () => {
    try {
      const shareOptions = {
        message: `🏨 ${hotel?.titre || 'Hôtel'}\n📍 ${hotel?.ville || ''}, ${hotel?.pays || 'Niger'}\n⭐ ${'★'.repeat(hotel?.categorie || 3)}\n💰 ${hotel?.prix_nuit || 0} FCFA/nuit\n\n${hotel?.description?.substring(0, 100) || ''}...\n\nTéléchargez l'application Villana pour plus de détails!`,
        title: 'Partager cet hôtel',
        url: `${Config.BASE_URL}/hotels/${hotel?.id}/`
      };

      await Share.share(shareOptions);
    } catch (error) {
      console.error('Erreur de partage:', error);
    }
  };

  const handleContact = () => {
    Alert.alert(
      'Contacter l\'hôtel',
      'Choisissez une méthode de contact:',
      [
        { text: 'Annuler', style: 'cancel' },
        { text: 'Appeler', onPress: () => Linking.openURL(`tel:${hotel?.telephone || ''}`) },
        { text: 'Email', onPress: () => Linking.openURL(`mailto:${hotel?.email || ''}`) },
        { text: 'Demande de réservation', onPress: () => navigation.navigate('ReservationForm', { hotelId: hotel?.id }) }
      ]
    );
  };

  const renderStars = (count, size = 24, color = '#FFD700') => {
    const starCount = count || 0;
    return Array(5).fill(0).map((_, index) => (
      <FontAwesome
        key={index}
        name={index < starCount ? "star" : "star-o"}
        size={size}
        color={color}
      />
    ));
  };

  const renderHotelPhotos = () => {
    if (!hotel?.photos || hotel.photos.length === 0) {
      return (
        <View style={styles.noPhotosContainer}>
          <FontAwesome name="image" size={50} color="#ccc" />
          <Text style={[styles.noPhotosText, isDarkMode && styles.darkSubText]}>Aucune photo disponible</Text>
        </View>
      );
    }

    return (
      <ScrollView 
        horizontal 
        pagingEnabled 
        showsHorizontalScrollIndicator={false}
        style={styles.photosContainer}
        onMomentumScrollEnd={(e) => {
          const index = Math.round(e.nativeEvent.contentOffset.x / 400);
          setCurrentImageIndex(index);
        }}
      >
        {hotel.photos.map((photo, index) => (
          <Image
            key={index}
            source={{ uri: photo.photos || photo }}
            style={styles.hotelImage}
            resizeMode="cover"
          />
        ))}
      </ScrollView>
    );
  };

  const renderServices = () => {
    if (!hotel?.services) return null;
    
    try {
      const servicesList = typeof hotel.services === 'string' 
        ? JSON.parse(hotel.services) 
        : hotel.services;
      
      if (!servicesList || servicesList.length === 0) return null;
      
      return (
        <View style={[styles.servicesContainer, isDarkMode && styles.darkCard]}>
          <Text style={[styles.sectionTitle, isDarkMode && styles.darkText]}>Services inclus</Text>
          <View style={styles.servicesGrid}>
            {servicesList.map((service, index) => (
              <View key={index} style={styles.serviceItem}>
                <FontAwesome name="check-circle" size={16} color="#4CAF50" />
                <Text style={[styles.serviceText, isDarkMode && styles.darkSubText]}>{service}</Text>
              </View>
            ))}
          </View>
        </View>
      );
    } catch (error) {
      return (
        <View style={[styles.servicesContainer, isDarkMode && styles.darkCard]}>
          <Text style={[styles.sectionTitle, isDarkMode && styles.darkText]}>Services</Text>
          <Text style={[styles.serviceText, isDarkMode && styles.darkSubText]}>{hotel.services}</Text>
        </View>
      );
    }
  };

  const renderComments = () => {
    if (!comments || comments.length === 0) {
      return (
        <View style={[styles.noCommentsContainer, isDarkMode && styles.darkCard]}>
          <Text style={[styles.noCommentsText, isDarkMode && styles.darkSubText]}>Aucun commentaire pour l'instant</Text>
          <Text style={[styles.noCommentsSubtext, isDarkMode && styles.darkSubText]}>Soyez le premier à donner votre avis!</Text>
        </View>
      );
    }

    return (
      <View style={[styles.commentsContainer, isDarkMode && styles.darkCard]}>
        <Text style={[styles.sectionTitle, isDarkMode && styles.darkText]}>Avis des clients ({comments.length})</Text>
        {comments.slice(0, 3).map((commentItem, index) => (
          <View key={index} style={[styles.commentItem, isDarkMode && styles.darkCardBorder]}>
            <View style={styles.commentHeader}>
              <Text style={[styles.commentUser, isDarkMode && styles.darkText]}>
                {commentItem.user_name || commentItem.user?.username || 'Anonyme'}
              </Text>
              <View style={styles.commentRating}>
                {renderStars(commentItem.note || 0, 14)}
              </View>
            </View>
            {commentItem.commentaire && (
              <Text style={[styles.commentText, isDarkMode && styles.darkSubText]}>{commentItem.commentaire}</Text>
            )}
            <Text style={[styles.commentDate, isDarkMode && styles.darkSubText]}>
              {new Date(commentItem.date_creation).toLocaleDateString('fr-FR')}
            </Text>
          </View>
        ))}
        
        {comments.length > 3 && (
          <TouchableOpacity 
            style={styles.seeMoreButton}
            onPress={() => navigation.navigate('HotelReviews', { hotelId: hotel?.id })}
          >
            <Text style={[styles.seeMoreText, { color: theme.primary }]}>Voir tous les avis</Text>
          </TouchableOpacity>
        )}
      </View>
    );
  };

  const renderRatingSection = () => (
    <View style={[styles.ratingContainer, isDarkMode && styles.darkCard]}>
      <Text style={[styles.sectionTitle, isDarkMode && styles.darkText]}>Votre avis</Text>
      <View style={styles.ratingStars}>
        {[1, 2, 3, 4, 5].map((star) => (
          <TouchableOpacity
            key={star}
            onPress={() => handleRating(star)}
            disabled={!user}
          >
            <FontAwesome
              name={star <= userRating ? "star" : "star-o"}
              size={32}
              color={star <= userRating ? "#FFD700" : "#ccc"}
            />
          </TouchableOpacity>
        ))}
      </View>
      <Text style={[styles.ratingText, isDarkMode && styles.darkSubText]}>
        {typeof rating === 'number' ? rating.toFixed(1) : '0.0'}/5 ({comments?.length || 0} avis)
      </Text>
      
      {!user && (
        <TouchableOpacity 
          style={styles.loginToRateButton}
          onPress={() => navigation.navigate('Login')}
        >
          <Text style={styles.loginToRateText}>Connectez-vous pour noter</Text>
        </TouchableOpacity>
      )}
    </View>
  );

  if (loading) {
    return (
      <SafeAreaView style={[styles.loadingContainer, isDarkMode && styles.darkContainer]}>
        <StatusBar barStyle={isDarkMode ? 'light-content' : 'dark-content'} backgroundColor={theme.background} translucent />
        <ActivityIndicator size="large" color={theme.primary} />
        <Text style={[styles.loadingText, isDarkMode && styles.darkText]}>Chargement des détails...</Text>
      </SafeAreaView>
    );
  }

  if (!hotel) {
    return (
      <SafeAreaView style={[styles.errorContainer, isDarkMode && styles.darkContainer]}>
        <StatusBar barStyle={isDarkMode ? 'light-content' : 'dark-content'} backgroundColor={theme.background} translucent />
        <FontAwesome name="hotel" size={60} color="#ccc" />
        <Text style={[styles.errorText, isDarkMode && styles.darkText]}>Hôtel non trouvé</Text>
        <TouchableOpacity 
          style={styles.goBackButton}
          onPress={() => navigation.goBack()}
        >
          <Text style={styles.goBackButtonText}>Retour</Text>
        </TouchableOpacity>
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView style={[styles.container, isDarkMode && styles.darkContainer]}>
      <StatusBar barStyle={isDarkMode ? 'light-content' : 'dark-content'} backgroundColor={theme.background} translucent />
      
      <ScrollView showsVerticalScrollIndicator={false}>
        {/* Header avec image et bouton retour */}
        <View style={styles.headerContainer}>
          {renderHotelPhotos()}
          <TouchableOpacity 
            style={styles.backButton}
            onPress={() => navigation.goBack()}
          >
            <FontAwesome name="chevron-left" size={24} color="#fff" />
          </TouchableOpacity>
          
          <TouchableOpacity 
            style={styles.shareButton}
            onPress={handleShare}
          >
            <FontAwesome name="share-alt" size={20} color="#fff" />
          </TouchableOpacity>

          {/* Indicateur de page pour les photos */}
          {hotel.photos && hotel.photos.length > 1 && (
            <View style={styles.imageCounter}>
              <Text style={styles.imageCounterText}>
                {currentImageIndex + 1}/{hotel.photos.length}
              </Text>
            </View>
          )}
        </View>

        {/* Informations principales */}
        <View style={[styles.mainInfoContainer, isDarkMode && styles.darkCard]}>
          <View style={styles.titleRow}>
            <Text style={[styles.hotelTitle, isDarkMode && styles.darkText]}>{hotel.titre}</Text>
            <View style={styles.categoryContainer}>
              {renderStars(hotel.categorie || 3, 16)}
            </View>
          </View>
          
          <View style={styles.locationRow}>
            <FontAwesome name="map-marker" size={16} color={isDarkMode ? '#aaa' : '#666'} />
            <Text style={[styles.locationText, isDarkMode && styles.darkSubText]}>
              {hotel.ville}, {hotel.pays || 'Niger'}
            </Text>
          </View>
          
          <View style={styles.priceContainer}>
            <Text style={[styles.price, { color: theme.primary }]}>{hotel.prix_nuit} FCFA</Text>
            <Text style={[styles.priceLabel, isDarkMode && styles.darkSubText]}>/nuit</Text>
          </View>
        </View>

        {/* Description */}
        <View style={[styles.descriptionContainer, isDarkMode && styles.darkCard]}>
          <Text style={[styles.sectionTitle, isDarkMode && styles.darkText]}>Description</Text>
          <Text style={[styles.descriptionText, isDarkMode && styles.darkSubText]} numberOfLines={showFullDescription ? undefined : 3}>
            {hotel.description}
          </Text>
          {hotel.description && hotel.description.length > 150 && (
            <TouchableOpacity 
              style={styles.showMoreButton}
              onPress={() => setShowFullDescription(!showFullDescription)}
            >
              <Text style={[styles.showMoreText, { color: theme.primary }]}>
                {showFullDescription ? 'Voir moins' : 'Voir plus'}
              </Text>
            </TouchableOpacity>
          )}
        </View>

        {/* Services */}
        {renderServices()}

        {/* Informations pratiques */}
        <View style={[styles.practicalInfoContainer, isDarkMode && styles.darkCard]}>
          <Text style={[styles.sectionTitle, isDarkMode && styles.darkText]}>Informations pratiques</Text>
          <View style={styles.infoGrid}>
            <View style={[styles.infoItem, isDarkMode && styles.darkCardBorder]}>
              <FontAwesome name="bed" size={20} color={theme.primary} />
              <Text style={[styles.infoLabel, isDarkMode && styles.darkSubText]}>Chambres</Text>
              <Text style={[styles.infoValue, isDarkMode && styles.darkText]}>
                {hotel.chambres_disponibles}/{hotel.nombre_chambres} dispo
              </Text>
            </View>
            
            <View style={[styles.infoItem, isDarkMode && styles.darkCardBorder]}>
              <FontAwesome name="sign-in" size={20} color={theme.primary} />
              <Text style={[styles.infoLabel, isDarkMode && styles.darkSubText]}>Check-in</Text>
              <Text style={[styles.infoValue, isDarkMode && styles.darkText]}>{hotel.heure_check_in || '14:00'}</Text>
            </View>
            
            <View style={[styles.infoItem, isDarkMode && styles.darkCardBorder]}>
              <FontAwesome name="sign-out" size={20} color={theme.primary} />
              <Text style={[styles.infoLabel, isDarkMode && styles.darkSubText]}>Check-out</Text>
              <Text style={[styles.infoValue, isDarkMode && styles.darkText]}>{hotel.heure_check_out || '12:00'}</Text>
            </View>
            
            <View style={[styles.infoItem, isDarkMode && styles.darkCardBorder]}>
              <FontAwesome name="hotel" size={20} color={theme.primary} />
              <Text style={[styles.infoLabel, isDarkMode && styles.darkSubText]}>Type</Text>
              <Text style={[styles.infoValue, isDarkMode && styles.darkText]}>{hotel.type_hotel || 'Standard'}</Text>
            </View>
          </View>
        </View>

        {/* Notation */}
        {renderRatingSection()}

        {/* Commentaires */}
        {renderComments()}

        {/* Espacement */}
        <View style={styles.bottomSpacing} />
      </ScrollView>

      {/* Bouton d'action fixe */}
      <View style={[styles.actionBar, isDarkMode && styles.darkCard]}>
        <TouchableOpacity 
          style={[styles.contactButton, { backgroundColor: '#4CAF50' }]}
          onPress={handleContact}
        >
          <FontAwesome name="phone" size={20} color="#fff" />
          <Text style={styles.contactButtonText}>Contacter</Text>
        </TouchableOpacity>
        
        <TouchableOpacity 
          style={[styles.reserveButton, { backgroundColor: theme.primary }]}
          onPress={() => navigation.navigate('ReservationForm', { hotelId: hotel.id })}
        >
          <FontAwesome name="calendar-check-o" size={20} color="#fff" />
          <Text style={styles.reserveButtonText}>Réserver</Text>
        </TouchableOpacity>
      </View>
    </SafeAreaView>
  );
};

