// PropertyDetail.js - Détail d'un bien
import React, { useState, useEffect } from 'react';
import { Platform, StatusBar, 
  View,
  Text,
  StyleSheet,
  ScrollView,
  TouchableOpacity,
  Image,
  Alert,
  ActivityIndicator,
  Linking
} from 'react-native';
import Ionicons from 'react-native-vector-icons/Ionicons';
import AsyncStorage from '@react-native-async-storage/async-storage';
import axios from 'axios';
import Config from './Config';
import {  useTheme } from '../context/ThemeContext.js';
import { useThemedStyles } from '../hooks/useThemedStyles.js';

const PropertyDetail = ({ navigation, route }) => {
  const { propertyId } = route.params;
  const { isDarkMode } = useTheme();
  const { createThemedStyles, theme } = useThemedStyles();
  const styles = createThemedStyles(themedStyles);
  
  const [property, setProperty] = useState(null);
  const [loading, setLoading] = useState(true);
  const [isFavorite, setIsFavorite] = useState(false);

  useEffect(() => {
    fetchPropertyDetail();
    checkFavorite();
  }, []);

  const fetchPropertyDetail = async () => {
    try {
      const response = await axios.get(`${Config.BASE_URL}/api/properties/${propertyId}/`);
      setProperty(response.data);
    } catch (error) {
      Alert.alert('Erreur', 'Impossible de charger les détails');
      navigation.goBack();
    } finally {
      setLoading(false);
    }
  };

  const checkFavorite = async () => {
    try {
      const token = await AsyncStorage.getItem('access_token');
      if (token) {
        const response = await axios.get(`${Config.BASE_URL}/api/favorites/check/${propertyId}/`, {
          headers: { Authorization: `Bearer ${token}` }
        });
        setIsFavorite(response.data.is_favorite);
      }
    } catch (error) {
      console.error('Erreur check favori:', error);
    }
  };

  const toggleFavorite = async () => {
    try {
      const token = await AsyncStorage.getItem('access_token');
      if (!token) {
        Alert.alert('Connexion requise', 'Veuillez vous connecter pour ajouter aux favoris');
        navigation.navigate('LoginScreen');
        return;
      }

      if (isFavorite) {
        await axios.delete(`${Config.BASE_URL}/api/favorites/remove/${propertyId}/`, {
          headers: { Authorization: `Bearer ${token}` }
        });
        setIsFavorite(false);
      } else {
        await axios.post(`${Config.BASE_URL}/api/favorites/add/`, { property_id: propertyId }, {
          headers: { Authorization: `Bearer ${token}` }
        });
        setIsFavorite(true);
      }
    } catch (error) {
      Alert.alert('Erreur', 'Impossible de modifier les favoris');
    }
  };

  const contactOwner = () => {
    if (property?.owner_phone) {
      Linking.openURL(`tel:${property.owner_phone}`);
    } else {
      Alert.alert('Information', 'Le numéro du propriétaire n\'est pas disponible');
    }
  };

  if (loading) {
    return (
      <View style={[styles.container, isDarkMode && styles.darkContainer, styles.centerContent]}>
        <ActivityIndicator size="large" color={theme.primary} />
      </View>
    );
  }

  return (
    <ScrollView style={[styles.container, isDarkMode && styles.darkContainer]}>
      <View style={styles.imageContainer}>
        <Image 
          source={property?.images?.[0] ? { uri: property.images[0] } : require('../assets/profil.jpg')}
          style={styles.mainImage}
        />
        <TouchableOpacity style={styles.backButton} onPress={() => navigation.goBack()}>
          <Ionicons name="arrow-back" size={24} color="#fff" />
        </TouchableOpacity>
        <TouchableOpacity style={styles.favoriteButton} onPress={toggleFavorite}>
          <Ionicons name={isFavorite ? 'heart' : 'heart-outline'} size={28} color={isFavorite ? '#FF3B30' : '#fff'} />
        </TouchableOpacity>
      </View>

      <View style={styles.content}>
        <View style={styles.header}>
          <Text style={[styles.title, isDarkMode && styles.darkText]}>{property.title}</Text>
          <Text style={[styles.price, isDarkMode && styles.darkText]}>{property.price} FCFA/mois</Text>
        </View>

        <View style={styles.location}>
          <Ionicons name="location-outline" size={18} color={theme.subText} />
          <Text style={[styles.locationText, isDarkMode && styles.darkSubText]}>{property.location}</Text>
        </View>

        <View style={styles.features}>
          <View style={styles.feature}>
            <Ionicons name="resize-outline" size={20} color={theme.primary} />
            <Text style={[styles.featureText, isDarkMode && styles.darkText]}>{property.area} m²</Text>
          </View>
          <View style={styles.feature}>
            <Ionicons name="bed-outline" size={20} color={theme.primary} />
            <Text style={[styles.featureText, isDarkMode && styles.darkText]}>{property.bedrooms} ch.</Text>
          </View>
          <View style={styles.feature}>
            <Ionicons name="water-outline" size={20} color={theme.primary} />
            <Text style={[styles.featureText, isDarkMode && styles.darkText]}>{property.bathrooms} sdb</Text>
          </View>
        </View>

        <View style={styles.section}>
          <Text style={[styles.sectionTitle, isDarkMode && styles.darkText]}>Description</Text>
          <Text style={[styles.description, isDarkMode && styles.darkSubText]}>{property.description}</Text>
        </View>

        <TouchableOpacity style={styles.contactButton} onPress={contactOwner}>
          <Ionicons name="call" size={20} color="#fff" />
          <Text style={styles.contactButtonText}>Contacter le propriétaire</Text>
        </TouchableOpacity>
      </View>
    </ScrollView>
  );
};

const themedStyles = (theme, isDarkMode, Platform, StatusBar) => StyleSheet.create({
    container: {
      flex: 1,
      backgroundColor: theme.background,
      paddingTop: Platform.OS === 'android' ? StatusBar.currentHeight : 0,
    },
  darkContainer: { backgroundColor: '#1a1a1a' },
  darkText: { color: '#fff' },
  darkSubText: { color: '#aaa' },
  
  centerContent: { justifyContent: 'center', alignItems: 'center' },
  
  imageContainer: { position: 'relative' },
  mainImage: { width: '100%', height: 300 },
  backButton: { position: 'absolute', top: 40, left: 20, backgroundColor: 'rgba(0,0,0,0.5)', padding: 10, borderRadius: 25 },
  favoriteButton: { position: 'absolute', top: 40, right: 20, backgroundColor: 'rgba(0,0,0,0.5)', padding: 10, borderRadius: 25 },
  
  content: { padding: 20 },
  header: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 10 },
  title: { fontSize: 22, fontWeight: 'bold', color: theme.text, flex: 1 },
  price: { fontSize: 20, fontWeight: 'bold', color: theme.primary },
  
  location: { flexDirection: 'row', alignItems: 'center', gap: 5, marginBottom: 20 },
  locationText: { fontSize: 14, color: theme.subText },
  
  features: { flexDirection: 'row', gap: 20, marginBottom: 20, paddingVertical: 15, borderTopWidth: 1, borderBottomWidth: 1, borderColor: theme.border },
  feature: { flexDirection: 'row', alignItems: 'center', gap: 8 },
  featureText: { fontSize: 14, color: theme.text },
  
  section: { marginBottom: 20 },
  sectionTitle: { fontSize: 18, fontWeight: 'bold', color: theme.text, marginBottom: 10 },
  description: { fontSize: 14, color: theme.subText, lineHeight: 20 },
  
  contactButton: { backgroundColor: theme.primary, flexDirection: 'row', alignItems: 'center', justifyContent: 'center', gap: 10, padding: 15, borderRadius: 10, marginTop: 10 },
  contactButtonText: { color: '#fff', fontSize: 16, fontWeight: 'bold' },
});

export default PropertyDetail;


