// BandePub.js
import React, { useEffect, useState, useRef } from 'react';
import { 
  StyleSheet, 
  View, 
  FlatList, 
  TouchableOpacity, 
  Image, 
  Linking,
  Text,
  Dimensions 
} from 'react-native';
import axios from 'axios';
import { useNavigation } from '@react-navigation/native';
import FontAwesome from 'react-native-vector-icons/FontAwesome';
import Config from './Config';
import { useThemedStyles } from '../hooks/useThemedStyles';

const { width: SCREEN_WIDTH } = Dimensions.get('window');
const PLACEHOLDER = require('../assets/icon.png');

const BandePub = () => {
  const { createThemedStyles, theme, isDarkMode } = useThemedStyles();
  const styles = createThemedStyles(themedStyles);
  const [ads, setAds] = useState([]);
  const navigation = useNavigation();
  const flatListRef = useRef(null);
  const [currentIndex, setCurrentIndex] = useState(0);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      try {
        setLoading(true);
        const res = await axios.get(`${Config.BASE_URL}/publicites/`);
        
        // Sécuriser et formater les données
        const safeData = Array.isArray(res.data) ? res.data.map(ad => ({
          ...ad,
          photos: ad.photos || null,
          titre: ad.titre || 'Publicité',
          lien: ad.lien || null,
          brandName: ad.titre?.split(' ')[0] || 'Marque'
        })) : [];

        setAds(safeData);
      } catch (err) {
        //console.error('Erreur chargement publicités:', err.toString());
        // Données de démo en cas d'erreur
        setAds([
          {
            id: 1,
            titre: 'Agence Immobilière Premium',
            photos: null,
            lien: 'https://Immobilière.com',
            brandName: 'Agence',
            description: 'Trouvez la propriété de vos rêves'
          },
          {
            id: 2,
            titre: 'Financement Immobilier',
            photos: null,
            lien: 'https://example.com',
            brandName: 'Finance',
            description: 'Crédits avantageux jusqu\'à 25 ans'
          }
        ]);
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, []);

  useEffect(() => {
    if (!ads || ads.length <= 1) return;
    
    const interval = setInterval(() => {
      setCurrentIndex(prev => {
        const next = (prev + 1) % ads.length;
        if (flatListRef.current) {
          flatListRef.current.scrollToIndex({ 
            index: next, 
            animated: true,
            viewPosition: 0.5
          });
        }
        return next;
      });
    }, 4000); // 4 secondes entre chaque pub
    
    return () => clearInterval(interval);
  }, [ads]);

  const handleAdPress = (ad) => {
    if (ad.lien) {
      Linking.openURL(ad.lien).catch(err => {
        console.error('Failed to open URL:', err);
        alert("Impossible d'ouvrir le lien. Veuillez réessayer.");
      });
    } else {
      alert("Aucun lien disponible pour cette publicité.");
    }
  };

  const renderAdItem = ({ item, index }) => {
    const imageUrl = item.photos || null;
    const isActive = index === currentIndex;

    return (
      <TouchableOpacity 
        onPress={() => handleAdPress(item)}
        activeOpacity={0.8}
        style={styles.adContainer}
      >
        <View style={[
          styles.adCard,
          isActive && styles.activeAdCard
        ]}>
          {/* Image de la publicité */}
          <View style={styles.imageWrapper}>
            {imageUrl ? (
              <Image 
                source={{ uri: imageUrl }} 
                style={styles.adImage}
                resizeMode="cover"
                onError={() => console.log("Erreur de chargement de l'image publicitaire")}
              />
            ) : (
              <Image 
                source={PLACEHOLDER} 
                style={styles.adImage}
                resizeMode="cover"
              />
            )}
            
            {/* Overlay sombre pour meilleure lisibilité */}
            <View style={styles.imageOverlay} />
            
            {/* Nom de la marque en haut à gauche */}
            <View style={styles.brandTopLeft}>
              <Text style={styles.brandText} numberOfLines={1}>
                {item.brandName}
              </Text>
            </View>
            
            {/* Contenu de la publicité */}
            <View style={styles.adContent}>
              <Text style={styles.adTitle} numberOfLines={2}>
                {item.titre}
              </Text>
              {item.description && (
                <Text style={styles.adDescription} numberOfLines={2}>
                  {item.description}
                </Text>
              )}
              <Text style={styles.adSubtitle}>
                Publicité partenaire
              </Text>
            </View>
            
            {/* Indicateur de clic */}
            <View style={styles.clickIndicator}>
              <Text style={styles.clickText}>
                Cliquez pour en savoir plus
              </Text>
              <FontAwesome name="arrow-right" size={14} color="#fff" style={styles.arrowIcon} />
            </View>
          </View>
        </View>
      </TouchableOpacity>
    );
  };

  const renderPagination = () => {
    if (ads.length <= 1) return null;
    
    return (
      <View style={styles.paginationContainer}>
        {ads.map((_, index) => (
          <View 
            key={index}
            style={[
              styles.paginationDot,
              index === currentIndex ? styles.activeDot : styles.inactiveDot
            ]}
          />
        ))}
      </View>
    );
  };

  if (loading) {
    return (
      <View style={styles.loadingContainer}>
        <Text style={styles.loadingText}>Chargement des publicités...</Text>
      </View>
    );
  }

  if (ads.length === 0) {
    return (
      <View style={styles.emptyContainer}>
        <FontAwesome name="bullhorn" size={40} color="#ccc" />
        <Text style={styles.emptyText}>Aucune publicité disponible</Text>
      </View>
    );
  }

  return (
    <View style={styles.mainContainer}>
      {/*<View style={styles.headerContainer}>
        <Text style={styles.sectionTitle}>Publicités</Text>
      </View>*/}
      
      <View style={styles.adsContainer}>
        <FlatList
          ref={flatListRef}
          data={ads}
          keyExtractor={item => String(item.id)}
          horizontal
          pagingEnabled
          showsHorizontalScrollIndicator={false}
          renderItem={renderAdItem}
          contentContainerStyle={styles.listContent}
          onScrollToIndexFailed={() => {}}
          onMomentumScrollEnd={(event) => {
            const newIndex = Math.round(
              event.nativeEvent.contentOffset.x / (SCREEN_WIDTH * 0.9)
            );
            setCurrentIndex(newIndex);
          }}
        />
        
        {renderPagination()}
      </View>
    </View>
  );
};

export default BandePub;

