import React, { useState, useEffect } from "react";
import { useTheme } from '../context/ThemeContext.js';
import {
  View,
  Text,
  Pressable,
  TextInput,
  ScrollView,
  Alert,
  Image,
  StyleSheet,
  TouchableOpacity,
  Modal,
  ActivityIndicator,
  KeyboardAvoidingView,
  Platform,
  SafeAreaView, StatusBar,
} from "react-native";
import { launchImageLibrary, launchCamera } from "react-native-image-picker";
import Ionicons from "react-native-vector-icons/Ionicons";
import MaterialIcons from "react-native-vector-icons/MaterialIcons";
import FontAwesome from "react-native-vector-icons/FontAwesome";
import Feather from "react-native-vector-icons/Feather";
import LinearGradient from "react-native-linear-gradient";
import AsyncStorage from "@react-native-async-storage/async-storage";
import axios from "axios";
import Config from "./Config";
import { useThemedStyles } from '../hooks/useThemedStyles';

const PublishScreen = ({ navigation }) => {
  const { createThemedStyles, theme } = useThemedStyles(); // ← UTILISER useThemedStyles
  const [type, setType] = useState(null);
  const [photos, setPhotos] = useState([]);
  const [data, setData] = useState({});
  const [loading, setLoading] = useState(false);
  const [step, setStep] = useState(1);
  const [photoModalVisible, setPhotoModalVisible] = useState(false);
  const [selectedType, setSelectedType] = useState("");
 const styles = createThemedStyles(themedStyles);

  const pickImagesFromGallery = async () => {
    try {
      const result = await launchImageLibrary({
        mediaType: 'photo',
        selectionLimit: 0,
        quality: 0.8,
      });

      if (!result.didCancel && result.assets) {
        setPhotos([...photos, ...result.assets]);
      }
      setPhotoModalVisible(false);
    } catch (error) {
      Alert.alert("Erreur", "Impossible d'accéder à la galerie");
    }
  };

  const takePhoto = async () => {
    try {
      const result = await launchCamera({
        mediaType: 'photo',
        quality: 0.8,
      });

      if (!result.didCancel && result.assets) {
        setPhotos([...photos, ...result.assets]);
      }
      setPhotoModalVisible(false);
    } catch (error) {
      Alert.alert("Erreur", "Impossible d'accéder à la caméra");
    }
  };

  const removePhoto = (index) => {
    const newPhotos = [...photos];
    newPhotos.splice(index, 1);
    setPhotos(newPhotos);
  };

  const handleTypeSelect = (typeKey, typeLabel) => {
    setSelectedType(typeLabel);
    setType(typeKey);
    setStep(2);
  };

  const getFormData = () => {
    const formData = new FormData();

    // Ajouter les données de base
    Object.keys(data).forEach(key => {
      if (data[key] !== undefined && data[key] !== "") {
        formData.append(key, data[key]);
      }
    });

    // Ajouter le type selon la catégorie
    if (type === "vente" || type === "location") {
      formData.append("type_maison", type);
    } else if (type === "parcelle") {
      formData.append("type_parcelle", data.type_parcelle || "residentielle");
    } else if (type === "hotel") {
      formData.append("type_hotel", data.type_hotel || "hotel");
      formData.append("categorie", data.categorie || 3);
    }

    // Ajouter les photos
    photos.forEach((photo, index) => {
      const uriParts = photo.uri.split('.');
      const fileType = uriParts[uriParts.length - 1];

      formData.append("photos", {
        uri: photo.uri,
        name: `photo_${Date.now()}_${index}.${fileType}`,
        type: `image/${fileType}`,
      });
    });

    return formData;
  };

  const validateForm = () => {
    if (photos.length === 0) {
      Alert.alert("Attention", "Veuillez ajouter au moins une photo");
      return false;
    }

    if (!data.description || data.description.trim() === "") {
      Alert.alert("Attention", "Veuillez saisir une description");
      return false;
    }

    if (!data.prix || data.prix.trim() === "") {
      Alert.alert("Attention", "Veuillez saisir un prix");
      return false;
    }

    return true;
  };

  const submit = async () => {
    if (!validateForm()) return;

    setLoading(true);

    try {
      const userData = await AsyncStorage.getItem('user');
      const token = await AsyncStorage.getItem('access_token');

      if (!userData || !token) {
        Alert.alert("Erreur", "Vous devez être connecté pour publier");
        navigation.navigate('Login');
        return;
      }

      const user = JSON.parse(userData);
      const formData = getFormData();

      let endpoint = "";

      switch (type) {
        case "vente":
        case "location":
          endpoint = `${Config.BASE_URL}/maisons/`;
          break;
        case "parcelle":
          endpoint = `${Config.BASE_URL}/parcelles/`;
          break;
        case "hotel":
          endpoint = `${Config.BASE_URL}/hotels/`;
          break;
        case "pub":
          endpoint = `${Config.BASE_URL}/publicites/`;
          break;
        default:
          throw new Error("Type non reconnu");
      }

      await axios.post(endpoint, formData, {
        headers: {
          "Content-Type": "multipart/form-data",
          Authorization: `Bearer ${token}`,
        },
      });

      Alert.alert(
        "Succès",
        "Votre publication a été créée avec succès !",
        [
          {
            text: "OK",
            onPress: () => {
              resetForm();
              navigation.goBack();
            },
          },
        ]
      );
    } catch (error) {
      console.error("Erreur lors de la publication:", error);
      Alert.alert(
        "Erreur",
        error.response?.data?.message || "Une erreur est survenue lors de la publication"
      );
    } finally {
      setLoading(false);
    }
  };

  const resetForm = () => {
    setType(null);
    setPhotos([]);
    setData({});
    setStep(1);
    setSelectedType("");
  };

  const goBack = () => {
    if (step === 2) {
      Alert.alert(
        "Annuler la publication ?",
        "Les données saisies seront perdues.",
        [
          { text: "Non", style: "cancel" },
          { text: "Oui", onPress: () => setStep(1) },
        ]
      );
    } else {
      navigation.goBack();
    }
  };

  // Composant Field à l'intérieur pour éviter les problèmes
  const Field = ({
    label,
    placeholder,
    icon,
    keyboardType,
    multiline,
    numberOfLines,
    value,
    onChange,
    containerStyle
  }) => (
    <View style={[styles.fieldContainer, containerStyle]}>
      <Text style={styles.fieldLabel}>{label}</Text>
      <View style={[
        styles.inputContainer,
        multiline && styles.multilineInputContainer
      ]}>
        {icon && (
          <Ionicons
            name={icon}
            size={20}
            color="#666"
            style={styles.fieldIcon}
          />
        )}
        <TextInput
          style={[
            styles.input,
            multiline && styles.multilineInput
          ]}
          placeholder={placeholder}
          placeholderTextColor="#999"
          keyboardType={keyboardType}
          multiline={multiline}
          numberOfLines={numberOfLines}
          value={value}
          onChangeText={onChange}
        />
      </View>
    </View>
  );

  // ÉTAPE 1 : Choix du type
  if (step === 1) {
    return (
      <KeyboardAvoidingView
            style={styles.container}
            behavior={Platform.OS === "ios" ? "padding" : "height"}
          >
          <LinearGradient
            colors={["#6C63FF", "#3A7BD5"]}
            style={styles.header}
          >
            <TouchableOpacity onPress={goBack} style={styles.backButton}>
              <Ionicons name="arrow-back" size={24} color="#FFF" />
            </TouchableOpacity>
            <Text style={styles.title}>Publier une annonce</Text>
            <View style={{ width: 24 }} />
          </LinearGradient>

          <ScrollView contentContainerStyle={styles.step1Content}>
            <View style={styles.typeGrid}>
              {[
                {
                  key: "location",
                  label: "Maison à louer",
                  icon: "home-outline",
                  color: "#4CAF50",
                  gradient: ["#4CAF50", "#8BC34A"],
                },
                {
                  key: "vente",
                  label: "Maison à vendre",
                  icon: "home",
                  color: "#2196F3",
                  gradient: ["#2196F3", "#03A9F4"],
                },
                {
                  key: "parcelle",
                  label: "Terrain/Parcelle",
                  icon: "map-outline",
                  color: "#FF9800",
                  gradient: ["#FF9800", "#FFC107"],
                },
                {
                  key: "hotel",
                  label: "Hôtel/Appart-hôtel",
                  icon: "bed-outline",
                  color: "#9C27B0",
                  gradient: ["#9C27B0", "#E91E63"],
                },
                {
                  key: "pub",
                  label: "Publicité",
                  icon: "megaphone-outline",
                  color: "#607D8B",
                  gradient: ["#607D8B", "#78909C"],
                },
              ].map((item) => (
                <TouchableOpacity
                  key={item.key}
                  onPress={() => handleTypeSelect(item.key, item.label)}
                  style={styles.typeCard}
                  activeOpacity={0.8}
                >
                  <LinearGradient
                    colors={item.gradient}
                    style={styles.typeIconContainer}
                    start={{ x: 0, y: 0 }}
                    end={{ x: 1, y: 1 }}
                  >
                    <Ionicons name={item.icon} size={32} color="#FFF" />
                  </LinearGradient>
                  <Text style={styles.typeLabel}>{item.label}</Text>
                </TouchableOpacity>
              ))}
            </View>
          </ScrollView>
        </KeyboardAvoidingView>

    );
  }

  // ÉTAPE 2 : Formulaire de publication
  return (
<KeyboardAvoidingView
    style={styles.container}
    behavior={Platform.OS === "ios" ? "padding" : "height"}
  >
        <LinearGradient
          colors={["#6C63FF", "#3A7BD5"]}
          style={styles.header}
        >
          <TouchableOpacity onPress={goBack} style={styles.backButton}>
            <Ionicons name="arrow-back" size={24} color="#FFF" />
          </TouchableOpacity>
          <View style={styles.headerTextContainer}>
            <Text style={styles.title}>Nouvelle annonce</Text>
            <Text style={styles.subtitle}>{selectedType}</Text>
          </View>
          <View style={{ width: 24 }} />
        </LinearGradient>

        <ScrollView
          contentContainerStyle={styles.step2Content}
          showsVerticalScrollIndicator={false}
        >
          {/* Section Photos */}
          <View style={styles.section}>
            <Text style={styles.sectionTitle}>Photos</Text>
            <Text style={styles.sectionSubtitle}>
              {photos.length > 0
                ? `${photos.length} photo${photos.length > 1 ? 's' : ''} sélectionnée${photos.length > 1 ? 's' : ''}`
                : "Ajoutez des photos pour illustrer votre annonce"
              }
            </Text>

            <TouchableOpacity
              onPress={() => setPhotoModalVisible(true)}
              style={styles.addPhotosButton}
              activeOpacity={0.7}
            >
              <LinearGradient
                colors={["#6C63FF", "#FF6B9D"]}
                style={styles.addPhotosGradient}
              >
                <Ionicons name="camera" size={24} color="#FFF" />
                <Text style={styles.addPhotosText}>Ajouter des photos</Text>
              </LinearGradient>
            </TouchableOpacity>

            {photos.length > 0 && (
              <ScrollView horizontal showsHorizontalScrollIndicator={false} style={styles.photosContainer}>
                {photos.map((photo, index) => (
                  <View key={index} style={styles.photoItem}>
                    <Image source={{ uri: photo.uri }} style={styles.photo} />
                    <TouchableOpacity
                      onPress={() => removePhoto(index)}
                      style={styles.removePhotoButton}
                    >
                      <Ionicons name="close-circle" size={24} color="#FF3B30" />
                    </TouchableOpacity>
                  </View>
                ))}
              </ScrollView>
            )}
          </View>

          {/* Section Informations */}
          <View style={styles.section}>
            <Text style={styles.sectionTitle}>Informations principales</Text>

            <Field
              label="Titre"
              placeholder="Ex: Belle maison avec jardin..."
              icon="text-outline"
              value={data.titre || ""}
              onChange={(v) => setData({ ...data, titre: v })}
            />

            <Field
              label="Description"
              placeholder="Décrivez votre bien en détail..."
              icon="document-text-outline"
              multiline
              numberOfLines={4}
              value={data.description || ""}
              onChange={(v) => setData({ ...data, description: v })}
            />

            <Field
              label="Prix (FCFA)"
              placeholder="Ex: 150000"
              icon="cash-outline"
              keyboardType="numeric"
              value={data.prix || ""}
              onChange={(v) => setData({ ...data, prix: v })}
            />
          </View>

          {/* Section Détails spécifiques */}
          {(type === "vente" || type === "location") && (
            <View style={styles.section}>
              <Text style={styles.sectionTitle}>Détails de la maison</Text>
              <View style={styles.detailsGrid}>
                <Field
                  label="Chambres"
                  placeholder="3"
                  keyboardType="numeric"
                  containerStyle={styles.gridItem}
                  value={data.nombre_chambres || ""}
                  onChange={(v) => setData({ ...data, nombre_chambres: v })}
                />
                <Field
                  label="Salles de bain"
                  placeholder="2"
                  keyboardType="numeric"
                  containerStyle={styles.gridItem}
                  value={data.nombre_salles_de_bain || ""}
                  onChange={(v) => setData({ ...data, nombre_salles_de_bain: v })}
                />
                <Field
                  label="Surface (m²)"
                  placeholder="120"
                  keyboardType="numeric"
                  containerStyle={styles.gridItem}
                  value={data.surface || ""}
                  onChange={(v) => setData({ ...data, surface: v })}
                />
                <Field
                  label="Quartier"
                  placeholder="Nom du quartier"
                  containerStyle={styles.gridItem}
                  value={data.quartier || ""}
                  onChange={(v) => setData({ ...data, quartier: v })}
                />
              </View>

              <Field
                label="Ville"
                placeholder="Ex: Niamey"
                value={data.ville || ""}
                onChange={(v) => setData({ ...data, ville: v })}
              />

              <Field
                label="Pays"
                placeholder="Ex: Niger"
                value={data.pays || ""}
                onChange={(v) => setData({ ...data, pays: v })}
              />
            </View>
          )}

          {type === "parcelle" && (
            <View style={styles.section}>
              <Text style={styles.sectionTitle}>Détails du terrain</Text>
              <Field
                label="Surface (m²)"
                placeholder="Ex: 500"
                keyboardType="numeric"
                value={data.surface || ""}
                onChange={(v) => setData({ ...data, surface: v })}
              />
              <Field
                label="Quartier"
                placeholder="Nom du quartier"
                value={data.quartier || ""}
                onChange={(v) => setData({ ...data, quartier: v })}
              />
              <Field
                label="Ville"
                placeholder="Ex: Niamey"
                value={data.ville || ""}
                onChange={(v) => setData({ ...data, ville: v })}
              />
              <Field
                label="Type de parcelle"
                placeholder="Résidentielle"
                value={data.type_parcelle || ""}
                onChange={(v) => setData({ ...data, type_parcelle: v })}
              />
            </View>
          )}

          {type === "hotel" && (
            <View style={styles.section}>
              <Text style={styles.sectionTitle}>Détails de l'hôtel</Text>
              <Field
                label="Catégorie (étoiles)"
                placeholder="Ex: 3"
                keyboardType="numeric"
                value={data.categorie || ""}
                onChange={(v) => setData({ ...data, categorie: v })}
              />
              <Field
                label="Prix par nuit (FCFA)"
                placeholder="Ex: 25000"
                keyboardType="numeric"
                value={data.prix_nuit || ""}
                onChange={(v) => setData({ ...data, prix_nuit: v })}
              />
              <Field
                label="Ville"
                placeholder="Ex: Niamey"
                value={data.ville || ""}
                onChange={(v) => setData({ ...data, ville: v })}
              />
              <Field
                label="Nombre de chambres"
                placeholder="Ex: 20"
                keyboardType="numeric"
                value={data.nombre_chambres || ""}
                onChange={(v) => setData({ ...data, nombre_chambres: v })}
              />
            </View>
          )}

          {/* Bouton de publication */}
          <TouchableOpacity
            disabled={loading}
            onPress={submit}
            style={styles.publishButton}
            activeOpacity={0.8}
          >
            <LinearGradient
              colors={loading ? ["#CCC", "#AAA"] : ["#6C63FF", "#FF6B9D"]}
              style={styles.publishButtonGradient}
            >
              {loading ? (
                <ActivityIndicator color="#FFF" />
              ) : (
                <>
                  <Ionicons name="rocket-outline" size={22} color="#FFF" />
                  <Text style={styles.publishButtonText}>Publier l'annonce</Text>
                </>
              )}
            </LinearGradient>
          </TouchableOpacity>
        </ScrollView>

        {/* Modal pour choisir la source de la photo */}
        <Modal
          visible={photoModalVisible}
          transparent
          animationType="fade"
          onRequestClose={() => setPhotoModalVisible(false)}
        >
          <TouchableOpacity
            style={styles.modalOverlay}
            activeOpacity={1}
            onPress={() => setPhotoModalVisible(false)}
          >
            <View style={styles.modalContent}>
              <Text style={styles.modalTitle}>Ajouter des photos</Text>

              <TouchableOpacity
                style={styles.modalOption}
                onPress={takePhoto}
                activeOpacity={0.7}
              >
                <View style={[styles.modalIcon, { backgroundColor: "#4CAF50" }]}>
                  <Ionicons name="camera" size={28} color="#FFF" />
                </View>
                <View style={styles.modalOptionText}>
                  <Text style={styles.modalOptionTitle}>Prendre une photo</Text>
                  <Text style={styles.modalOptionSubtitle}>Utiliser la caméra</Text>
                </View>
              </TouchableOpacity>

              <TouchableOpacity
                style={styles.modalOption}
                onPress={pickImagesFromGallery}
                activeOpacity={0.7}
              >
                <View style={[styles.modalIcon, { backgroundColor: "#2196F3" }]}>
                  <Ionicons name="images" size={28} color="#FFF" />
                </View>
                <View style={styles.modalOptionText}>
                  <Text style={styles.modalOptionTitle}>Choisir depuis la galerie</Text>
                  <Text style={styles.modalOptionSubtitle}>Sélectionner des photos</Text>
                </View>
              </TouchableOpacity>

              <TouchableOpacity
                style={styles.cancelButton}
                onPress={() => setPhotoModalVisible(false)}
              >
                <Text style={styles.cancelButtonText}>Annuler</Text>
              </TouchableOpacity>
            </View>
          </TouchableOpacity>
        </Modal>
      </KeyboardAvoidingView>

  );
};


