import React from 'react';
import { Platform, StatusBar, 
  View,
  Text,
  StyleSheet,
  ScrollView,
  Image,
  TouchableOpacity,
  Linking,
  Dimensions
} from 'react-native';
import Ionicons from 'react-native-vector-icons/Ionicons';
import { useTheme } from '../context/ThemeContext.js';
import { useThemedStyles } from '../hooks/useThemedStyles';

const { width } = Dimensions.get('window');

const About = () => {
  const { isDarkMode } = useTheme();
  const { createThemedStyles, theme } = useThemedStyles();
  const styles = createThemedStyles(themedStyles);

  // Équipe corrigée avec les vrais noms
  const team = [
    { name: 'Ismaël Cissé', role: 'CEO & Fondateur', image: null },
    { name: 'Abdoul Malik', role: 'Co-fondateur & Directeur Technique', image: null },
    { name: 'Nasser', role: 'Lead Developer', image: null }
  ];

  const socialLinks = [
    { icon: 'logo-facebook', url: 'https://facebook.com/villana', color: '#1877f2' },
    { icon: 'logo-twitter', url: 'https://twitter.com/villana', color: '#1da1f2' },
    { icon: 'logo-linkedin', url: 'https://linkedin.com/company/villana', color: '#0077b5' },
    { icon: 'logo-instagram', url: 'https://instagram.com/villana', color: '#e4405f' }
  ];

  return (
    <ScrollView 
      style={[styles.container, isDarkMode && styles.darkContainer]}
      contentContainerStyle={styles.scrollContent}
      showsVerticalScrollIndicator={false}
    >
      <View style={styles.header}>
        <View style={styles.logoContainer}>
          <Image 
            source={require('../assets/viconcol.png')} 
            style={styles.logo}
            resizeMode="contain"
          />
        </View>
        
        <Text style={[styles.version, isDarkMode && styles.darkSubText]}>Version 1.0.0</Text>
      </View>

      <View style={styles.section}>
        <Text style={[styles.sectionTitle, isDarkMode && styles.darkText]}>Notre histoire</Text>
        <Text style={[styles.description, isDarkMode && styles.darkSubText]}>
          Villana est une plateforme innovante dédiée à la location immobilière au Niger et en Afrique. 
          Fondée en 2023, notre mission est de simplifier la recherche et la gestion de 
          biens immobiliers pour les particuliers et les professionnels.
        </Text>
      </View>

      <View style={styles.section}>
        <Text style={[styles.sectionTitle, isDarkMode && styles.darkText]}>Notre mission</Text>
        <Text style={[styles.description, isDarkMode && styles.darkSubText]}>
          Rendre l'immobilier accessible à tous au Niger en offrant une plateforme fiable, 
          transparente et facile à utiliser. Nous connectons propriétaires et locataires 
          dans un environnement sécurisé.
        </Text>
      </View>

      <View style={styles.section}>
        <Text style={[styles.sectionTitle, isDarkMode && styles.darkText]}>Nos valeurs</Text>
        <View style={styles.valuesGrid}>
          <View style={styles.valueItem}>
            <Ionicons name="shield-checkmark" size={30} color={theme.primary} />
            <Text style={[styles.valueTitle, isDarkMode && styles.darkText]}>Fiabilité</Text>
            <Text style={[styles.valueDesc, isDarkMode && styles.darkSubText]}>Annonces vérifiées</Text>
          </View>
          <View style={styles.valueItem}>
            <Ionicons name="flash" size={30} color={theme.primary} />
            <Text style={[styles.valueTitle, isDarkMode && styles.darkText]}>Rapidité</Text>
            <Text style={[styles.valueDesc, isDarkMode && styles.darkSubText]}>Mise en relation instantanée</Text>
          </View>
          <View style={styles.valueItem}>
            <Ionicons name="people" size={30} color={theme.primary} />
            <Text style={[styles.valueTitle, isDarkMode && styles.darkText]}>Communauté</Text>
            <Text style={[styles.valueDesc, isDarkMode && styles.darkSubText]}>Plus de 10k utilisateurs</Text>
          </View>
        </View>
      </View>

      <View style={styles.section}>
        <Text style={[styles.sectionTitle, isDarkMode && styles.darkText]}>L'équipe</Text>
        <View style={styles.teamGrid}>
          {team.map((member, index) => (
            <View key={index} style={[styles.teamCard, isDarkMode && styles.darkCard]}>
              <View style={[styles.teamAvatar, { backgroundColor: theme.primary + '20' }]}>
                <Ionicons name="person" size={40} color={theme.primary} />
              </View>
              <Text style={[styles.teamName, isDarkMode && styles.darkText]}>{member.name}</Text>
              <Text style={[styles.teamRole, isDarkMode && styles.darkSubText]}>{member.role}</Text>
            </View>
          ))}
        </View>
      </View>

      <View style={styles.section}>
        <Text style={[styles.sectionTitle, isDarkMode && styles.darkText]}>Suivez-nous</Text>
        <View style={styles.socialLinks}>
          {socialLinks.map((social, index) => (
            <TouchableOpacity
              key={index}
              style={[styles.socialButton, { backgroundColor: social.color }]}
              onPress={() => Linking.openURL(social.url)}
            >
              <Ionicons name={social.icon} size={24} color="#fff" />
            </TouchableOpacity>
          ))}
        </View>
      </View>

      <View style={styles.footer}>
        <Text style={[styles.footerText, isDarkMode && styles.darkSubText]}>
          © 2023-2025 Villana. Tous droits réservés.
        </Text>
        <Text style={[styles.footerText, isDarkMode && styles.darkSubText]}>
          Made with ❤️ in Niger
        </Text>
      </View>
    </ScrollView>
  );
};

const themedStyles = (theme, isDarkMode, Platform, StatusBar) => StyleSheet.create({
  container: { flex: 1, backgroundColor: theme.background },
  darkContainer: { backgroundColor: '#1a1a1a' },
  darkCard: { backgroundColor: '#2d2d2d' },
  darkText: { color: '#fff' },
  darkSubText: { color: '#aaa' },
  
  scrollContent: { flexGrow: 1 },
  
  header: { 
    alignItems: 'center', 
    paddingTop: 30,
    paddingBottom: 20,
    paddingHorizontal: 20,
    backgroundColor: theme.card,
    marginBottom: 10
  },
  logoContainer: {
    width: width * 0.4,
    height: width * 0.4,
    maxWidth: 150,
    maxHeight: 150,
    justifyContent: 'center',
    alignItems: 'center',
    marginBottom: 15,
    overflow: 'visible'
  },
  logo: { 
    width: '100%', 
    height: '100%',
    borderRadius: 20
  },
  appName: { fontSize: 28, fontWeight: 'bold', color: theme.text, marginBottom: 5 },
  version: { fontSize: 14, color: theme.subText },
  
  section: { padding: 20, marginBottom: 10 },
  sectionTitle: { fontSize: 20, fontWeight: 'bold', color: theme.text, marginBottom: 15 },
  description: { fontSize: 14, color: theme.subText, lineHeight: 22 },
  
  valuesGrid: { flexDirection: 'row', justifyContent: 'space-around', marginTop: 10, flexWrap: 'wrap' },
  valueItem: { alignItems: 'center', flex: 1, minWidth: 100, padding: 10 },
  valueTitle: { fontSize: 14, fontWeight: '600', color: theme.text, marginTop: 10, marginBottom: 5 },
  valueDesc: { fontSize: 12, color: theme.subText, textAlign: 'center' },
  
  teamGrid: { flexDirection: 'row', gap: 15, flexWrap: 'wrap' },
  teamCard: { 
    flex: 1, 
    minWidth: 100, 
    alignItems: 'center', 
    backgroundColor: theme.card, 
    padding: 15, 
    borderRadius: 12,
    elevation: 2,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 1 },
    shadowOpacity: 0.1,
    shadowRadius: 2
  },
  teamAvatar: { width: 80, height: 80, borderRadius: 40, justifyContent: 'center', alignItems: 'center', marginBottom: 10 },
  teamName: { fontSize: 14, fontWeight: '600', color: theme.text, marginBottom: 4, textAlign: 'center' },
  teamRole: { fontSize: 12, color: theme.subText, textAlign: 'center' },
  
  socialLinks: { flexDirection: 'row', justifyContent: 'center', gap: 15, flexWrap: 'wrap' },
  socialButton: { width: 50, height: 50, borderRadius: 25, justifyContent: 'center', alignItems: 'center' },
  
  footer: { alignItems: 'center', padding: 20, marginTop: 20, marginBottom: 30 },
  footerText: { fontSize: 12, color: theme.subText, marginBottom: 5, textAlign: 'center' },
});

export default About;


