import React, { useState, useEffect, useCallback } from 'react';
import { Platform, StatusBar, 
  View,
  Text,
  StyleSheet,
  FlatList,
  TouchableOpacity,
  Alert,
  RefreshControl,
  ActivityIndicator,
  Modal,
  TextInput,
  ScrollView
} from 'react-native';
import Ionicons from 'react-native-vector-icons/Ionicons';
import {  useNavigation, useFocusEffect } from '@react-navigation/native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import axios from 'axios';
import Config from './Config';
import {  useTheme } from '../context/ThemeContext.js';
import { useThemedStyles } from '../hooks/useThemedStyles';

const MyProperties = () => {
  const navigation = useNavigation();
  const { isDarkMode } = useTheme();
  const { createThemedStyles, theme } = useThemedStyles();
  const styles = createThemedStyles(themedStyles);
  
  const [properties, setProperties] = useState([]);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [selectedProperty, setSelectedProperty] = useState(null);
  const [modalVisible, setModalVisible] = useState(false);
  const [deleteConfirmVisible, setDeleteConfirmVisible] = useState(false);

  useFocusEffect(
    useCallback(() => {
      fetchProperties();
    }, [])
  );

  const fetchProperties = async () => {
    try {
      const token = await AsyncStorage.getItem('access_token');
      if (!token) {
        navigation.navigate('Login');
        return;
      }

      const response = await axios.get(`${Config.BASE_URL}/api/properties/my-properties/`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      
      setProperties(response.data);
    } catch (error) {
      console.error('Erreur chargement biens:', error);
      Alert.alert('Erreur', 'Impossible de charger vos biens');
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  const onRefresh = () => {
    setRefreshing(true);
    fetchProperties();
  };

  const handleDeleteProperty = async () => {
    if (!selectedProperty) return;
    
    try {
      const token = await AsyncStorage.getItem('access_token');
      await axios.delete(`${Config.BASE_URL}/api/properties/${selectedProperty.id}/`, {
        headers: { Authorization: `Bearer ${token}` }
      });
      
      Alert.alert('Succès', 'Bien supprimé avec succès');
      setDeleteConfirmVisible(false);
      setSelectedProperty(null);
      fetchProperties();
    } catch (error) {
      Alert.alert('Erreur', 'Impossible de supprimer ce bien');
    }
  };

  const getStatusColor = (status) => {
    switch(status) {
      case 'available': return theme.success;
      case 'rented': return theme.error;
      case 'pending': return theme.warning;
      default: return theme.subText;
    }
  };

  const getStatusText = (status) => {
    switch(status) {
      case 'available': return 'Disponible';
      case 'rented': return 'Loué';
      case 'pending': return 'En attente';
      default: return status;
    }
  };

  const renderPropertyCard = ({ item }) => (
    <TouchableOpacity 
      style={styles.propertyCard}
      onPress={() => navigation.navigate('PropertyDetail', { propertyId: item.id })}
      activeOpacity={0.7}
    >
      <View style={styles.cardHeader}>
        <View style={styles.propertyType}>
          <Ionicons name="home" size={20} color={theme.primary} />
          <Text style={[styles.propertyTitle, isDarkMode && styles.darkText]}>{item.title}</Text>
        </View>
        <View style={[styles.statusBadge, { backgroundColor: getStatusColor(item.status) }]}>
          <Text style={styles.statusText}>{getStatusText(item.status)}</Text>
        </View>
      </View>
      
      <View style={styles.propertyDetails}>
        <View style={styles.detailItem}>
          <Ionicons name="location-outline" size={16} color={theme.subText} />
          <Text style={[styles.detailText, isDarkMode && styles.darkSubText]}>{item.location}</Text>
        </View>
        <View style={styles.detailItem}>
          <Ionicons name="cash-outline" size={16} color={theme.subText} />
          <Text style={[styles.detailText, isDarkMode && styles.darkSubText]}>{item.price} FCFA/mois</Text>
        </View>
        <View style={styles.detailItem}>
          <Ionicons name="resize-outline" size={16} color={theme.subText} />
          <Text style={[styles.detailText, isDarkMode && styles.darkSubText]}>{item.area} m²</Text>
        </View>
      </View>
      
      <View style={styles.cardActions}>
        <TouchableOpacity 
          style={[styles.actionButton, styles.editButton]}
          onPress={() => navigation.navigate('EditProperty', { propertyId: item.id })}
        >
          <Ionicons name="create-outline" size={20} color="#fff" />
          <Text style={styles.actionButtonText}>Modifier</Text>
        </TouchableOpacity>
        
        <TouchableOpacity 
          style={[styles.actionButton, styles.deleteButton]}
          onPress={() => {
            setSelectedProperty(item);
            setDeleteConfirmVisible(true);
          }}
        >
          <Ionicons name="trash-outline" size={20} color="#fff" />
          <Text style={styles.actionButtonText}>Supprimer</Text>
        </TouchableOpacity>
      </View>
    </TouchableOpacity>
  );

  if (loading) {
    return (
      <View style={[styles.container, isDarkMode && styles.darkContainer, styles.centerContent]}>
        <ActivityIndicator size="large" color={theme.primary} />
      </View>
    );
  }

  return (
    <View style={[styles.container, isDarkMode && styles.darkContainer]}>
      <View style={styles.header}>
        <Text style={[styles.headerTitle, isDarkMode && styles.darkText]}>Mes Biens</Text>
        <TouchableOpacity 
          style={styles.addButton}
          onPress={() => navigation.navigate('AddProperty')}
        >
          <Ionicons name="add-circle" size={24} color={theme.primary} />
          <Text style={styles.addButtonText}>Ajouter</Text>
        </TouchableOpacity>
      </View>
      
      {properties.length === 0 ? (
        <View style={styles.emptyContainer}>
          <Ionicons name="home-outline" size={80} color={theme.subText} />
          <Text style={[styles.emptyText, isDarkMode && styles.darkSubText]}>
            Vous n'avez aucun bien immobilier
          </Text>
          <TouchableOpacity 
            style={styles.emptyButton}
            onPress={() => navigation.navigate('AddProperty')}
          >
            <Text style={styles.emptyButtonText}>Ajouter mon premier bien</Text>
          </TouchableOpacity>
        </View>
      ) : (
        <FlatList
          data={properties}
          renderItem={renderPropertyCard}
          keyExtractor={(item) => item.id.toString()}
          refreshControl={
            <RefreshControl refreshing={refreshing} onRefresh={onRefresh} />
          }
          contentContainerStyle={styles.listContainer}
        />
      )}
      
      {/* Modal de confirmation de suppression */}
      <Modal
        animationType="fade"
        transparent={true}
        visible={deleteConfirmVisible}
        onRequestClose={() => setDeleteConfirmVisible(false)}
      >
        <View style={styles.modalOverlay}>
          <View style={[styles.modalContent, isDarkMode && styles.darkCard]}>
            <Ionicons name="warning" size={50} color={theme.error} />
            <Text style={[styles.modalTitle, isDarkMode && styles.darkText]}>Confirmation</Text>
            <Text style={[styles.modalText, isDarkMode && styles.darkSubText]}>
              Êtes-vous sûr de vouloir supprimer ce bien ?
            </Text>
            <View style={styles.modalButtons}>
              <TouchableOpacity 
                style={[styles.modalButton, styles.cancelButton]}
                onPress={() => setDeleteConfirmVisible(false)}
              >
                <Text style={styles.cancelButtonText}>Annuler</Text>
              </TouchableOpacity>
              <TouchableOpacity 
                style={[styles.modalButton, styles.confirmButton]}
                onPress={handleDeleteProperty}
              >
                <Text style={styles.confirmButtonText}>Supprimer</Text>
              </TouchableOpacity>
            </View>
          </View>
        </View>
      </Modal>
    </View>
  );
};

const themedStyles = (theme, isDarkMode, Platform, StatusBar) => StyleSheet.create({
  container: {
          flex: 1,
          backgroundColor: theme.background,
          paddingTop: Platform.OS === 'android' ? StatusBar.currentHeight : 0,
        },
  darkContainer: { backgroundColor: '#1a1a1a' },
  darkCard: { backgroundColor: '#2d2d2d' },
  darkText: { color: '#fff' },
  darkSubText: { color: '#aaa' },
  
  centerContent: { justifyContent: 'center', alignItems: 'center' },
  
  header: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    padding: 20,
    backgroundColor: theme.card,
    borderBottomWidth: 1,
    borderBottomColor: theme.border,
  },
  headerTitle: { fontSize: 24, fontWeight: 'bold', color: theme.text },
  addButton: { flexDirection: 'row', alignItems: 'center', gap: 5 },
  addButtonText: { color: theme.primary, fontSize: 16, fontWeight: '600' },
  
  listContainer: { padding: 15 },
  propertyCard: {
    backgroundColor: theme.card,
    borderRadius: 12,
    padding: 15,
    marginBottom: 15,
    elevation: 3,
  },
  cardHeader: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 10,
  },
  propertyType: { flexDirection: 'row', alignItems: 'center', gap: 8 },
  propertyTitle: { fontSize: 18, fontWeight: 'bold', color: theme.text },
  statusBadge: { paddingHorizontal: 10, paddingVertical: 4, borderRadius: 12 },
  statusText: { color: '#fff', fontSize: 12, fontWeight: '600' },
  
  propertyDetails: { gap: 8, marginBottom: 15 },
  detailItem: { flexDirection: 'row', alignItems: 'center', gap: 8 },
  detailText: { fontSize: 14, color: theme.subText },
  
  cardActions: { flexDirection: 'row', gap: 10, marginTop: 5 },
  actionButton: {
    flex: 1,
    flexDirection: 'row',
    alignItems: 'center',
    justifyContent: 'center',
    padding: 10,
    borderRadius: 8,
    gap: 8,
  },
  editButton: { backgroundColor: theme.primary },
  deleteButton: { backgroundColor: theme.error },
  actionButtonText: { color: '#fff', fontWeight: '600' },
  
  emptyContainer: { flex: 1, justifyContent: 'center', alignItems: 'center', padding: 20 },
  emptyText: { fontSize: 16, color: theme.subText, textAlign: 'center', marginTop: 20, marginBottom: 20 },
  emptyButton: { backgroundColor: theme.primary, paddingHorizontal: 20, paddingVertical: 12, borderRadius: 25 },
  emptyButtonText: { color: '#fff', fontWeight: '600' },
  
  modalOverlay: { flex: 1, backgroundColor: 'rgba(0,0,0,0.5)', justifyContent: 'center', alignItems: 'center' },
  modalContent: { backgroundColor: '#fff', borderRadius: 12, padding: 20, width: '80%', alignItems: 'center' },
  modalTitle: { fontSize: 20, fontWeight: 'bold', marginTop: 15, marginBottom: 10 },
  modalText: { fontSize: 16, textAlign: 'center', marginBottom: 20 },
  modalButtons: { flexDirection: 'row', gap: 10, width: '100%' },
  modalButton: { flex: 1, padding: 12, borderRadius: 8, alignItems: 'center' },
  cancelButton: { backgroundColor: '#f0f0f0' },
  cancelButtonText: { color: '#333', fontWeight: '600' },
  confirmButton: { backgroundColor: theme.error },
  confirmButtonText: { color: '#fff', fontWeight: '600' },
});

export default MyProperties;


