import React, { useState, useEffect } from 'react';
import { Platform, StatusBar,  
  View, 
  Text, 
  StyleSheet, 
  Image, 
  TouchableOpacity, 
  FlatList, 
  ScrollView,
  Alert,
  Linking,
  SafeAreaView,
  ActivityIndicator,
  Switch
} from 'react-native';
import Ionicons from 'react-native-vector-icons/Ionicons';
import FontAwesome from 'react-native-vector-icons/FontAwesome';
import { useNavigation } from '@react-navigation/native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import axios from 'axios';
import Config from './Config';
import { useTheme } from '../context/ThemeContext.js';
import {  useThemedStyles } from '../hooks/useThemedStyles';

const MenuScreen = () => {
  const navigation = useNavigation();
  const { isDarkMode, toggleTheme } = useTheme(); // ← Récupère le thème du contexte
  const { createThemedStyles, theme } = useThemedStyles();
  const styles = createThemedStyles(themedStyles);
  
  const [user, setUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [unreadCount, setUnreadCount] = useState({ messages: 0, notifications: 0 });

  useEffect(() => {
    loadUserData();
    fetchUnreadCounts();
  }, []);

  const loadUserData = async () => {
    try {
      const userData = await AsyncStorage.getItem('user');
      if (userData) setUser(JSON.parse(userData));
    } catch (error) {
      console.error('Erreur chargement utilisateur:', error);
    } finally {
      setLoading(false);
    }
  };

  const fetchUnreadCounts = async () => {
    try {
      const token = await AsyncStorage.getItem('access_token');
      if (!token) return;

      const msgRes = await axios.get(`${Config.BASE_URL}/messages/conversations/`, {
        headers: { Authorization: `Bearer ${token}` }
      }).catch(() => ({ data: [] }));
      
      let unreadMessages = 0;
      if (Array.isArray(msgRes.data)) {
        unreadMessages = msgRes.data.reduce((total, conv) => total + (conv.unread_count || 0), 0);
      }

      const notifRes = await axios.get(`${Config.BASE_URL}/notifications/non_lues/`, {
        headers: { Authorization: `Bearer ${token}` }
      }).catch(() => ({ data: { count: 0 } }));

      setUnreadCount({
        messages: unreadMessages,
        notifications: notifRes.data?.count || 0
      });
    } catch (error) {
      console.error('Erreur chargement compteurs:', error);
    }
  };

  const handleLogout = async () => {
    Alert.alert('Déconnexion', 'Voulez-vous vous déconnecter ?', [
      { text: 'Annuler', style: 'cancel' },
      {
        text: 'Déconnexion',
        style: 'destructive',
        onPress: async () => {
          await AsyncStorage.clear();
          navigation.reset({ index: 0, routes: [{ name: 'Login' }] });
        }
      }
    ]);
  };

  const navigateTo = (screen, params = {}) => {
    if (screen === 'logout') handleLogout();
    else if (screen === 'privacy' || screen === 'conditions') Linking.openURL(`${Config.BASE_URL}/${screen}`);
    else navigation.navigate(screen, params);
  };

  const mainMenu = [
    { id: 'my_properties', title: 'Mes biens', icon: 'home', color: '#FF9800', screen: 'MyProperties' },
    { id: 'favorites', title: 'Favoris', icon: 'heart', color: '#E91E63', screen: 'FavoriScreen', badge: 'favorites' },
    { id: 'messages', title: 'Messages', icon: 'chatbubble', color: '#4CAF50', screen: 'Messages', badge: 'messages' },
    { id: 'notifications', title: 'Notifications', icon: 'notifications', color: '#2196F3', screen: 'Notifications', badge: 'notifications' },
    { id: 'dashboard', title: 'Tableau de bord', icon: 'stats-chart', color: '#9C27B0', screen: 'Dashboard' },
    { id: 'professional', title: 'Devenir pro', icon: 'briefcase', color: '#795548', screen: 'ProfessionalAccess' },
  ];

  const secondaryMenu = [
    { id: 'help', title: 'Aide', icon: 'help-circle', color: '#00BCD4', screen: 'Help' },
    { id: 'contact_us', title: 'Contact', icon: 'mail', color: '#FF5722', screen: 'ContactForm' },
    { id: 'privacy', title: 'Confidentialité', icon: 'shield', color: '#607D8B', screen: 'privacy' },
    { id: 'about', title: 'À Propos', icon: 'information-circle', color: '#009688', screen: 'About' },
    { id: 'logout', title: 'Déconnexion', icon: 'log-out', color: '#FF3B30', screen: 'logout' },
  ];

  const renderMenuItem = ({ item }) => (
    <TouchableOpacity style={styles.menuItem} onPress={() => navigateTo(item.screen)} activeOpacity={0.7}>
      <View style={[styles.iconContainer, { backgroundColor: `${item.color}20` }]}>
        <Ionicons name={item.icon} size={24} color={item.color} />
        {item.badge && unreadCount[item.badge] > 0 && (
          <View style={styles.badge}>
            <Text style={styles.badgeText}>{unreadCount[item.badge] > 99 ? '99+' : unreadCount[item.badge]}</Text>
          </View>
        )}
      </View>
      <Text style={[styles.menuItemText, isDarkMode && styles.darkText]}>{item.title}</Text>
    </TouchableOpacity>
  );

  const renderSettingItem = ({ item }) => (
    <TouchableOpacity style={styles.settingItem} onPress={() => navigateTo(item.screen)} activeOpacity={0.7}>
      <View style={styles.settingInfo}>
        <Ionicons name={item.icon} size={22} color={item.color} />
        <Text style={[styles.settingLabel, isDarkMode && styles.darkText]}>{item.title}</Text>
      </View>
      <Ionicons name="chevron-forward" size={20} color={theme.subText} />
    </TouchableOpacity>
  );

  if (loading) {
    return (
      <SafeAreaView style={[styles.container, isDarkMode && styles.darkContainer]}>
        <StatusBar barStyle={isDarkMode ? "light-content" : "dark-content"} />
        <View style={styles.loadingContainer}>
          <ActivityIndicator size="large" color={theme.primary} />
        </View>
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView style={[styles.container, isDarkMode && styles.darkContainer]}>
      <StatusBar barStyle={isDarkMode ? "light-content" : "dark-content"} />
      <ScrollView showsVerticalScrollIndicator={false}>
        
        {/* Profil utilisateur */}
        <View style={[styles.header, isDarkMode && styles.darkCard]}>
          <TouchableOpacity onPress={() => navigateTo('ProfilScreen')}>
            <Image 
              source={user?.avatar ? { uri: user.avatar } : require('../assets/profil.jpg')} 
              style={styles.profileImage}
            />
          </TouchableOpacity>
          <View style={styles.userInfo}>
            <Text style={[styles.userName, isDarkMode && styles.darkText]}>{user?.username || 'Invité'}</Text>
            <Text style={[styles.userEmail, isDarkMode && styles.darkSubText]}>{user?.email || 'Connectez-vous'}</Text>
            {user && (
              <View style={styles.userBadges}>
                {user.is_proprietaire && (
                  <View style={styles.badgeProprietaire}>
                    <FontAwesome name="home" size={12} color="#fff" />
                    <Text style={styles.badgeTextSmall}>Propriétaire</Text>
                  </View>
                )}
                {user.is_verified && (
                  <View style={styles.badgeVerified}>
                    <FontAwesome name="check-circle" size={12} color="#fff" />
                    <Text style={styles.badgeTextSmall}>Vérifié</Text>
                  </View>
                )}
              </View>
            )}
          </View>
          {/* Bouton pour changer le thème */}
          <TouchableOpacity onPress={toggleTheme} style={[styles.themeToggle, isDarkMode && styles.darkThemeToggle]}>
            <Ionicons name={isDarkMode ? 'sunny' : 'moon'} size={24} color={isDarkMode ? '#FFD700' : '#444'} />
          </TouchableOpacity>
        </View>

        {/* Menu principal */}
        <View style={[styles.section, isDarkMode && styles.darkCard]}>
          <Text style={[styles.sectionTitle, isDarkMode && styles.darkText]}>Menu</Text>
          <FlatList data={mainMenu} renderItem={renderMenuItem} keyExtractor={(item) => item.id} numColumns={3} scrollEnabled={false} />
        </View>

        {/* Support */}
        <View style={[styles.section, isDarkMode && styles.darkCard]}>
          <Text style={[styles.sectionTitle, isDarkMode && styles.darkText]}>Support</Text>
          <FlatList data={secondaryMenu} renderItem={renderSettingItem} keyExtractor={(item) => item.id} scrollEnabled={false} />
        </View>

        {/* Version */}
        <View style={styles.versionContainer}>
          <Text style={[styles.versionText, isDarkMode && styles.darkSubText]}>Version 1.0.0</Text>
          <Text style={[styles.copyrightText, isDarkMode && styles.darkSubText]}>© 2025 Villana</Text>
        </View>
      </ScrollView>
    </SafeAreaView>
  );
};

const themedStyles = (theme, isDarkMode, Platform, StatusBar) => StyleSheet.create({
    container: {
      flex: 1,
      backgroundColor: theme.background,
      paddingTop: Platform.OS === 'android' ? StatusBar.currentHeight : 0,
    },
  darkContainer: { backgroundColor: '#1a1a1a' },
  darkCard: { backgroundColor: '#2d2d2d' },
  darkText: { color: '#fff' },
  darkSubText: { color: '#aaa' },
  darkThemeToggle: { backgroundColor: '#3d3d3d' },
  
  loadingContainer: { flex: 1, justifyContent: 'center', alignItems: 'center' },
  
  header: {
    flexDirection: 'row',
    alignItems: 'center',
    padding: 20,
    backgroundColor: theme.card,
    margin: 15,
    borderRadius: 20,
    elevation: 3,
  },
  profileImage: { width: 70, height: 70, borderRadius: 35, marginRight: 15, borderWidth: 2, borderColor: theme.primary },
  userInfo: { flex: 1 },
  userName: { fontSize: 20, fontWeight: 'bold', color: theme.text, marginBottom: 2 },
  userEmail: { fontSize: 13, color: theme.subText, marginBottom: 5 },
  userBadges: { flexDirection: 'row', gap: 8 },
  badgeProprietaire: { flexDirection: 'row', alignItems: 'center', backgroundColor: theme.primary, paddingHorizontal: 8, paddingVertical: 3, borderRadius: 12, gap: 4 },
  badgeVerified: { flexDirection: 'row', alignItems: 'center', backgroundColor: theme.success, paddingHorizontal: 8, paddingVertical: 3, borderRadius: 12, gap: 4 },
  badgeTextSmall: { fontSize: 11, color: '#fff' },
  themeToggle: { padding: 8, backgroundColor: theme.iconBackground, borderRadius: 20 },
  
  section: { backgroundColor: theme.card, marginHorizontal: 15, marginBottom: 15, padding: 15, borderRadius: 15 },
  sectionTitle: { fontSize: 18, fontWeight: 'bold', color: theme.primary, marginBottom: 15 },
  
  menuItem: { flex: 1, alignItems: 'center', margin: 5, paddingVertical: 12, backgroundColor: theme.card, borderRadius: 12, elevation: 1, maxWidth: 105 },
  iconContainer: { width: 45, height: 45, borderRadius: 23, justifyContent: 'center', alignItems: 'center', marginBottom: 5, position: 'relative' },
  badge: { position: 'absolute', top: -5, right: -5, backgroundColor: theme.error, minWidth: 18, height: 18, borderRadius: 9, justifyContent: 'center', alignItems: 'center', paddingHorizontal: 3 },
  badgeText: { color: '#fff', fontSize: 10, fontWeight: 'bold' },
  menuItemText: { fontSize: 11, fontWeight: '600', textAlign: 'center' },
  
  settingItem: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingVertical: 12, borderBottomWidth: 1, borderBottomColor: theme.border },
  settingInfo: { flexDirection: 'row', alignItems: 'center', flex: 1 },
  settingLabel: { fontSize: 15, marginLeft: 12, flex: 1 },
  
  versionContainer: { alignItems: 'center', marginVertical: 30 },
  versionText: { fontSize: 13, marginBottom: 3 },
  copyrightText: { fontSize: 11 },
});

export default MenuScreen;


