import React from 'react';
import { NavigationContainer } from '@react-navigation/native';
import { createStackNavigator } from '@react-navigation/stack';

// Import des écrans - GROUPÉS PAR CATÉGORIE
// ========================================

// Écrans principaux (tabs)
//import TabNavigator from '../Navigations/TabNavigator';
import Accueil from '../components/Accueil';

// Auth
import LoginScreen from '../components/loginscreen';
import RegistrationScreen from '../components/RegistrationScreen';

// Profil
import ProfilScreen from '../components/ProfileScreen';
import EditProfil from '../components/EditProfil';

// Annonces
import MaisonList from '../components/MaisonList';
import MaisonDetail from '../components/MaisonDetail';
import HotelsDetails from '../components/HotelsDetails';
import PublishScreen from '../components/PublishScreen';
import FavoriScreen from '../components/FavoriScreen';
import AdddMenu from '../components/AddMenu';
import MenuScreen from '../components/MenuScreen';

// Recherche
import SearchScreen from '../components/SearchScreen';
import SearchUsersScreen from '../components/SearchUsersScreen';

// Messages & Notifications
import TextoScreen from '../components/TextoScreen';
import NotificationsScreen from '../components/NotificationScreen';
import MessageScreen from '../components/MessageScreen';

// Images
import ImageDetails from '../components/ImageDetails';

// ========== NOUVEAUX ÉCRANS ==========
// Gestion des biens
import MyProperties from '../components/MyProperties';
import AddProperty from '../components/AddProperty';
import EditProperty from '../components/EditProperty';
import PropertyDetail from '../components/PropertyDetail';

// Dashboard & Professionnel
import Dashboard from '../components/Dashboard';
import ProfessionalAccess from '../components/ProfessionalAccess';

// Support
import Help from '../components/Help';
import ContactForm from '../components/ContactForm';
import About from '../components/About';

const Stack = createStackNavigator();

const MainNavigator = () => {
  return (
    <NavigationContainer>
      <Stack.Navigator 
        initialRouteName="Accueil"
        screenOptions={{
          headerShown: false,
          gestureEnabled: true,
        }}
      >
        {/* ========== ÉCRAN PRINCIPAL ========== */}
        {/* <Stack.Screen name="TabNavigator" component={TabNavigator} /> */}
        <Stack.Screen name="Accueil" component={Accueil} />

        {/* ========== AUTHENTIFICATION ========== */}
        <Stack.Screen name="LoginScreen" component={LoginScreen} />
        <Stack.Screen name="RegistrationScreen" component={RegistrationScreen} />

        {/* ========== PROFIL ========== */}
        <Stack.Screen name="ProfilScreen" component={ProfilScreen} />
        <Stack.Screen name="EditProfil" component={EditProfil} />

        {/* ========== ANNONCES ========== */}
        <Stack.Screen name="MaisonList" component={MaisonList} />
        <Stack.Screen name="MaisonDetail" component={MaisonDetail} />
        <Stack.Screen name="HotelsDetails" component={HotelsDetails} />
        <Stack.Screen name="PublishScreen" component={PublishScreen} />
        <Stack.Screen name="FavoriScreen" component={FavoriScreen} />
        <Stack.Screen name="AddMenus" component={AdddMenu} />

        {/* ========== RECHERCHE ========== */}
        <Stack.Screen name="Search" component={SearchScreen} />
        <Stack.Screen name="SearchUsersScreen" component={SearchUsersScreen} />

        {/* ========== MESSAGES & NOTIFICATIONS ========== */}
        <Stack.Screen name="TextoScreen" component={TextoScreen} />
        <Stack.Screen name="Messages" component={MessageScreen} />
        <Stack.Screen name="Notifications" component={NotificationsScreen} />

        {/* ========== IMAGES ========== */}
        <Stack.Screen name="ImageDetails" component={ImageDetails} />
        
        {/* ========== MENU ========== */}
        <Stack.Screen name="Menu" component={MenuScreen} />

        {/* ========== GESTION DES BIENS IMMOBILIERS ========== */}
        <Stack.Screen name="MyProperties" component={MyProperties} />
        <Stack.Screen name="AddProperty" component={AddProperty} />
        <Stack.Screen name="EditProperty" component={EditProperty} />
        <Stack.Screen name="PropertyDetail" component={PropertyDetail} />

        {/* ========== TABLEAU DE BORD & PROFESSIONNEL ========== */}
        <Stack.Screen name="Dashboard" component={Dashboard} />
        <Stack.Screen name="ProfessionalAccess" component={ProfessionalAccess} />

        {/* ========== SUPPORT & INFORMATION ========== */}
        <Stack.Screen name="Help" component={Help} />
        <Stack.Screen name="ContactForm" component={ContactForm} />
        <Stack.Screen name="About" component={About} />
      </Stack.Navigator>
    </NavigationContainer>
  );
};

export default MainNavigator;