import React, { useState, useRef, useEffect, useCallback } from 'react';
import {
  View,
  TextInput,
  Text,
  Image,
  StyleSheet,
  Animated,
  Keyboard,
  KeyboardAvoidingView,
  Platform,
  FlatList,
  TouchableOpacity,
  Alert,
  ActivityIndicator,
  Dimensions,
} from 'react-native';
import Ionicons from 'react-native-vector-icons/Ionicons';
import MaterialIcons from 'react-native-vector-icons/MaterialIcons';
import FontAwesome5 from 'react-native-vector-icons/FontAwesome5';
import MaterialCommunityIcons from 'react-native-vector-icons/MaterialCommunityIcons';
import { useRoute, useNavigation } from '@react-navigation/native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import axios from 'axios';
import LinearGradient from 'react-native-linear-gradient';
import Config from './Config';

const { width } = Dimensions.get('window');
const BASE_URL = Config.BASE_URL;

const ChatScreen = () => {
  const navigation = useNavigation();
  const route = useRoute();
  const { userName, userId, userAvatar } = route.params || {};
  
  const [messageText, setMessageText] = useState('');
  const [messages, setMessages] = useState([]);
  const [sending, setSending] = useState(false);
  const [loading, setLoading] = useState(true);
  const [token, setToken] = useState('');
  const [currentUserId, setCurrentUserId] = useState(null);

  const flatListRef = useRef(null);
  const keyboardHeight = useRef(new Animated.Value(0)).current;

  useEffect(() => {
    const init = async () => {
      const userToken = await AsyncStorage.getItem('userToken');
      const userData = await AsyncStorage.getItem('user');
      
      setToken(userToken);
      if (userData) {
        const parsedUser = JSON.parse(userData);
        setCurrentUserId(parsedUser.id);
      }
    };
    init();
  }, []);

  const loadMessages = useCallback(async () => {
    if (!token || !userId) return;

    try {
      setLoading(true);
      const response = await axios.get(`${BASE_URL}/messages/`, {
        params: { user: userId },
        headers: { Authorization: `Bearer ${token}` },
      });
      
      const sortedMessages = response.data.sort((a, b) => 
        new Date(a.created_at) - new Date(b.created_at)
      );
      
      setMessages(sortedMessages);
      
    } catch (error) {
      console.error("Erreur fetch messages:", error.response?.data || error.message);
    } finally {
      setLoading(false);
    }
  }, [token, userId]);

  useEffect(() => {
    if (token && userId) {
      loadMessages();
      // Polling pour les nouveaux messages
      const interval = setInterval(loadMessages, 3000);
      return () => clearInterval(interval);
    }
  }, [loadMessages, token, userId]);

  const markMessageAsRead = async (messageId) => {
    try {
      await axios.patch(
        `${BASE_URL}/messages/${messageId}/marquer_lu/`,
        {},
        { headers: { Authorization: `Bearer ${token}` } }
      );
    } catch (error) {
      console.error("Erreur mark as read:", error);
    }
  };

  const sendMessage = async () => {
    const trimmedText = messageText.trim();
    if (!trimmedText || !token || sending) return;

    setSending(true);
    
    try {
      const tempId = Date.now().toString();
      const tempMessage = {
        id: tempId,
        text: trimmedText,
        sender: currentUserId,
        receiver: userId,
        created_at: new Date().toISOString(),
        is_sending: true,
      };

      setMessages(prev => [...prev, tempMessage]);
      setMessageText('');
      
      const response = await axios.post(
        `${BASE_URL}/messages/`,
        {
          receiver: userId,
          text: trimmedText,
        },
        {
          headers: { Authorization: `Bearer ${token}` },
        }
      );

      // Remplacer le message temporaire par le message réel
      setMessages(prev =>
        prev.map(msg =>
          msg.id === tempId
            ? response.data
            : msg
        )
      );

      // Faire défiler vers le bas
      setTimeout(() => {
        flatListRef.current?.scrollToEnd({ animated: true });
      }, 100);

    } catch (error) {
      console.error("Erreur envoyer message:", error.response?.data || error.message);
      Alert.alert('Erreur', 'Impossible d\'envoyer le message');
      
      // Supprimer le message temporaire en cas d'erreur
      setMessages(prev => prev.filter(msg => msg.id !== tempId));
    } finally {
      setSending(false);
    }
  };

  const deleteMessage = async (messageId) => {
    Alert.alert(
      'Supprimer le message',
      'Êtes-vous sûr de vouloir supprimer ce message ?',
      [
        { text: 'Annuler', style: 'cancel' },
        {
          text: 'Supprimer',
          style: 'destructive',
          onPress: async () => {
            try {
              await axios.delete(`${BASE_URL}/messages/${messageId}/`, {
                headers: { Authorization: `Bearer ${token}` },
              });
              
              setMessages(prev => prev.filter(msg => msg.id !== messageId));
            } catch (error) {
              Alert.alert('Erreur', 'Impossible de supprimer le message');
            }
          },
        },
      ]
    );
  };

  const handleKeyboardShow = (event) => {
    Animated.timing(keyboardHeight, {
      toValue: event.endCoordinates.height,
      duration: 250,
      useNativeDriver: false,
    }).start();
    
    setTimeout(() => {
      flatListRef.current?.scrollToEnd({ animated: true });
    }, 100);
  };

  const handleKeyboardHide = () => {
    Animated.timing(keyboardHeight, {
      toValue: 0,
      duration: 250,
      useNativeDriver: false,
    }).start();
  };

  useEffect(() => {
    const showSubscription = Keyboard.addListener('keyboardDidShow', handleKeyboardShow);
    const hideSubscription = Keyboard.addListener('keyboardDidHide', handleKeyboardHide);
    
    return () => {
      showSubscription.remove();
      hideSubscription.remove();
    };
  }, []);

  const renderMessage = ({ item, index }) => {
    const isMe = item.sender === currentUserId;
    const previousMessage = messages[index - 1];
    const showDate = shouldShowDate(item, previousMessage);
    const showTime = shouldShowTime(item, previousMessage);

    // Marquer comme lu si c'est un message reçu
    if (!isMe && !item.is_read) {
      markMessageAsRead(item.id);
    }

    return (
      <View>
        {showDate && (
          <View style={styles.dateSeparator}>
            <Text style={styles.dateText}>
              {formatDate(item.created_at)}
            </Text>
          </View>
        )}

        <View style={[
          styles.messageContainer,
          isMe ? styles.messageContainerRight : styles.messageContainerLeft
        ]}>
          {!isMe && (
            <Image
              source={userAvatar ? { uri: userAvatar } : require('../assets/profil.jpg')}
              style={styles.avatar}
            />
          )}
          
          <TouchableOpacity
            activeOpacity={0.8}
            onLongPress={() => deleteMessage(item.id)}
            delayLongPress={500}
          >
            <LinearGradient
              colors={isMe ? ['#6C63FF', '#3A7BD5'] : ['#F0F2FF', '#FFFFFF']}
              start={{ x: 0, y: 0 }}
              end={{ x: 1, y: 1 }}
              style={[
                styles.messageBubble,
                isMe ? styles.messageBubbleRight : styles.messageBubbleLeft,
                item.is_sending && styles.sendingMessage
              ]}
            >
              {item.is_sending && (
                <ActivityIndicator size="small" color="#FFF" style={styles.sendingIndicator} />
              )}
              
              <Text style={[
                styles.messageText,
                isMe ? styles.messageTextRight : styles.messageTextLeft
              ]}>
                {item.text}
              </Text>
              
              {showTime && (
                <Text style={[
                  styles.timeText,
                  isMe ? styles.timeTextRight : styles.timeTextLeft
                ]}>
                  {formatTime(item.created_at)}
                </Text>
              )}
            </LinearGradient>
          </TouchableOpacity>
          
          {isMe && item.is_read && (
            <MaterialIcons name="done-all" size={16} color="#6C63FF" style={styles.readIndicator} />
          )}
        </View>
      </View>
    );
  };

  const shouldShowDate = (current, previous) => {
    if (!previous) return true;
    const currentDate = new Date(current.created_at).toDateString();
    const previousDate = new Date(previous.created_at).toDateString();
    return currentDate !== previousDate;
  };

  const shouldShowTime = (current, previous) => {
    if (!previous) return true;
    const currentTime = new Date(current.created_at);
    const previousTime = new Date(previous.created_at);
    const timeDiff = currentTime - previousTime;
    return timeDiff > 5 * 60 * 1000;
  };

  const formatDate = (dateString) => {
    if (!dateString) return '';
    const date = new Date(dateString);
    const today = new Date();
    
    if (date.toDateString() === today.toDateString()) {
      return "Aujourd'hui";
    }
    
    const yesterday = new Date(today);
    yesterday.setDate(yesterday.getDate() - 1);
    if (date.toDateString() === yesterday.toDateString()) {
      return 'Hier';
    }
    
    return date.toLocaleDateString('fr-FR', {
      weekday: 'long',
      day: 'numeric',
      month: 'long'
    });
  };

  const formatTime = (dateString) => {
    if (!dateString) return '';
    const date = new Date(dateString);
    return date.toLocaleTimeString('fr-FR', {
      hour: '2-digit',
      minute: '2-digit'
    });
  };

  const getInitials = (name) => {
    if (!name) return '??';
    return name
      .split(' ')
      .map(part => part[0])
      .join('')
      .toUpperCase()
      .substring(0, 2);
  };

  return (
    <KeyboardAvoidingView
      style={styles.container}
      behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
      keyboardVerticalOffset={Platform.OS === 'ios' ? 90 : 0}
    >
      {/* Header */}
      <LinearGradient
        colors={['#6C63FF', '#3A7BD5']}
        style={styles.header}
      >
        <View style={styles.headerContent}>
          <TouchableOpacity
            style={styles.backButton}
            onPress={() => navigation.goBack()}
          >
            <Ionicons name="arrow-back" size={24} color="#FFF" />
          </TouchableOpacity>
          
          <View style={styles.userInfo}>
            <View style={styles.avatarContainer}>
              {userAvatar ? (
                <Image source={{ uri: userAvatar }} style={styles.headerAvatar} />
              ) : (
                <View style={styles.avatarPlaceholder}>
                  <Text style={styles.avatarText}>
                    {getInitials(userName)}
                  </Text>
                </View>
              )}
            </View>
            <View style={styles.userDetails}>
              <Text style={styles.userName} numberOfLines={1}>
                {userName || 'Utilisateur'}
              </Text>
            </View>
          </View>
          
          <View style={styles.headerActions}>
            <TouchableOpacity style={styles.headerActionButton}>
              <Ionicons name="call" size={20} color="#FFF" />
            </TouchableOpacity>
            <TouchableOpacity style={styles.headerActionButton}>
              <Ionicons name="videocam" size={22} color="#FFF" />
            </TouchableOpacity>
            <TouchableOpacity style={styles.headerActionButton}>
              <Ionicons name="ellipsis-vertical" size={20} color="#FFF" />
            </TouchableOpacity>
          </View>
        </View>
      </LinearGradient>

      {/* Messages List */}
      {loading ? (
        <View style={styles.loadingContainer}>
          <ActivityIndicator size="large" color="#6C63FF" />
          <Text style={styles.loadingText}>Chargement des messages...</Text>
        </View>
      ) : (
        <Animated.View style={[styles.messagesContainer, { marginBottom: keyboardHeight }]}>
          <FlatList
            ref={flatListRef}
            data={messages}
            renderItem={renderMessage}
            keyExtractor={item => item.id?.toString() || Math.random().toString()}
            contentContainerStyle={styles.messagesList}
            showsVerticalScrollIndicator={false}
            onContentSizeChange={() => flatListRef.current?.scrollToEnd({ animated: true })}
            onLayout={() => flatListRef.current?.scrollToEnd({ animated: true })}
            ListEmptyComponent={
              <View style={styles.emptyState}>
                <MaterialCommunityIcons name="chat-plus" size={80} color="#E0E0E0" />
                <Text style={styles.emptyStateTitle}>Aucun message</Text>
                <Text style={styles.emptyStateText}>
                  Envoyez votre premier message à {userName}
                </Text>
              </View>
            }
          />
        </Animated.View>
      )}

      {/* Input Area */}
      <Animated.View style={[styles.inputContainer, { bottom: keyboardHeight }]}>
        <View style={styles.inputWrapper}>
          <TouchableOpacity style={styles.attachmentButton}>
            <MaterialCommunityIcons name="plus" size={24} color="#6C63FF" />
          </TouchableOpacity>
          
          <TextInput
            style={styles.input}
            placeholder="Écrivez un message..."
            placeholderTextColor="#8E8E93"
            value={messageText}
            onChangeText={setMessageText}
            multiline
            maxLength={1000}
            onSubmitEditing={sendMessage}
          />
          
          {messageText.trim() ? (
            <TouchableOpacity
              style={styles.sendButton}
              onPress={sendMessage}
              disabled={sending}
            >
              <LinearGradient
                colors={['#6C63FF', '#FF6B9D']}
                style={styles.sendButtonGradient}
              >
                {sending ? (
                  <ActivityIndicator size="small" color="#FFF" />
                ) : (
                  <Ionicons name="send" size={20} color="#FFF" />
                )}
              </LinearGradient>
            </TouchableOpacity>
          ) : (
            <View style={styles.actionButtons}>
              <TouchableOpacity style={styles.actionButton}>
                <Ionicons name="mic" size={22} color="#6C63FF" />
              </TouchableOpacity>
              <TouchableOpacity style={styles.actionButton}>
                <Ionicons name="image" size={22} color="#6C63FF" />
              </TouchableOpacity>
            </View>
          )}
        </View>
      </Animated.View>
    </KeyboardAvoidingView>
  );
};

