import React, { useEffect, useState } from 'react';
import { 
  StyleSheet, 
  Text, 
  View, 
  FlatList, 
  TouchableOpacity, 
  Image,
  StatusBar,
  Alert 
} from 'react-native';
import FontAwesome from 'react-native-vector-icons/FontAwesome';
import axios from 'axios';
import { useNavigation } from '@react-navigation/native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import Config from './Config';
import { useTheme } from '../context/ThemeContext.js';
import { useThemedStyles } from '../hooks/useThemedStyles';

const BandeMaisons = () => {
    const navigation = useNavigation();
    const { isDarkMode } = useTheme();
    const { createThemedStyles, theme } = useThemedStyles();
    const styles = createThemedStyles(themedStyles);
    
    const [maisons, setMaisons] = useState([]);
    const [likes, setLikes] = useState({});
    const [user, setUser] = useState(null);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        const fetchUserData = async () => {
            try {
                const userData = await AsyncStorage.getItem('user');
                const token = await AsyncStorage.getItem('access_token');
                if (userData && token) {
                    setUser({ ...JSON.parse(userData), token });
                }
            } catch (error) {
                console.error('Erreur récupération utilisateur:', error);
            }
        };
        fetchUserData();
    }, []);

    useEffect(() => {
        const fetchData = async () => {
            try {
                setLoading(true);
                const response = await axios.get(`${Config.BASE_URL}/maisons/`);
                
                let maisonsData = [];
                if (response.data && response.data.results) {
                    maisonsData = response.data.results;
                } else if (Array.isArray(response.data)) {
                    maisonsData = response.data;
                }
                
                const initialLikes = {};
                maisonsData.forEach(maison => {
                    initialLikes[maison.id] = {
                        liked: maison.is_liked || false,
                        count: maison.likes_count || 0
                    };
                });
                
                setLikes(initialLikes);
                setMaisons(maisonsData);
            } catch (error) {
                setMaisons([
                    {
                        id: 'demo1',
                        titre: 'Villa moderne',
                        description: 'Superbe villa avec piscine',
                        prix: 150000000,
                        type_maison: 'vente',
                        quartier: 'Plateau',
                        ville: 'Abidjan',
                        pays: 'Côte d\'Ivoire',
                        nombre_chambres: 4,
                        nombre_salles_de_bain: 3,
                        surface: 250,
                        piscine: true,
                        jardin: true,
                        garage: true,
                        photos: [],
                        owner: { id: 1, username: 'Propriétaire', avatar: null }
                    }
                ]);
            } finally {
                setLoading(false);
            }
        };
        fetchData();
    }, []);

    const handleViewAll = () => {
        navigation.navigate('MaisonList');
    };

    const toggleLike = async (id) => {
        if (!user || !user.token) {
            Alert.alert('Connexion requise', 'Connectez-vous pour aimer', [
                { text: 'Annuler', style: 'cancel' },
                { text: 'Se connecter', onPress: () => navigation.navigate('Login') }
            ]);
            return;
        }

        try {
            const isCurrentlyLiked = likes[id]?.liked || false;
            await axios.post(`${Config.BASE_URL}/maisons/${id}/like/`, {}, {
                headers: { Authorization: `Bearer ${user.token}` }
            });
            setLikes(prev => ({
                ...prev,
                [id]: {
                    liked: !isCurrentlyLiked,
                    count: !isCurrentlyLiked ? (prev[id]?.count || 0) + 1 : Math.max(0, (prev[id]?.count || 1) - 1)
                }
            }));
        } catch (error) {
            console.error('Erreur like:', error);
        }
    };

    const getImageUri = (item) => {
        if (Array.isArray(item.photos) && item.photos.length > 0) {
            const firstPhoto = item.photos[0];
            if (typeof firstPhoto === "object" && firstPhoto.photos) return firstPhoto.photos;
            if (typeof firstPhoto === "string") return firstPhoto;
        }
        return null;
    };

    const handleMaisonPress = (item) => {
        navigation.navigate('MaisonDetail', { maisonId: item.id, maison: item });
    };

    const renderMaisonItem = ({ item }) => {
        const imageUri = getImageUri(item);
        const maisonLikes = likes[item.id] || { liked: false, count: 0 };

        return (
            <TouchableOpacity onPress={() => handleMaisonPress(item)} activeOpacity={0.9}>
                <View style={[styles.maisonContainer, isDarkMode && styles.darkCard]}>
                    <View style={styles.Imagebox}>
                        <Image source={imageUri ? { uri: imageUri } : require('../assets/icon.png')} style={styles.maisonImage} resizeMode="cover" />
                        <View style={styles.imageOverlay} />
                        <View style={styles.imageContent}>
                            <View style={styles.topSection}>
                                <View style={[styles.typeBadge, item.type_maison === 'vente' ? styles.saleBadge : styles.rentBadge]}>
                                    <Text style={styles.typeText}>{item.type_maison === 'vente' ? 'À VENDRE' : 'À LOUER'}</Text>
                                </View>
                                <TouchableOpacity onPress={() => toggleLike(item.id)} style={styles.likeButton}>
                                    <FontAwesome name={maisonLikes.liked ? "heart" : "heart-o"} size={20} color={maisonLikes.liked ? '#FF3B30' : '#fff'} />
                                </TouchableOpacity>
                            </View>
                            <View style={styles.bottomImageSection}>
                                <TouchableOpacity style={styles.profileSection} onPress={() => navigation.navigate('ProfilScreen', { userId: item.owner?.id })}>
                                    <Image source={item.owner?.avatar ? { uri: item.owner.avatar } : require('../assets/profil.jpg')} style={styles.Userprofil} />
                                    <View style={styles.locationInfo}>
                                        <Text style={styles.ownerName}>{item.owner?.username || 'Propriétaire'}</Text>
                                        <View style={styles.locationRow}>
                                            <FontAwesome name="map-marker" size={12} color="#fff" />
                                            <Text style={styles.locationText}>{item.quartier}, {item.ville}</Text>
                                        </View>
                                    </View>
                                </TouchableOpacity>
                                <View style={styles.priceContainer}>
                                    <Text style={styles.price}>{parseFloat(item.prix).toLocaleString('fr-FR')} fCfa</Text>
                                    {item.type_maison === 'location' && <Text style={styles.pricePeriod}>/mois</Text>}
                                </View>
                            </View>
                        </View>
                    </View>
                    <View style={[styles.DetailText, isDarkMode && styles.darkCard]}>
                        <Text style={[styles.description, isDarkMode && styles.darkText]} numberOfLines={2}>{item.description}</Text>
                        <View style={styles.featuresSection}>
                            <View style={styles.featureItem}><FontAwesome name="bed" size={14} color={theme.primary} /><Text style={[styles.featureText, isDarkMode && styles.darkText]}>{item.nombre_chambres}</Text></View>
                            <View style={styles.featureItem}><FontAwesome name="bath" size={14} color={theme.primary} /><Text style={[styles.featureText, isDarkMode && styles.darkText]}>{item.nombre_salles_de_bain}</Text></View>
                            {item.surface > 0 && <View style={styles.featureItem}><FontAwesome name="expand" size={14} color={theme.primary} /><Text style={[styles.featureText, isDarkMode && styles.darkText]}>{item.surface} m²</Text></View>}
                        </View>
                    </View>
                </View>
            </TouchableOpacity>
        );
    };

    if (loading) {
        return <View style={[styles.loadingContainer, isDarkMode && styles.darkContainer]}><Text style={isDarkMode && styles.darkText}>Chargement des propriétés...</Text></View>;
    }

    return (
        <View style={[styles.container, isDarkMode && styles.darkContainer]}>
            <View style={styles.sectionContainer}>
                <View style={styles.sectionHeader}>
                    <Text style={[styles.title, isDarkMode && styles.darkText]}></Text>
                    <TouchableOpacity style={styles.seeAllButton} onPress={handleViewAll}>
                        <Text style={[styles.seeAllText, isDarkMode && styles.darkText]}>Tout voir</Text>
                        <FontAwesome name="chevron-right" size={14} color={isDarkMode ? '#aaa' : '#052c65'} />
                    </TouchableOpacity>
                </View>
                <FlatList 
                    data={maisons} 
                    keyExtractor={item => item.id.toString()}
                    horizontal 
                    showsHorizontalScrollIndicator={false} 
                    renderItem={renderMaisonItem} 
                    contentContainerStyle={styles.listContent}
                    ListEmptyComponent={
                        <View style={styles.emptyContainer}>
                            <FontAwesome name="home" size={40} color="#ccc" />
                            <Text style={[styles.emptyText, isDarkMode && styles.darkSubText]}>Aucune propriété</Text>
                        </View>
                    } 
                />
            </View>
        </View>
    );
};

const themedStyles = (theme, isDarkMode, Platform, StatusBar) => StyleSheet.create({
    
  container: {  // ← AJOUTER CE NOM DE STYLE
    flex: 1,
    backgroundColor: theme.background,
    paddingTop: Platform.OS === 'android' ? StatusBar.currentHeight : 0,
  },
    darkContainer: {
        backgroundColor: '#1a1a1a',
    },
    darkCard: {
        backgroundColor: '#2d2d2d',
    },
    darkText: {
        color: '#fff',
    },
    darkSubText: {
        color: '#aaa',
    },
    sectionContainer: {
        marginTop: 15,
    },
    sectionHeader: {
        flexDirection: 'row',
        justifyContent: 'space-between',
        alignItems: 'center',
        paddingHorizontal: 15,
        marginBottom: 15,
    },
    seeAllButton: {
        flexDirection: 'row',
        alignItems: 'center',
    },
    seeAllText: {
        fontSize: 14,
        fontWeight: '600',
        marginRight: 5,
    },
    title: {
        fontSize: 22,
        fontWeight: 'bold',
        letterSpacing: 0.5,
    },
    listContent: {
        paddingHorizontal: 10,
        paddingBottom: 10,
    },
    maisonContainer: {
        marginRight: 15,
        width: 320,
        backgroundColor: '#fff',
        borderRadius: 20,
        overflow: 'hidden',
        elevation: 3,
        shadowColor: '#000',
        shadowOffset: { width: 0, height: 2 },
        shadowOpacity: 0.1,
        shadowRadius: 4,
        marginBottom: 5,
    },
    Imagebox: {
        position: 'relative',
        height: 200,
    },
    maisonImage: {
        width: '100%',
        height: '100%',
    },
    imageOverlay: {
        position: 'absolute',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        backgroundColor: 'rgba(0, 0, 0, 0.3)',
    },
    imageContent: {
        position: 'absolute',
        top: 0,
        left: 0,
        right: 0,
        bottom: 0,
        padding: 15,
        justifyContent: 'space-between',
    },
    topSection: {
        flexDirection: 'row',
        justifyContent: 'space-between',
        alignItems: 'flex-start',
    },
    typeBadge: {
        paddingHorizontal: 12,
        paddingVertical: 6,
        borderRadius: 15,
        backgroundColor: 'rgba(5, 44, 101, 0.9)',
    },
    saleBadge: {
        backgroundColor: 'rgba(5, 44, 101, 0.9)',
    },
    rentBadge: {
        backgroundColor: 'rgba(33, 150, 243, 0.9)',
    },
    typeText: {
        color: '#fff',
        fontSize: 11,
        fontWeight: 'bold',
    },
    likeButton: {
        width: 36,
        height: 36,
        borderRadius: 18,
        backgroundColor: 'rgba(255, 255, 255, 0.2)',
        justifyContent: 'center',
        alignItems: 'center',
    },
    bottomImageSection: {
        flexDirection: 'row',
        justifyContent: 'space-between',
        alignItems: 'flex-end',
    },
    profileSection: {
        flexDirection: 'row',
        alignItems: 'center',
        flex: 1,
        marginRight: 10,
    },
    Userprofil: {
        width: 36,
        height: 36,
        borderRadius: 18,
        backgroundColor: '#f0f0f0',
        borderWidth: 2,
        borderColor: '#fff',
        marginRight: 10,
    },
    locationInfo: {
        flex: 1,
    },
    ownerName: {
        fontSize: 14,
        fontWeight: '600',
        color: '#fff',
        marginBottom: 2,
        textShadowColor: 'rgba(0, 0, 0, 0.5)',
        textShadowOffset: { width: 1, height: 1 },
        textShadowRadius: 2,
    },
    locationRow: {
        flexDirection: 'row',
        alignItems: 'center',
    },
    locationText: {
        fontSize: 12,
        color: '#fff',
        marginLeft: 5,
        textShadowColor: 'rgba(0, 0, 0, 0.5)',
        textShadowOffset: { width: 1, height: 1 },
        textShadowRadius: 2,
    },
    priceContainer: {
        backgroundColor: 'rgba(255, 255, 255, 0.9)',
        paddingHorizontal: 10,
        paddingVertical: 6,
        borderRadius: 12,
        alignItems: 'center',
    },
    price: {
        fontSize: 16,
        fontWeight: 'bold',
        color: '#052c65',
    },
    pricePeriod: {
        fontSize: 10,
        color: '#666',
        marginTop: 2,
    },
    DetailText: {
        padding: 12,
        backgroundColor: '#fff',
    },
    description: {
        fontSize: 14,
        color: '#333',
        marginBottom: 10,
        lineHeight: 18,
    },
    featuresSection: {
        flexDirection: 'row',
        flexWrap: 'wrap',
        gap: 8,
        marginBottom: 10,
    },
    featureItem: {
        flexDirection: 'row',
        alignItems: 'center',
        backgroundColor: '#f0f5ff',
        paddingHorizontal: 8,
        paddingVertical: 4,
        borderRadius: 12,
        minWidth: 40,
    },
    featureText: {
        fontSize: 12,
        fontWeight: '600',
        marginLeft: 4,
    },
    loadingContainer: {
        flex: 1,
        justifyContent: 'center',
        alignItems: 'center',
    },
    emptyContainer: {
        width: 280,
        alignItems: 'center',
        paddingVertical: 40,
    },
    emptyText: {
        fontSize: 14,
        color: '#999',
        marginTop: 10,
        textAlign: 'center',
    },
});

export default BandeMaisons;
