import React, { useState, useRef } from 'react';
import { 
  FlatList, 
  StyleSheet, 
  Text, 
  View, 
  Image,
  Dimensions,
  ActivityIndicator,
  TouchableOpacity,
  StatusBar,
  Animated,
  Platform
} from 'react-native';
import Ionicons from 'react-native-vector-icons/Ionicons';
import { useNavigation } from '@react-navigation/native';

const { width, height } = Dimensions.get('window');

const ImageDetails = ({ route }) => {
  const navigation = useNavigation();
  const [currentIndex, setCurrentIndex] = useState(0);
  const flatListRef = useRef(null);
  const [isLiked, setIsLiked] = useState(false);
  const [isSaved, setIsSaved] = useState(false);
  const fadeAnim = useState(new Animated.Value(1))[0];

  // Récupération des données
  const { slides: paramSlides, trip: paramTrip, propertyId } = route.params || {};
  
  const slides = paramSlides || [];
  const trip = paramTrip || null;
  const images = slides.length > 0 ? slides : (trip?.photos || []);

  const [showControls, setShowControls] = useState(true);
  
  const toggleControls = () => {
    Animated.timing(fadeAnim, {
      toValue: showControls ? 0 : 1,
      duration: 300,
      useNativeDriver: true,
    }).start();
    setShowControls(!showControls);
  };

  const getImageUrl = (item) => {
    if (!item) return null;
    if (typeof item === 'string') return item;
    if (item.uri) return item.uri;
    if (item.url) return item.url;
    if (item.photos) return item.photos;
    if (item.image) return item.image;
    return null;
  };

  const handleLike = () => {
    setIsLiked(!isLiked);
  };

  const handleSave = () => {
    setIsSaved(!isSaved);
  };

  const handleShare = () => {
    console.log('Partager l\'image');
  };

  const handleDownload = () => {
    console.log('Télécharger l\'image');
  };

  const onScroll = (event) => {
    const index = Math.round(event.nativeEvent.contentOffset.x / width);
    setCurrentIndex(index);
  };

  if (images.length === 0) {
    return (
      <View style={styles.noImagesContainer}>
        <StatusBar barStyle={isDarkMode ? 'light-content' : 'dark-content'} backgroundColor={theme.background} translucent />
        <TouchableOpacity 
          style={styles.closeButton}
          onPress={() => navigation.goBack()}
        >
          <Ionicons name="close" size={28} color="#fff" />
        </TouchableOpacity>
        <Ionicons name="images-outline" size={80} color="#666" />
        <Text style={styles.noImagesText}>Aucune image disponible</Text>
        <Text style={styles.noImagesSubText}>Cette propriété n'a pas encore de photos</Text>
      </View>
    );
  }

  return (
    <View style={styles.container}>
      <StatusBar barStyle={isDarkMode ? 'light-content' : 'dark-content'} backgroundColor={theme.background} translucent />
      
      {/* Bouton fermeture */}
      <TouchableOpacity 
        style={styles.closeButton}
        onPress={() => navigation.goBack()}
      >
        <Ionicons name="close" size={28} color="#fff" />
      </TouchableOpacity>

      {/* Contrôles supérieurs */}
      <Animated.View style={[styles.topControls, { opacity: fadeAnim }]}>
        <View style={styles.counterBadge}>
          <Text style={styles.counterText}>
            {currentIndex + 1} / {images.length}
          </Text>
        </View>
      </Animated.View>

      {/* Contrôles inférieurs */}
      <Animated.View style={[styles.bottomControls, { opacity: fadeAnim }]}>
        <TouchableOpacity style={styles.controlButton} onPress={handleLike}>
          <View style={styles.controlIconContainer}>
            <Ionicons 
              name={isLiked ? "heart" : "heart-outline"} 
              size={24} 
              color={isLiked ? "#FF3B30" : "#fff"} 
            />
          </View>
          <Text style={styles.controlText}>Favori</Text>
        </TouchableOpacity>

        <TouchableOpacity style={styles.controlButton} onPress={handleSave}>
          <View style={styles.controlIconContainer}>
            <Ionicons 
              name={isSaved ? "bookmark" : "bookmark-outline"} 
              size={24} 
              color={isSaved ? "#FFD700" : "#fff"} 
            />
          </View>
          <Text style={styles.controlText}>Sauvegarder</Text>
        </TouchableOpacity>

        <TouchableOpacity style={styles.controlButton} onPress={handleShare}>
          <View style={styles.controlIconContainer}>
            <Ionicons name="share-outline" size={24} color="#fff" />
          </View>
          <Text style={styles.controlText}>Partager</Text>
        </TouchableOpacity>

        <TouchableOpacity style={styles.controlButton} onPress={handleDownload}>
          <View style={styles.controlIconContainer}>
            <Ionicons name="download-outline" size={24} color="#fff" />
          </View>
          <Text style={styles.controlText}>Télécharger</Text>
        </TouchableOpacity>
      </Animated.View>

      {/* Carrousel d'images - CORRECTION ICI */}
      <FlatList
        ref={flatListRef}
        data={images}
        horizontal
        pagingEnabled
        showsHorizontalScrollIndicator={false}
        onScroll={onScroll}
        scrollEventThrottle={16}
        keyExtractor={(_, index) => `img-${index}`}
        renderItem={({ item }) => {
          const imageUrl = getImageUrl(item);
          if (!imageUrl) return null;
          
          return (
            <TouchableOpacity 
              style={styles.imageContainer}
              onPress={toggleControls}
              activeOpacity={1}
            >
              <Image 
                source={{ uri: imageUrl }} 
                style={styles.image} 
                resizeMode="contain"
                onError={(e) => console.log('Erreur chargement image:', e.nativeEvent.error)}
              />
            </TouchableOpacity>
          );
        }}
      />
    </View>
  );
};

const themedStyles = (theme, isDarkMode, Platform, StatusBar) => StyleSheet.create({
  container: { 
    flex: 1, 
    backgroundColor: '#000' 
  },
  imageContainer: { 
    width: width, 
    height: height,
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: '#000'
  },
  image: { 
    width: width,
    height: height,
  },
  
  closeButton: {
    position: 'absolute',
    top: Platform.OS === 'ios' ? 50 : 30,
    left: 20,
    zIndex: 20,
    width: 40,
    height: 40,
    borderRadius: 20,
    backgroundColor: 'rgba(0,0,0,0.5)',
    justifyContent: 'center',
    alignItems: 'center',
  },
  
  topControls: {
    position: 'absolute',
    top: Platform.OS === 'ios' ? 50 : 30,
    right: 20,
    zIndex: 20,
  },
  counterBadge: {
    backgroundColor: 'rgba(0,0,0,0.6)',
    paddingHorizontal: 12,
    paddingVertical: 6,
    borderRadius: 20,
    borderWidth: 1,
    borderColor: 'rgba(255,255,255,0.2)',
  },
  counterText: {
    color: '#fff',
    fontSize: 14,
    fontWeight: '600',
  },
  
  bottomControls: {
    position: 'absolute',
    bottom: Platform.OS === 'ios' ? 40 : 20,
    left: 0,
    right: 0,
    flexDirection: 'row',
    justifyContent: 'space-around',
    alignItems: 'center',
    paddingHorizontal: 20,
    paddingVertical: 15,
    backgroundColor: 'rgba(0,0,0,0.7)',
    zIndex: 20,
  },
  controlButton: {
    alignItems: 'center',
    justifyContent: 'center',
    paddingVertical: 5,
  },
  controlIconContainer: {
    width: 45,
    height: 45,
    borderRadius: 23,
    backgroundColor: 'rgba(255,255,255,0.15)',
    justifyContent: 'center',
    alignItems: 'center',
    marginBottom: 5,
  },
  controlText: {
    color: '#fff',
    fontSize: 11,
    fontWeight: '500',
  },
  
  noImagesContainer: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: '#000',
    paddingHorizontal: 20,
  },
  noImagesText: { 
    color: '#fff', 
    fontSize: 18, 
    fontWeight: '600', 
    marginTop: 20,
    marginBottom: 8 
  },
  noImagesSubText: { 
    color: '#999', 
    fontSize: 14, 
    textAlign: 'center' 
  },
  
  loadingContainer: {
    position: 'absolute',
    top: 0,
    left: 0,
    right: 0,
    bottom: 0,
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: '#000',
  },
});

export default ImageDetails;


