import React, { useEffect, useState } from 'react';
import { StyleSheet, Text, View, FlatList, TouchableOpacity, Image, Alert } from 'react-native';
import FontAwesome from 'react-native-vector-icons/FontAwesome';
import axios from 'axios';
import { useNavigation } from '@react-navigation/native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import Config from './Config';
import { useTheme } from '../context/ThemeContext.js';
import { useThemedStyles } from '../hooks/useThemedStyles';

const BandeHotels = () => {
    const { isDarkMode } = useTheme();
    const { createThemedStyles, theme } = useThemedStyles();
    const styles = createThemedStyles(themedStyles);
    
    const [hotels, setHotels] = useState([]);
    const [favorites, setFavorites] = useState({});
    const [loading, setLoading] = useState(true);
    const [user, setUser] = useState(null);
    const navigation = useNavigation();

    useEffect(() => {
        const fetchUserData = async () => {
            try {
                const userData = await AsyncStorage.getItem('user');
                const token = await AsyncStorage.getItem('access_token');
                if (userData && token) setUser({ ...JSON.parse(userData), token });
            } catch (error) { console.error('Erreur:', error); }
        };
        fetchUserData();
    }, []);

    useEffect(() => {
        const fetchData = async () => {
            try {
                setLoading(true);
                const response = await axios.get(`${Config.BASE_URL}/hotels/`);
                let hotelsData = [];
                if (response.data?.results) hotelsData = response.data.results;
                else if (Array.isArray(response.data)) hotelsData = response.data;
                
                const initialFavorites = {};
                hotelsData.forEach(hotel => { initialFavorites[hotel.id] = false; });
                setFavorites(initialFavorites);
                setHotels(hotelsData);
            } catch (error) {
                // Données de démo avec plus d'informations
                setHotels([
                    { 
                        id: 'demo1', 
                        titre: 'Hôtel Palace', 
                        prix_nuit: 75000, 
                        ville: 'Niamey', 
                        pays: 'Niger',
                        categorie: 5, 
                        note_moyenne: 4.8, 
                        photos: [{ photos: 'https://via.placeholder.com/400x300' }], 
                        owner: null, 
                        description: 'Luxueux hôtel en centre-ville avec piscine, spa et restaurant gastronomique. Idéal pour les voyages d\'affaires et les séjours de luxe.',
                        nombre_chambres: 50,
                        chambres_disponibles: 12,
                        services: ['WiFi gratuit', 'Petit-déjeuner', 'Piscine', 'Spa', 'Parking', 'Restaurant'],
                        type_hotel: 'Luxe',
                        heure_check_in: '14:00',
                        heure_check_out: '12:00',
                        telephone: '+22790123456',
                        email: 'contact@hotelpalace.com'
                    },
                    { 
                        id: 'demo2', 
                        titre: 'Hôtel Riviera', 
                        prix_nuit: 45000, 
                        ville: 'Niamey',
                        pays: 'Niger',
                        categorie: 4, 
                        note_moyenne: 4.5, 
                        photos: [{ photos: 'https://via.placeholder.com/400x300' }], 
                        owner: null, 
                        description: 'Hôtel avec vue sur le fleuve Niger. Chambres confortables, terrasse panoramique et cuisine locale.',
                        nombre_chambres: 30,
                        chambres_disponibles: 8,
                        services: ['WiFi gratuit', 'Petit-déjeuner', 'Restaurant', 'Parking'],
                        type_hotel: 'Confort',
                        heure_check_in: '14:00',
                        heure_check_out: '12:00',
                        telephone: '+22790789012',
                        email: 'info@hotelriviera.com'
                    }
                ]);
            } finally { setLoading(false); }
        };
        fetchData();
    }, []);

    const getImageUri = (item) => {
        if (item.photos?.length > 0) {
            const firstPhoto = item.photos[0];
            if (typeof firstPhoto === "object" && firstPhoto.photos) return firstPhoto.photos;
            if (typeof firstPhoto === "string") return firstPhoto;
        }
        return null;
    };

    // ✅ MODIFICATION ICI : Navigation vers HotelsDetails au lieu de MaisonDetail
    const handleItemPress = (item) => {
        navigation.navigate('HotelsDetails', { 
            hotelId: item.id, 
            hotel: item
        });
    };

    const renderHotelItem = ({ item }) => {
        const imageUri = getImageUri(item);
        return (
            <TouchableOpacity onPress={() => handleItemPress(item)} activeOpacity={0.9}>
                <View style={[styles.hotelContainer, isDarkMode && styles.darkCard]}>
                    <View style={styles.imageContainer}>
                        <Image 
                            source={imageUri ? { uri: imageUri } : require('../assets/icon.png')} 
                            style={styles.hotelImage} 
                            resizeMode="cover" 
                        />
                        {/* Badge de catégorie (étoiles) */}
                        <View style={styles.categoryBadge}>
                            {[...Array(item.categorie || 3)].map((_, i) => (
                                <FontAwesome key={i} name="star" size={10} color="#FFD700" />
                            ))}
                        </View>
                        <View style={styles.titleOverlay}>
                            <Text style={styles.hotelTitle} numberOfLines={1}>{item.titre}</Text>
                        </View>
                    </View>
                    <View style={[styles.detailContainer, isDarkMode && styles.darkCard]}>
                        <View style={styles.ratingContainer}>
                            <View style={styles.starsContainer}>
                                {[...Array(5)].map((_, i) => (
                                    <FontAwesome 
                                        key={i} 
                                        name={i < Math.floor(item.note_moyenne || 0) ? "star" : "star-o"} 
                                        size={12} 
                                        color="#FFD700" 
                                        style={styles.starIcon} 
                                    />
                                ))}
                            </View>
                            <Text style={[styles.ratingText, isDarkMode && styles.darkSubText]}>
                                {item.note_moyenne || 'Nouveau'}
                            </Text>
                        </View>
                        <Text style={[styles.locationText, isDarkMode && styles.darkSubText]}>
                            <FontAwesome name="map-marker" size={10} color={isDarkMode ? '#aaa' : '#666'} /> {item.ville}, {item.pays || 'Niger'}
                        </Text>
                        <View style={styles.priceRow}>
                            <Text style={[styles.price, isDarkMode && { color: theme.primary }]}>
                                {parseFloat(item.prix_nuit).toLocaleString('fr-FR')} FCFA
                            </Text>
                            <Text style={[styles.priceUnit, isDarkMode && styles.darkSubText]}>/nuit</Text>
                        </View>
                    </View>
                </View>
            </TouchableOpacity>
        );
    };

    if (loading) return (
        <View style={[styles.loadingContainer, isDarkMode && styles.darkContainer]}>
            <Text style={isDarkMode && styles.darkText}>Chargement des hôtels...</Text>
        </View>
    );

    return (
        <View style={[styles.container, isDarkMode && styles.darkContainer]}>
            <View style={styles.sectionHeader}>
                <Text style={[styles.title, isDarkMode && styles.darkText]}>Hôtels populaires</Text>
                <TouchableOpacity 
                    style={styles.seeAllButton} 
                    onPress={() => navigation.navigate('AllHotels')}
                >
                    <Text style={[styles.seeAllText, isDarkMode && styles.darkText]}>Tout voir</Text>
                    <FontAwesome name="chevron-right" size={14} color={isDarkMode ? '#aaa' : '#052c65'} />
                </TouchableOpacity>
            </View>
            <FlatList 
                data={hotels} 
                keyExtractor={item => item.id.toString()} 
                horizontal 
                showsHorizontalScrollIndicator={false} 
                renderItem={renderHotelItem} 
                contentContainerStyle={styles.listContent} 
                ListEmptyComponent={
                    <View style={styles.emptyContainer}>
                        <FontAwesome name="building" size={40} color="#ccc" />
                        <Text style={[styles.emptyText, isDarkMode && styles.darkSubText]}>Aucun hôtel</Text>
                    </View>
                } 
            />
        </View>
    );
};

const themedStyles = (theme, isDarkMode, Platform, StatusBar) => StyleSheet.create({

    container: { flex: 1, backgroundColor: theme.background },
    darkContainer: { backgroundColor: '#1a1a1a' },
    darkCard: { backgroundColor: '#2d2d2d' },
    darkText: { color: '#fff' },
    darkSubText: { color: '#aaa' },
    
    sectionHeader: { 
        flexDirection: 'row', 
        justifyContent: 'space-between', 
        alignItems: 'center', 
        paddingHorizontal: 15, 
        marginBottom: 15 
    },
    title: { 
        fontSize: 18, 
        fontWeight: 'bold', 
        color: theme.primary, 
        letterSpacing: 0.5 
    },
    seeAllButton: { 
        flexDirection: 'row', 
        alignItems: 'center' 
    },
    seeAllText: { 
        fontSize: 13, 
        fontWeight: '600', 
        marginRight: 5,
        color: theme.primary
    },
    listContent: { 
        paddingHorizontal: 10, 
        paddingBottom: 10 
    },
    hotelContainer: { 
        marginRight: 15, 
        width: 170, 
        backgroundColor: '#fff', 
        borderRadius: 16, 
        overflow: 'hidden', 
        elevation: 3, 
        shadowColor: '#000', 
        shadowOffset: { width: 0, height: 2 }, 
        shadowOpacity: 0.1, 
        shadowRadius: 4 
    },
    imageContainer: { 
        position: 'relative', 
        height: 160 
    },
    hotelImage: { 
        width: '100%', 
        height: '100%' 
    },
    categoryBadge: {
        position: 'absolute',
        top: 10,
        left: 10,
        flexDirection: 'row',
        backgroundColor: 'rgba(0,0,0,0.6)',
        paddingHorizontal: 8,
        paddingVertical: 4,
        borderRadius: 12,
        gap: 2,
    },
    titleOverlay: { 
        position: 'absolute', 
        bottom: 0, 
        left: 0, 
        right: 0, 
        backgroundColor: 'rgba(0, 0, 0, 0.6)', 
        paddingHorizontal: 10, 
        paddingVertical: 8 
    },
    hotelTitle: { 
        color: '#fff', 
        fontSize: 14, 
        fontWeight: 'bold', 
        textAlign: 'center' 
    },
    detailContainer: { 
        padding: 12, 
        backgroundColor: '#fff' 
    },
    ratingContainer: { 
        flexDirection: 'row', 
        alignItems: 'center', 
        justifyContent: 'space-between',
        marginBottom: 8 
    },
    starsContainer: {
        flexDirection: 'row',
    },
    starIcon: { 
        marginRight: 2 
    },
    ratingText: { 
        fontSize: 11, 
        color: '#666', 
        fontWeight: '600' 
    },
    locationText: { 
        fontSize: 11, 
        color: '#666', 
        marginBottom: 8 
    },
    priceRow: {
        flexDirection: 'row',
        alignItems: 'baseline',
        justifyContent: 'flex-end',
    },
    price: { 
        fontSize: 15, 
        fontWeight: 'bold', 
        color: theme.primary 
    },
    priceUnit: {
        fontSize: 10,
        color: '#666',
        marginLeft: 2,
    },
    loadingContainer: { 
        padding: 40, 
        justifyContent: 'center', 
        alignItems: 'center' 
    },
    emptyContainer: { 
        paddingHorizontal: 30, 
        paddingVertical: 30, 
        alignItems: 'center', 
        justifyContent: 'center' 
    },
    emptyText: { 
        fontSize: 16, 
        fontWeight: 'bold', 
        color: '#666', 
        marginTop: 15, 
        textAlign: 'center' 
    },
});

export default BandeHotels;
