import React, { useState, useEffect, useRef } from 'react';
import { Platform, StatusBar,  
  View, 
  Text, 
  Image, 
  ScrollView, 
  StyleSheet, 
  TouchableOpacity, 
  Alert, 
  SafeAreaView,
  Share,
  Dimensions,
  FlatList,
  Animated,
  ActivityIndicator
} from 'react-native';
import axios from 'axios';
import FontAwesome from 'react-native-vector-icons/FontAwesome';
import Ionicons from 'react-native-vector-icons/Ionicons';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { useNavigation, useRoute } from '@react-navigation/native';
import Config from './Config';
import { useTheme } from '../context/ThemeContext.js';
import {  useThemedStyles } from '../hooks/useThemedStyles';

const { width, height } = Dimensions.get('window');

const MaisonDetail = () => {
  const navigation = useNavigation();
  const route = useRoute();
  const { maisonId, maison: initialMaison } = route.params;
  const { isDarkMode } = useTheme();
  const { createThemedStyles, theme } = useThemedStyles();
  const styles = createThemedStyles(themedStyles);
  
  const [maison, setMaison] = useState(initialMaison);
  const [loading, setLoading] = useState(!initialMaison);
  const [user, setUser] = useState(null);
  const [liked, setLiked] = useState(false);
  const [favorited, setFavorited] = useState(false);
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const scrollX = useRef(new Animated.Value(0)).current;
  const flatListRef = useRef(null);

  useEffect(() => {
    loadUserData();
    if (!initialMaison) {
      fetchMaisonDetails();
    } else {
      setMaison(initialMaison);
      setLiked(initialMaison.is_liked || false);
      setFavorited(initialMaison.is_favori || false);
    }
  }, []);

  const loadUserData = async () => {
    try {
      const userData = await AsyncStorage.getItem('user');
      if (userData) setUser(JSON.parse(userData));
    } catch (error) {
      console.error('Erreur chargement utilisateur:', error);
    }
  };

  const fetchMaisonDetails = async () => {
    try {
      setLoading(true);
      const response = await axios.get(`${Config.BASE_URL}/maisons/${maisonId}/`);
      setMaison(response.data);
      setLiked(response.data.is_liked || false);
      setFavorited(response.data.is_favori || false);
    } catch (error) {
      console.error('Erreur chargement maison:', error);
      Alert.alert('Erreur', 'Impossible de charger les détails');
    } finally {
      setLoading(false);
    }
  };

  const handleLike = async () => {
    const token = await AsyncStorage.getItem('access_token');
    if (!token) {
      Alert.alert('Connexion requise', 'Connectez-vous pour liker');
      return;
    }
    try {
      await axios.post(`${Config.BASE_URL}/maisons/${maisonId}/like/`, {}, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setLiked(!liked);
    } catch (error) {
      console.error('Erreur like:', error);
    }
  };

  const handleFavorite = async () => {
    const token = await AsyncStorage.getItem('access_token');
    if (!token) {
      Alert.alert('Connexion requise', 'Connectez-vous pour ajouter aux favoris');
      return;
    }
    try {
      await axios.post(`${Config.BASE_URL}/maisons/${maisonId}/favori/`, {}, {
        headers: { Authorization: `Bearer ${token}` }
      });
      setFavorited(!favorited);
    } catch (error) {
      console.error('Erreur favori:', error);
    }
  };

  const handleShare = async () => {
    try {
      await Share.share({
        message: `🏠 ${maison.titre}\n📍 ${maison.quartier}, ${maison.ville}\n💰 ${maison.prix} FCFA`,
        title: 'Partager cette propriété',
      });
    } catch (error) {
      console.error('Erreur de partage:', error);
    }
  };

  const handleContact = () => {
    Alert.alert(
      'Contacter le propriétaire',
      'Choisissez une méthode:',
      [
        { text: 'Annuler', style: 'cancel' },
        { text: 'Demande de visite', onPress: () => navigation.navigate('DemandeVisite', { 
          bien_type: 'maison', bien_id: maison.id 
        })},
        { text: 'Message', onPress: () => navigation.navigate('TextoScreen', { 
          userId: maison.owner, userName: maison.owner_name 
        })}
      ]
    );
  };

  const goToProfile = () => {
    if (maison.owner) {
      navigation.navigate('ProfilScreen', { userId: maison.owner });
    }
  };

  const onScrollEnd = (e) => {
    const index = Math.round(e.nativeEvent.contentOffset.x / width);
    setCurrentImageIndex(index);
  };

  // CARROUSEL D'IMAGES - IMAGES EN ENTIER
  const renderImageCarousel = () => {
    if (!maison.photos || maison.photos.length === 0) {
      return (
        <View style={styles.noImagesContainer}>
          <FontAwesome name="image" size={50} color="#ccc" />
          <Text style={styles.noImagesText}>Aucune photo</Text>
        </View>
      );
    }

    return (
      <View style={styles.carouselContainer}>
        <FlatList
          ref={flatListRef}
          data={maison.photos}
          horizontal
          pagingEnabled
          showsHorizontalScrollIndicator={false}
          onMomentumScrollEnd={onScrollEnd}
          onScroll={Animated.event(
            [{ nativeEvent: { contentOffset: { x: scrollX } } }],
            { useNativeDriver: false }
          )}
          renderItem={({ item }) => (
            <View style={styles.imageWrapper}>
              <Image 
                source={{ uri: item.photos }} 
                style={styles.carouselImage} 
                resizeMode="contain"
              />
            </View>
          )}
          keyExtractor={(_, index) => `img-${index}`}
        />
        
        {/* Bouton retour - En haut à gauche */}
        <TouchableOpacity style={styles.backButtonOverlay} onPress={() => navigation.goBack()}>
          <Ionicons name="arrow-back" size={24} color="#fff" />
        </TouchableOpacity>

        {/* Compteur d'images */}
        {maison.photos.length > 1 && (
          <View style={styles.imageCounter}>
            <Text style={styles.imageCounterText}>
              {currentImageIndex + 1}/{maison.photos.length}
            </Text>
          </View>
        )}

        {/* Indicateurs de page (dots) */}
        {maison.photos.length > 1 && (
          <View style={styles.indicatorsContainer}>
            {maison.photos.map((_, index) => {
              const inputRange = [(index - 1) * width, index * width, (index + 1) * width];
              const dotWidth = scrollX.interpolate({
                inputRange,
                outputRange: [6, 16, 6],
                extrapolate: 'clamp',
              });
              const opacity = scrollX.interpolate({
                inputRange,
                outputRange: [0.4, 1, 0.4],
                extrapolate: 'clamp',
              });
              return (
                <Animated.View
                  key={index}
                  style={[styles.indicator, { width: dotWidth, opacity }]}
                />
              );
            })}
          </View>
        )}
      </View>
    );
  };

  if (loading) {
    return (
      <SafeAreaView style={[styles.loadingContainer, isDarkMode && styles.darkContainer]}>
        <ActivityIndicator size="large" color={theme.primary} />
        <Text style={[styles.loadingText, isDarkMode && styles.darkText]}>Chargement...</Text>
      </SafeAreaView>
    );
  }

  if (!maison) {
    return (
      <SafeAreaView style={[styles.errorContainer, isDarkMode && styles.darkContainer]}>
        <FontAwesome name="home" size={60} color="#ccc" />
        <Text style={[styles.errorText, isDarkMode && styles.darkText]}>Maison non trouvée</Text>
        <TouchableOpacity style={styles.errorButton} onPress={() => navigation.goBack()}>
          <Text style={styles.errorButtonText}>Retour</Text>
        </TouchableOpacity>
      </SafeAreaView>
    );
  }

  return (
    <SafeAreaView style={[styles.container, isDarkMode && styles.darkContainer]}>
      <StatusBar barStyle={isDarkMode ? 'light-content' : 'dark-content'} backgroundColor={theme.background} translucent />
      
      <ScrollView 
        showsVerticalScrollIndicator={false}
        contentContainerStyle={styles.scrollContent}
      >
        {/* Carrousel d'images */}
        {renderImageCarousel()}

        {/* Contenu sous les images - TOUTES LES ICONES SONT ICI */}
        <View style={[styles.contentContainer, isDarkMode && styles.darkCard]}>
          
          {/* Ligne des actions (Like, Favori, Partager, Contact) - Intégrée dans le contenu */}
          <View style={styles.actionsRow}>
            <TouchableOpacity style={styles.actionButton} onPress={handleLike}>
              <FontAwesome 
                name={liked ? "heart" : "heart-o"} 
                size={24} 
                color={liked ? "#FF3B30" : (isDarkMode ? '#fff' : "#333")} 
              />
              <Text style={[styles.actionButtonText, isDarkMode && styles.darkSubText]}>
                {liked ? 'Aimé' : 'J\'aime'}
              </Text>
            </TouchableOpacity>

            <TouchableOpacity style={styles.actionButton} onPress={handleFavorite}>
              <FontAwesome 
                name={favorited ? "bookmark" : "bookmark-o"} 
                size={24} 
                color={favorited ? "#FFD700" : (isDarkMode ? '#fff' : "#333")} 
              />
              <Text style={[styles.actionButtonText, isDarkMode && styles.darkSubText]}>
                Favori
              </Text>
            </TouchableOpacity>

            <TouchableOpacity style={styles.actionButton} onPress={handleShare}>
              <FontAwesome name="share-alt" size={24} color={isDarkMode ? '#fff' : "#333"} />
              <Text style={[styles.actionButtonText, isDarkMode && styles.darkSubText]}>
                Partager
              </Text>
            </TouchableOpacity>

            <TouchableOpacity style={styles.actionButton} onPress={handleContact}>
              <FontAwesome name="whatsapp" size={24} color="#25D366" />
              <Text style={[styles.actionButtonText, isDarkMode && styles.darkSubText]}>
                WhatsApp
              </Text>
            </TouchableOpacity>
          </View>

          {/* Séparateur */}
          <View style={[styles.divider, isDarkMode && styles.darkBorder]} />

          {/* Prix */}
          <View style={styles.priceRow}>
            <Text style={[styles.price, { color: theme.primary }]}>
              {maison.prix?.toLocaleString()} FCFA
            </Text>
            <View style={[styles.typeBadge, maison.type_maison === 'vente' ? styles.saleBadge : styles.rentBadge]}>
              <Text style={styles.typeText}>
                {maison.type_maison === 'vente' ? 'À VENDRE' : 'À LOUER'}
              </Text>
            </View>
          </View>
           {/* Caractéristiques */}
          <View style={styles.section}>
            <Text style={[styles.sectionTitle, isDarkMode && styles.darkText]}>Caractéristiques</Text>
            <View style={styles.featuresGrid}>
              <View style={styles.featureItem}>
                <FontAwesome name="bed" size={22} color={theme.primary} />
                <Text style={[styles.featureValue, isDarkMode && styles.darkText]}>{maison.nombre_chambres}</Text>
                <Text style={[styles.featureLabel, isDarkMode && styles.darkSubText]}>Chambres</Text>
              </View>
              <View style={styles.featureItem}>
                <FontAwesome name="bath" size={22} color={theme.primary} />
                <Text style={[styles.featureValue, isDarkMode && styles.darkText]}>{maison.nombre_salles_de_bain}</Text>
                <Text style={[styles.featureLabel, isDarkMode && styles.darkSubText]}>Salles de bain</Text>
              </View>
              {maison.surface > 0 && (
                <View style={styles.featureItem}>
                  <FontAwesome name="expand" size={22} color={theme.primary} />
                  <Text style={[styles.featureValue, isDarkMode && styles.darkText]}>{maison.surface}</Text>
                  <Text style={[styles.featureLabel, isDarkMode && styles.darkSubText]}>m²</Text>
                </View>
              )}
            </View>
          </View>

          {/* Titre */}
          <Text style={[styles.title, isDarkMode && styles.darkText]}>{maison.titre || 'Propriété'}</Text>

          {/* Localisation */}
          <Text style={[styles.location, isDarkMode && styles.darkSubText]}>
            <Ionicons name="location-outline" size={16} color={isDarkMode ? '#aaa' : '#666'} />
            {' '}{maison.quartier}, {maison.ville}, {maison.pays || 'Niger'}
          </Text>

          {/* Description */}
          <Text style={[styles.description, isDarkMode && styles.darkText]}>{maison.description}</Text>

          {/* Séparateur */}
          <View style={[styles.divider, isDarkMode && styles.darkBorder]} />

          {/* Carte propriétaire */}
          <TouchableOpacity style={[styles.ownerCard, isDarkMode && styles.darkCardBorder]} onPress={goToProfile}>
            <View style={styles.ownerAvatarContainer}>
              {maison.owner_avatar ? (
                <Image source={{ uri: maison.owner_avatar }} style={styles.ownerAvatar} />
              ) : (
                <View style={[styles.ownerAvatarPlaceholder, { backgroundColor: theme.primary }]}>
                  <FontAwesome name="user" size={24} color="#fff" />
                </View>
              )}
            </View>
            <View style={styles.ownerInfo}>
              <Text style={[styles.ownerName, isDarkMode && styles.darkText]}>{maison.owner_name || 'Propriétaire'}</Text>
              <Text style={[styles.ownerBadge, { color: theme.success }]}>
                {maison.owner?.is_proprietaire ? '✓ Propriétaire vérifié' : 'Propriétaire'}
              </Text>
            </View>
            <TouchableOpacity style={[styles.contactButtonMini, { backgroundColor: theme.primary }]} onPress={handleContact}>
              <Text style={styles.contactButtonMiniText}>Contacter</Text>
            </TouchableOpacity>
          </TouchableOpacity>

         

          {/* Équipements */}
          {['piscine', 'jardin', 'garage', 'climatiseur', 'internet', 'meuble'].some(key => maison[key]) && (
            <View style={styles.section}>
              <Text style={[styles.sectionTitle, isDarkMode && styles.darkText]}>Équipements</Text>
              <View style={styles.amenitiesGrid}>
                {maison.piscine && (
                  <View style={[styles.amenityItem, isDarkMode && styles.darkCardBorder]}>
                    <FontAwesome name="tint" size={16} color="#00BCD4" />
                    <Text style={[styles.amenityText, isDarkMode && styles.darkText]}>Piscine</Text>
                  </View>
                )}
                {maison.jardin && (
                  <View style={[styles.amenityItem, isDarkMode && styles.darkCardBorder]}>
                    <FontAwesome name="tree" size={16} color="#4CAF50" />
                    <Text style={[styles.amenityText, isDarkMode && styles.darkText]}>Jardin</Text>
                  </View>
                )}
                {maison.garage && (
                  <View style={[styles.amenityItem, isDarkMode && styles.darkCardBorder]}>
                    <FontAwesome name="car" size={16} color="#FF9800" />
                    <Text style={[styles.amenityText, isDarkMode && styles.darkText]}>Garage</Text>
                  </View>
                )}
                {maison.climatiseur && (
                  <View style={[styles.amenityItem, isDarkMode && styles.darkCardBorder]}>
                    <FontAwesome name="snowflake-o" size={16} color="#2196F3" />
                    <Text style={[styles.amenityText, isDarkMode && styles.darkText]}>Climatisation</Text>
                  </View>
                )}
                {maison.internet && (
                  <View style={[styles.amenityItem, isDarkMode && styles.darkCardBorder]}>
                    <FontAwesome name="wifi" size={16} color="#9C27B0" />
                    <Text style={[styles.amenityText, isDarkMode && styles.darkText]}>WiFi</Text>
                  </View>
                )}
                {maison.meuble && (
                  <View style={[styles.amenityItem, isDarkMode && styles.darkCardBorder]}>
                    <FontAwesome name="couch" size={16} color="#795548" />
                    <Text style={[styles.amenityText, isDarkMode && styles.darkText]}>Meublé</Text>
                  </View>
                )}
              </View>
            </View>
          )}
        </View>
        
        <View style={styles.bottomSpacer} />
      </ScrollView>
    </SafeAreaView>
  );
};

const themedStyles = (theme, isDarkMode, Platform, StatusBar) => StyleSheet.create({
  container: { flex: 1, backgroundColor: theme.background },
  darkContainer: { backgroundColor: '#1a1a1a' },
  darkCard: { backgroundColor: '#2d2d2d' },
  darkCardBorder: { backgroundColor: '#2d2d2d', borderWidth: 1, borderColor: '#3d3d3d' },
  darkText: { color: '#fff' },
  darkSubText: { color: '#aaa' },
  darkBorder: { backgroundColor: '#3d3d3d' },
  
  scrollContent: {
    flexGrow: 1,
  },
  
  loadingContainer: { flex: 1, justifyContent: 'center', alignItems: 'center', backgroundColor: theme.background },
  loadingText: { marginTop: 10, color: theme.subText },
  errorContainer: { flex: 1, justifyContent: 'center', alignItems: 'center', backgroundColor: theme.background, padding: 20 }, // ← CORRIGÉ
  errorText: { fontSize: 18, color: theme.subText, marginTop: 20, marginBottom: 30 },
  errorButton: { backgroundColor: theme.primary, paddingHorizontal: 30, paddingVertical: 12, borderRadius: 10 },
  errorButtonText: { color: '#fff', fontSize: 16, fontWeight: '600' },
  
  // Carrousel - IMAGE ENTIÈRE
  carouselContainer: { 
    height: 600, 
    position: 'relative',
    backgroundColor: '#807e7e',
  },
  imageWrapper: {
    width: width,
    height: 600,
    justifyContent: 'center',
    alignItems: 'center',
    backgroundColor: '#fff',
  },
  carouselImage: { 
    width: width,
    height: 600,
  },
  noImagesContainer: { height: 600, justifyContent: 'center', alignItems: 'center', backgroundColor: theme.background },
  noImagesText: { color: theme.subText, marginTop: 10 },
  
  // Bouton retour
  backButtonOverlay: { 
    position: 'absolute', 
    top: 16, 
    left: 16,
    width: 40,
    height: 40,
    borderRadius: 20,
    backgroundColor: 'rgba(128, 127, 127, 0.5)',
    justifyContent: 'center',
    alignItems: 'center',
  },
  
  // Compteur d'images
  imageCounter: { 
    position: 'absolute', 
    top: 16, 
    alignSelf: 'center',
    backgroundColor: 'rgba(0,0,0,0.6)',
    paddingHorizontal: 12, 
    paddingVertical: 4, 
    borderRadius: 20,
  },
  imageCounterText: { color: '#fff', fontSize: 12, fontWeight: '600' },
  
  // Indicateurs de page (dots)
  indicatorsContainer: { 
    position: 'absolute', 
    bottom: 16, 
    left: 0, 
    right: 0, 
    flexDirection: 'row', 
    justifyContent: 'center', 
    alignItems: 'center' 
  },
  indicator: { 
    height: 4, 
    borderRadius: 2, 
    backgroundColor: '#fff', 
    marginHorizontal: 4 
  },
  
  // Contenu sous les images
  content:{
    paddingTop: Platform.OS === 'android' ? StatusBar.currentHeight : 0, 
    padding: 20,
  },
  
  // Ligne d'actions intégrée
  actionsRow: {
    flexDirection: 'row',
    justifyContent: 'space-around',
    alignItems: 'center',
    marginBottom: 16,
  },
  actionButton: {
    alignItems: 'center',
    paddingVertical: 8,
  },
  actionButtonText: {
    fontSize: 12,
    marginTop: 4,
    color: '#666',
  },
  
  divider: {
    height: 1,
    backgroundColor: '#e8e8e8',
    marginVertical: 16,
  },
  
  priceRow: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 },
  price: { fontSize: 28, fontWeight: 'bold' },
  typeBadge: { paddingHorizontal: 14, paddingVertical: 6, borderRadius: 20 },
  saleBadge: { backgroundColor: theme.success + '20' },
  rentBadge: { backgroundColor: theme.primary + '20' },
  typeText: { fontSize: 12, fontWeight: 'bold', color: theme.primary },
  
  title: { fontSize: 22, fontWeight: 'bold', marginBottom: 8 },
  location: { fontSize: 14, marginBottom: 16 },
  description: { fontSize: 15, lineHeight: 22, marginBottom: 16 },
  
  // Carte propriétaire
  ownerCard: { 
    flexDirection: 'row', 
    alignItems: 'center', 
    backgroundColor: theme.card, 
    padding: 15, 
    borderRadius: 16, 
    marginBottom: 24,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.05,
    shadowRadius: 4,
    elevation: 2,
  },
  ownerAvatarContainer: { marginRight: 14 },
  ownerAvatar: { width: 52, height: 52, borderRadius: 26 },
  ownerAvatarPlaceholder: { width: 52, height: 52, borderRadius: 26, justifyContent: 'center', alignItems: 'center' },
  ownerInfo: { flex: 1 },
  ownerName: { fontSize: 16, fontWeight: 'bold', marginBottom: 4 },
  ownerBadge: { fontSize: 12, marginTop: 2 },
  contactButtonMini: { paddingHorizontal: 18, paddingVertical: 10, borderRadius: 25 },
  contactButtonMiniText: { color: '#fff', fontSize: 14, fontWeight: '600' },
  
  section: { marginBottom: 24 },
  sectionTitle: { fontSize: 18, fontWeight: 'bold', marginBottom: 16 },
  featuresGrid: { flexDirection: 'row', justifyContent: 'space-around' },
  featureItem: { alignItems: 'center' },
  featureValue: { fontSize: 18, fontWeight: 'bold', marginTop: 8, marginBottom: 4 },
  featureLabel: { fontSize: 12 },
  
  amenitiesGrid: { flexDirection: 'row', flexWrap: 'wrap', gap: 10 },
  amenityItem: { 
    flexDirection: 'row', 
    alignItems: 'center', 
    backgroundColor: theme.background, 
    paddingHorizontal: 14, 
    paddingVertical: 8, 
    borderRadius: 25, 
    gap: 8,
    borderWidth: 1,
    borderColor: theme.border,
  },
  amenityText: { fontSize: 14 },
  
  bottomSpacer: { height: 30 },
});

export default MaisonDetail;




