import React, { useState, useEffect, useCallback } from 'react';
import { Platform, StatusBar, 
  View,
  Text,
  StyleSheet,
  ScrollView,
  RefreshControl,
  ActivityIndicator,
  TouchableOpacity
} from 'react-native';
import Ionicons from 'react-native-vector-icons/Ionicons';
import { useFocusEffect } from '@react-navigation/native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import axios from 'axios';
import Config from './Config';
import {useTheme } from '../context/ThemeContext.js';
import {  useThemedStyles } from '../hooks/useThemedStyles';

const Dashboard = () => {
  const { isDarkMode } = useTheme();
  const { createThemedStyles, theme } = useThemedStyles();
  const styles = createThemedStyles(themedStyles);
  
  const [stats, setStats] = useState({
    totalProperties: 0,
    activeListings: 0,
    totalViews: 0,
    totalMessages: 0,
    recentActivities: []
  });
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);

  useFocusEffect(
    useCallback(() => {
      fetchDashboardData();
    }, [])
  );

  const fetchDashboardData = async () => {
    try {
      const token = await AsyncStorage.getItem('access_token');
      if (!token) return;

      const [propertiesRes, statsRes, activitiesRes] = await Promise.all([
        axios.get(`${Config.BASE_URL}/api/properties/my-properties/`, {
          headers: { Authorization: `Bearer ${token}` }
        }),
        axios.get(`${Config.BASE_URL}/api/dashboard/stats/`, {
          headers: { Authorization: `Bearer ${token}` }
        }),
        axios.get(`${Config.BASE_URL}/api/dashboard/recent-activities/`, {
          headers: { Authorization: `Bearer ${token}` }
        })
      ]);

      setStats({
        totalProperties: propertiesRes.data.length,
        activeListings: propertiesRes.data.filter(p => p.status === 'available').length,
        totalViews: statsRes.data.total_views || 0,
        totalMessages: statsRes.data.total_messages || 0,
        recentActivities: activitiesRes.data || []
      });
    } catch (error) {
      console.error('Erreur chargement dashboard:', error);
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  const onRefresh = () => {
    setRefreshing(true);
    fetchDashboardData();
  };

  const StatCard = ({ title, value, icon, color, onPress }) => (
    <TouchableOpacity style={styles.statCard} onPress={onPress} activeOpacity={0.7}>
      <View style={[styles.statIcon, { backgroundColor: color + '20' }]}>
        <Ionicons name={icon} size={30} color={color} />
      </View>
      <View style={styles.statInfo}>
        <Text style={[styles.statValue, isDarkMode && styles.darkText]}>{value}</Text>
        <Text style={[styles.statTitle, isDarkMode && styles.darkSubText]}>{title}</Text>
      </View>
    </TouchableOpacity>
  );

  const ActivityItem = ({ activity }) => (
    <View style={styles.activityItem}>
      <View style={[styles.activityIcon, { backgroundColor: theme.primary + '20' }]}>
        <Ionicons name={activity.icon || 'notifications'} size={20} color={theme.primary} />
      </View>
      <View style={styles.activityContent}>
        <Text style={[styles.activityText, isDarkMode && styles.darkText]}>{activity.message}</Text>
        <Text style={[styles.activityTime, isDarkMode && styles.darkSubText]}>{activity.time_ago}</Text>
      </View>
    </View>
  );

  if (loading) {
    return (
      <View style={[styles.container, isDarkMode && styles.darkContainer, styles.centerContent]}>
        <ActivityIndicator size="large" color={theme.primary} />
      </View>
    );
  }

  return (
    <ScrollView 
      style={[styles.container, isDarkMode && styles.darkContainer]}
      refreshControl={<RefreshControl refreshing={refreshing} onRefresh={onRefresh} />}
    >
      <View style={styles.header}>
        <Text style={[styles.headerTitle, isDarkMode && styles.darkText]}>Tableau de bord</Text>
        <Text style={[styles.headerSubtitle, isDarkMode && styles.darkSubText]}>
          Vue d'ensemble de votre activité
        </Text>
      </View>

      <View style={styles.statsGrid}>
        <StatCard 
          title="Mes biens"
          value={stats.totalProperties}
          icon="home"
          color={theme.primary}
          onPress={() => {}}
        />
        <StatCard 
          title="Annonces actives"
          value={stats.activeListings}
          icon="megaphone"
          color={theme.success}
          onPress={() => {}}
        />
        <StatCard 
          title="Vues totales"
          value={stats.totalViews}
          icon="eye"
          color={theme.warning}
          onPress={() => {}}
        />
        <StatCard 
          title="Messages"
          value={stats.totalMessages}
          icon="chatbubbles"
          color={theme.info}
          onPress={() => {}}
        />
      </View>

      <View style={styles.section}>
        <Text style={[styles.sectionTitle, isDarkMode && styles.darkText]}>Activités récentes</Text>
        {stats.recentActivities.length === 0 ? (
          <View style={styles.emptyActivities}>
            <Ionicons name="time-outline" size={50} color={theme.subText} />
            <Text style={[styles.emptyText, isDarkMode && styles.darkSubText]}>
              Aucune activité récente
            </Text>
          </View>
        ) : (
          stats.recentActivities.map((activity, index) => (
            <ActivityItem key={index} activity={activity} />
          ))
        )}
      </View>

      <View style={styles.quickActions}>
        <Text style={[styles.sectionTitle, isDarkMode && styles.darkText]}>Actions rapides</Text>
        <View style={styles.actionsGrid}>
          <TouchableOpacity style={styles.actionButton}>
            <Ionicons name="add-circle" size={24} color={theme.primary} />
            <Text style={styles.actionText}>Ajouter un bien</Text>
          </TouchableOpacity>
          <TouchableOpacity style={styles.actionButton}>
            <Ionicons name="pulse" size={24} color={theme.primary} />
            <Text style={styles.actionText}>Voir les stats</Text>
          </TouchableOpacity>
          <TouchableOpacity style={styles.actionButton}>
            <Ionicons name="chatbubble" size={24} color={theme.primary} />
            <Text style={styles.actionText}>Messages</Text>
          </TouchableOpacity>
        </View>
      </View>
    </ScrollView>
  );
};

const themedStyles = (theme, isDarkMode, Platform, StatusBar) => StyleSheet.create({
  container: {
          flex: 1,
          backgroundColor: theme.background,
          paddingTop: Platform.OS === 'android' ? StatusBar.currentHeight : 0,
        },
  darkContainer: { backgroundColor: '#1a1a1a' },
  darkText: { color: '#fff' },
  darkSubText: { color: '#aaa' },
  
  centerContent: { justifyContent: 'center', alignItems: 'center' },
  
  header: { padding: 20, backgroundColor: theme.card, marginBottom: 15 },
  headerTitle: { fontSize: 28, fontWeight: 'bold', color: theme.text, marginBottom: 5 },
  headerSubtitle: { fontSize: 14, color: theme.subText },
  
  statsGrid: { flexDirection: 'row', flexWrap: 'wrap', paddingHorizontal: 10, gap: 10 },
  statCard: {
    flex: 1,
    minWidth: '45%',
    backgroundColor: theme.card,
    borderRadius: 12,
    padding: 15,
    flexDirection: 'row',
    alignItems: 'center',
    gap: 15,
    elevation: 2,
  },
  statIcon: { width: 50, height: 50, borderRadius: 25, justifyContent: 'center', alignItems: 'center' },
  statInfo: { flex: 1 },
  statValue: { fontSize: 24, fontWeight: 'bold', color: theme.text },
  statTitle: { fontSize: 12, color: theme.subText, marginTop: 2 },
  
  section: { marginTop: 20, paddingHorizontal: 20 },
  sectionTitle: { fontSize: 18, fontWeight: 'bold', color: theme.text, marginBottom: 15 },
  
  activityItem: { flexDirection: 'row', alignItems: 'center', marginBottom: 15, gap: 12 },
  activityIcon: { width: 40, height: 40, borderRadius: 20, justifyContent: 'center', alignItems: 'center' },
  activityContent: { flex: 1 },
  activityText: { fontSize: 14, color: theme.text, marginBottom: 4 },
  activityTime: { fontSize: 12, color: theme.subText },
  
  emptyActivities: { alignItems: 'center', padding: 30 },
  emptyText: { fontSize: 14, color: theme.subText, marginTop: 10 },
  
  quickActions: { marginTop: 20, marginBottom: 30, paddingHorizontal: 20 },
  actionsGrid: { flexDirection: 'row', gap: 15 },
  actionButton: { flex: 1, backgroundColor: theme.card, padding: 15, borderRadius: 12, alignItems: 'center', gap: 8 },
  actionText: { fontSize: 12, color: theme.primary, fontWeight: '500' },
});

export default Dashboard;


