import React, { useState } from 'react';
import {
  View,
  Text,
  TextInput,
  Image,
  TouchableOpacity,
  StyleSheet,
  KeyboardAvoidingView,
  Platform,
  SafeAreaView,
  ScrollView,
  StatusBar,
  Alert,
  ActivityIndicator
} from 'react-native';
import Ionicons from 'react-native-vector-icons/Ionicons';
import axios from 'axios';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { API_URL } from '../components/Config'; // IMPORTANT

export default function LoginScreen({ navigation }) {
  const [phone_number, setPhone_number] = useState(''); // RENOMMÉ pour clarté
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [loading, setLoading] = useState(false);
  const [isFocused, setIsFocused] = useState({
    phone: false,
    password: false,
  });

  const handleFocus = (field) => {
    setIsFocused(prev => ({ ...prev, [field]: true }));
  };

  const handleBlur = (field) => {
    setIsFocused(prev => ({ ...prev, [field]: false }));
  };

  const handlePasswordToggle = () => {
    setShowPassword(!showPassword);
  };

  const handleLogin = async () => {
    if (loading) return;

    if (!phone_number || !password) {
      Alert.alert("Erreur", "Tous les champs sont obligatoires !");
      return;
    }

    try {
      setLoading(true);

      // 📍 LOG POUR DEBUG
      console.log('🔍 Tentative de connexion...');
      console.log('   URL:', `${API_URL}/login/`);
      console.log('   Phone:', phone_number);

      // ✅ CORRECT - Utilise phone_number comme demandé par le serializer
      const response = await axios.post(`${API_URL}/login/`, {
        phone_number: phone_number,
        password: password,
      });

      console.log('✅ Connexion réussie!', response.status);

      const { access, refresh, user } = response.data;

      // Stocker les tokens
      await AsyncStorage.setItem('access_token', access);
      await AsyncStorage.setItem('refresh_token', refresh);
      await AsyncStorage.setItem('user', JSON.stringify(user));

      Alert.alert(
        "✅ Connexion réussie",
        `Bienvenue ${user.username} !`,
        [{ text: 'OK', onPress: () => navigation.replace('Accueil') }]
      );

    } catch (error) {
      console.error('❌ Erreur login:', error.response?.data || error.message);
      
      let errorMessage = "Identifiants incorrects.";
      
      if (error.response) {
        // Afficher l'erreur exacte du backend
        console.log('   Statut:', error.response.status);
        console.log('   Données:', error.response.data);
        
        if (error.response.data && typeof error.response.data === 'object') {
          if (error.response.data.non_field_errors) {
            errorMessage = error.response.data.non_field_errors[0];
          } else if (error.response.data.detail) {
            errorMessage = error.response.data.detail;
          } else if (error.response.data.phone_number) {
            errorMessage = error.response.data.phone_number[0];
          } else {
            // Si c'est un autre type d'erreur
            errorMessage = JSON.stringify(error.response.data);
          }
        }
      } else if (error.code === 'ECONNABORTED') {
        errorMessage = 'Délai d\'attente dépassé. Vérifiez votre connexion.';
      } else if (error.message === 'Network Error') {
        errorMessage = 'Impossible de joindre le serveur. Vérifiez l\'URL.';
      }
      
      Alert.alert("❌ Erreur de connexion", errorMessage);
    } finally {
      setLoading(false);
    }
  };

  const handleSignUp = () => {
    navigation.navigate('RegistrationScreen');
  };

  return (
    <SafeAreaView style={styles.container}>
      <StatusBar barStyle="dark-content" />

      <KeyboardAvoidingView
        style={styles.container}
        behavior={Platform.OS === 'ios' ? 'padding' : 'height'}
      >
        <ScrollView
          contentContainerStyle={styles.scrollViewContent}
          keyboardShouldPersistTaps="handled"
          showsVerticalScrollIndicator={false}
        >

          <View style={styles.header}>
            <Image
              source={require('../assets/villanaicon.png')}
              style={styles.logo}
            />
            <TouchableOpacity
              style={styles.skipButton}
              onPress={() => navigation.navigate("Accueil")}
            >
              <Text style={styles.skipButtonText}>Ignorer</Text>
            </TouchableOpacity>
          </View>

          <View style={styles.form}>

            <TextInput
              value={phone_number}
              onChangeText={setPhone_number}
              placeholder="Numéro de téléphone"
              placeholderTextColor="grey"
              style={[styles.input, isFocused.phone && styles.inputFocused]}
              onFocus={() => handleFocus('phone')}
              onBlur={() => handleBlur('phone')}
              autoCapitalize="none"
              keyboardType="phone-pad"
              editable={!loading}
            />

            <View style={styles.passwordContainer}>
              <TextInput
                value={password}
                onChangeText={setPassword}
                placeholder="Mot de passe"
                placeholderTextColor="grey"
                secureTextEntry={!showPassword}
                style={[styles.input, isFocused.password && styles.inputFocused]}
                onFocus={() => handleFocus('password')}
                onBlur={() => handleBlur('password')}
                autoCapitalize="none"
                editable={!loading}
              />

              <TouchableOpacity
                onPress={handlePasswordToggle}
                style={styles.showPasswordButton}
                disabled={loading}
              >
                <Ionicons
                  name={showPassword ? 'eye-off' : 'eye'}
                  size={20}
                  color={showPassword ? '#00BFFF' : 'grey'}
                />
              </TouchableOpacity>
            </View>

            <TouchableOpacity onPress={() => navigation.navigate('ForgotPassword')}>
              <Text style={styles.forgotPasswordText}>
                Mot de passe oublié ?
              </Text>
            </TouchableOpacity>

            <TouchableOpacity
              onPress={handleLogin}
              style={[styles.loginButton, loading && styles.loginButtonDisabled]}
              disabled={loading}
            >
              {loading ? (
                <ActivityIndicator color="#fff" />
              ) : (
                <Text style={styles.loginButtonText}>
                  Se Connecter
                </Text>
              )}
            </TouchableOpacity>

            <TouchableOpacity
              style={styles.signupButton}
              onPress={handleSignUp}
              disabled={loading}
            >
              <Text style={styles.signupButtonText}>
                S'inscrire
              </Text>
            </TouchableOpacity>

          </View>
        </ScrollView>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: 'white',
  },
  header: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginTop: 70,
    paddingHorizontal: 16,
  },
  skipButton: {
    backgroundColor: '#0F4C81',
    paddingVertical: 8,
    paddingHorizontal: 16,
    borderRadius: 8,
  },
  skipButtonText: {
    color: 'white',
    fontSize: 16,
  },
  logo: {
    height: 60,
    width: 140,
    resizeMode: 'contain',
  },
  form: {
    paddingHorizontal: 26,
    paddingTop: 50,
    flex: 1,
  },
  scrollViewContent: {
    flexGrow: 1,
  },
  input: {
    color: 'black',
    borderColor: 'grey',
    borderWidth: 1,
    borderRadius: 8,
    marginBottom: 16,
    padding: 12,
    fontSize: 16,
    width: '100%',
  },
  inputFocused: {
    borderColor: '#0F4C81',
    borderWidth: 2,
  },
  passwordContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    marginBottom: 16,
    position: 'relative',
  },
  showPasswordButton: {
    position: 'absolute',
    right: 10,
    top: '50%',
    transform: [{ translateY: -10 }],
  },
  forgotPasswordText: {
    color: 'grey',
    textAlign: 'left',
    marginVertical: 8,
  },
  loginButton: {
    backgroundColor: '#0F4C81',
    borderRadius: 8,
    padding: 16,
    alignItems: 'center',
    marginTop: 32,
  },
  loginButtonDisabled: {
    backgroundColor: '#7A9EBA',
  },
  loginButtonText: {
    color: 'white',
    fontSize: 18,
    fontWeight: '600',
  },
  signupButton: {
    backgroundColor: 'white',
    borderRadius: 8,
    padding: 16,
    alignItems: 'center',
    marginTop: 16,
    borderWidth: 1,
    borderColor: '#0F4C81',
  },
  signupButtonText: {
    color: '#0F4C81',
    fontSize: 18,
    fontWeight: '600',
  },
});
