import React, { useState } from 'react';
import { Platform, StatusBar, 
  View,
  Text,
  StyleSheet,
  ScrollView,
  TouchableOpacity,
  TextInput,
  Linking
} from 'react-native';
import Ionicons from 'react-native-vector-icons/Ionicons';
import { useTheme } from '../context/ThemeContext.js';
import {useThemedStyles } from '../hooks/useThemedStyles';

const Help = () => {
  const { isDarkMode } = useTheme();
  const { createThemedStyles, theme } = useThemedStyles();
  const styles = createThemedStyles(themedStyles);
  
  const [searchQuery, setSearchQuery] = useState('');
  const [expandedFaq, setExpandedFaq] = useState(null);

  const faqs = [
    {
      id: 1,
      question: "Comment publier une annonce ?",
      answer: "Pour publier une annonce, allez dans l'onglet 'Mes biens' puis cliquez sur le bouton '+' en haut à droite. Remplissez tous les champs requis et soumettez votre annonce."
    },
    {
      id: 2,
      question: "Comment contacter un propriétaire ?",
      answer: "Sur la fiche d'un bien, cliquez sur 'Contacter' pour envoyer un message directement au propriétaire. Vous pouvez aussi voir son numéro s'il l'a rendu public."
    },
    {
      id: 3,
      question: "Comment devenir professionnel ?",
      answer: "Allez dans le menu 'Devenir pro' et remplissez le formulaire avec vos informations professionnelles. Notre équipe vous contactera sous 48h."
    },
    {
      id: 4,
      question: "Comment modifier mon profil ?",
      answer: "Cliquez sur votre photo de profil dans le menu principal, puis sur 'Modifier le profil' pour mettre à jour vos informations."
    },
    {
      id: 5,
      question: "Comment signaler une annonce ?",
      answer: "Sur la page de détail d'une annonce, cliquez sur les trois points en haut à droite et sélectionnez 'Signaler'."
    }
  ];

  const contactMethods = [
    { icon: 'chatbubble', title: 'Chat en ligne', description: 'Réponse instantanée', action: () => {} },
    { icon: 'call', title: 'Appeler', description: '+221 78 123 45 67', action: () => Linking.openURL('tel:+221781234567') },
    { icon: 'mail', title: 'Email', description: 'support@villana.com', action: () => Linking.openURL('mailto:support@villana.com') },
    { icon: 'logo-whatsapp', title: 'WhatsApp', description: '+221 78 123 45 67', action: () => Linking.openURL('https://wa.me/221781234567') }
  ];

  const filteredFaqs = faqs.filter(faq => 
    faq.question.toLowerCase().includes(searchQuery.toLowerCase()) ||
    faq.answer.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <ScrollView style={[styles.container, isDarkMode && styles.darkContainer]}>
      <View style={styles.header}>
        <Text style={[styles.headerTitle, isDarkMode && styles.darkText]}>Centre d'aide</Text>
        <Text style={[styles.headerSubtitle, isDarkMode && styles.darkSubText]}>
          Comment pouvons-nous vous aider ?
        </Text>
      </View>

      <View style={styles.searchSection}>
        <View style={[styles.searchContainer, isDarkMode && styles.darkCard]}>
          <Ionicons name="search" size={20} color={theme.subText} />
          <TextInput
            style={[styles.searchInput, isDarkMode && styles.darkText]}
            placeholder="Rechercher une question..."
            placeholderTextColor={theme.subText}
            value={searchQuery}
            onChangeText={setSearchQuery}
          />
        </View>
      </View>

      <View style={styles.faqSection}>
        <Text style={[styles.sectionTitle, isDarkMode && styles.darkText]}>Questions fréquentes</Text>
        {filteredFaqs.map((faq) => (
          <TouchableOpacity 
            key={faq.id}
            style={[styles.faqItem, isDarkMode && styles.darkCard]}
            onPress={() => setExpandedFaq(expandedFaq === faq.id ? null : faq.id)}
          >
            <View style={styles.faqHeader}>
              <Text style={[styles.faqQuestion, isDarkMode && styles.darkText]}>{faq.question}</Text>
              <Ionicons 
                name={expandedFaq === faq.id ? 'chevron-up' : 'chevron-down'} 
                size={20} 
                color={theme.primary} 
              />
            </View>
            {expandedFaq === faq.id && (
              <Text style={[styles.faqAnswer, isDarkMode && styles.darkSubText]}>{faq.answer}</Text>
            )}
          </TouchableOpacity>
        ))}
      </View>

      <View style={styles.contactSection}>
        <Text style={[styles.sectionTitle, isDarkMode && styles.darkText]}>Nous contacter</Text>
        <View style={styles.contactGrid}>
          {contactMethods.map((method, index) => (
            <TouchableOpacity 
              key={index}
              style={[styles.contactCard, isDarkMode && styles.darkCard]}
              onPress={method.action}
            >
              <View style={[styles.contactIcon, { backgroundColor: theme.primary + '20' }]}>
                <Ionicons name={method.icon} size={30} color={theme.primary} />
              </View>
              <Text style={[styles.contactTitle, isDarkMode && styles.darkText]}>{method.title}</Text>
              <Text style={[styles.contactDesc, isDarkMode && styles.darkSubText]}>{method.description}</Text>
            </TouchableOpacity>
          ))}
        </View>
      </View>

      <View style={styles.resourcesSection}>
        <Text style={[styles.sectionTitle, isDarkMode && styles.darkText]}>Ressources utiles</Text>
        <View style={styles.resourceList}>
          <TouchableOpacity style={styles.resourceItem}>
            <Ionicons name="document-text" size={24} color={theme.primary} />
            <View style={styles.resourceContent}>
              <Text style={[styles.resourceTitle, isDarkMode && styles.darkText]}>Guide d'utilisation</Text>
              <Text style={[styles.resourceDesc, isDarkMode && styles.darkSubText]}>Téléchargez notre guide complet</Text>
            </View>
          </TouchableOpacity>
          <TouchableOpacity style={styles.resourceItem}>
            <Ionicons name="videocam" size={24} color={theme.primary} />
            <View style={styles.resourceContent}>
              <Text style={[styles.resourceTitle, isDarkMode && styles.darkText]}>Tutoriels vidéo</Text>
              <Text style={[styles.resourceDesc, isDarkMode && styles.darkSubText]}>Regardez nos vidéos explicatives</Text>
            </View>
          </TouchableOpacity>
        </View>
      </View>
    </ScrollView>
  );
};

const themedStyles = (theme, isDarkMode, Platform, StatusBar) => StyleSheet.create({
  container: {
          flex: 1,
          backgroundColor: theme.background,
          paddingTop: Platform.OS === 'android' ? StatusBar.currentHeight : 0,
        },
  darkContainer: { backgroundColor: '#1a1a1a' },
  darkText: { color: '#fff' },
  darkSubText: { color: '#aaa' },
  darkCard: { backgroundColor: '#2d2d2d' },
  
  header: { padding: 20, backgroundColor: theme.card, marginBottom: 15 },
  headerTitle: { fontSize: 28, fontWeight: 'bold', color: theme.text, marginBottom: 5 },
  headerSubtitle: { fontSize: 14, color: theme.subText },
  
  searchSection: { paddingHorizontal: 20, marginBottom: 20 },
  searchContainer: { flexDirection: 'row', alignItems: 'center', backgroundColor: theme.card, borderRadius: 12, paddingHorizontal: 15, borderWidth: 1, borderColor: theme.border },
  searchInput: { flex: 1, paddingVertical: 12, marginLeft: 10, fontSize: 16 },
  
  faqSection: { paddingHorizontal: 20, marginBottom: 20 },
  sectionTitle: { fontSize: 20, fontWeight: 'bold', color: theme.text, marginBottom: 15 },
  faqItem: { backgroundColor: theme.card, borderRadius: 10, padding: 15, marginBottom: 10 },
  faqHeader: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center' },
  faqQuestion: { fontSize: 16, fontWeight: '600', color: theme.text, flex: 1, marginRight: 10 },
  faqAnswer: { fontSize: 14, color: theme.subText, marginTop: 10, lineHeight: 20 },
  
  contactSection: { paddingHorizontal: 20, marginBottom: 20 },
  contactGrid: { flexDirection: 'row', flexWrap: 'wrap', gap: 15 },
  contactCard: { flex: 1, minWidth: '45%', backgroundColor: theme.card, padding: 15, borderRadius: 12, alignItems: 'center' },
  contactIcon: { width: 50, height: 50, borderRadius: 25, justifyContent: 'center', alignItems: 'center', marginBottom: 10 },
  contactTitle: { fontSize: 14, fontWeight: '600', color: theme.text, marginBottom: 5 },
  contactDesc: { fontSize: 12, color: theme.subText, textAlign: 'center' },
  
  resourcesSection: { paddingHorizontal: 20, marginBottom: 30 },
  resourceList: { gap: 10 },
  resourceItem: { flexDirection: 'row', alignItems: 'center', backgroundColor: theme.card, padding: 15, borderRadius: 10, gap: 15 },
  resourceContent: { flex: 1 },
  resourceTitle: { fontSize: 16, fontWeight: '600', color: theme.text, marginBottom: 4 },
  resourceDesc: { fontSize: 12, color: theme.subText },
});

export default Help;


