// ProfileScreen.js (Version corrigée avec redirection vers Login)
import React, { useState, useEffect } from 'react';
import { Platform, StatusBar, 
  View,
  Text,
  Image,
  TouchableOpacity,
  StyleSheet,
  SafeAreaView,
  ScrollView,
  ActivityIndicator,
  Alert,
  RefreshControl,
  Share
} from 'react-native';
import FontAwesome from 'react-native-vector-icons/FontAwesome';
import Ionicons from 'react-native-vector-icons/Ionicons';
import MaterialIcons from 'react-native-vector-icons/MaterialIcons';
import {  useNavigation, useFocusEffect } from '@react-navigation/native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import axios from 'axios';
import Config from './Config';

const ProfileScreen = ({ route }) => {
  const navigation = useNavigation();
  const { userId: routeUserId } = route.params || {};

  const [user, setUser] = useState(null);
  const [currentUserId, setCurrentUserId] = useState(null);
  const [loading, setLoading] = useState(true);
  const [refreshing, setRefreshing] = useState(false);
  const [stats, setStats] = useState({
    annonces: 0,
    favoris: 0,
    commentaires: 0
  });
  const [userProperties, setUserProperties] = useState([]);
  const [isOwner, setIsOwner] = useState(false);
  const [token, setToken] = useState('');

  useFocusEffect(
    React.useCallback(() => {
      checkAuthAndLoad();
    }, [routeUserId])
  );

  const checkAuthAndLoad = async () => {
    const accessToken = await AsyncStorage.getItem('access_token');
    const userData = await AsyncStorage.getItem('user');
    
    // ✅ REDIRIGER VERS LOGIN SI NON CONNECTÉ
    if (!accessToken || !userData) {
      setLoading(false);
      navigation.replace('LoginScreen');
      return;
    }
    
    await loadInitialData();
  };

  const loadInitialData = async () => {
    await loadTokenAndUser();
  };

  const loadTokenAndUser = async () => {
    try {
      setLoading(true);
      const accessToken = await AsyncStorage.getItem('access_token');
      setToken(accessToken);

      const userData = await AsyncStorage.getItem('user');
      if (userData) {
        const currentUser = JSON.parse(userData);
        setCurrentUserId(currentUser.id);
      }

      await loadUserProfile(accessToken);
    } catch (error) {
      console.error('Erreur chargement token:', error);
    } finally {
      setLoading(false);
      setRefreshing(false);
    }
  };

  const loadUserProfile = async (accessToken) => {
    const endpoint = `${Config.BASE_URL}/profile/`;

    try {
      const response = await axios.get(endpoint, {
        headers: { Authorization: `Bearer ${accessToken}` }
      });

      if (response.data) {
        const userData = response.data;
        setUser(userData);
        setIsOwner(true);

        await loadUserStats(accessToken);
        await loadUserProperties(accessToken);
      }
    } catch (error) {
      console.error('❌ Erreur chargement profil:', error);
      Alert.alert('Erreur', 'Impossible de charger votre profil.');
    }
  };

  const loadUserStats = async (accessToken) => {
    try {
      const [maisonsRes, favorisRes] = await Promise.all([
        axios.get(`${Config.BASE_URL}/maisons/?owner=${currentUserId}`, {
          headers: { Authorization: `Bearer ${accessToken}` }
        }).catch(() => ({ data: { results: [] } })),
        axios.get(`${Config.BASE_URL}/maisons/mes_favoris/`, {
          headers: { Authorization: `Bearer ${accessToken}` }
        }).catch(() => ({ data: [] }))
      ]);

      const maisonsCount = maisonsRes.data.results?.length || maisonsRes.data.length || 0;
      const favorisCount = favorisRes.data.length || 0;

      setStats({
        annonces: maisonsCount,
        favoris: favorisCount,
        commentaires: 0
      });
    } catch (error) {
      console.error('Erreur chargement stats:', error);
    }
  };

  const loadUserProperties = async (accessToken) => {
    try {
      const response = await axios.get(`${Config.BASE_URL}/maisons/?owner=${currentUserId}`, {
        headers: { Authorization: `Bearer ${accessToken}` }
      });
      
      const properties = response.data.results || response.data || [];
      setUserProperties(properties.slice(0, 3));
    } catch (error) {
      console.error('Erreur chargement annonces:', error);
    }
  };

  const onRefresh = async () => {
    setRefreshing(true);
    await loadTokenAndUser();
    setRefreshing(false);
  };

  const handleEditProfile = () => {
    navigation.navigate('EditProfil', { userId: user?.id });
  };

  const handleLogout = async () => {
    Alert.alert(
      'Déconnexion',
      'Voulez-vous vraiment vous déconnecter ?',
      [
        { text: 'Annuler', style: 'cancel' },
        {
          text: 'Déconnexion',
          style: 'destructive',
          onPress: async () => {
            await AsyncStorage.multiRemove(['access_token', 'refresh_token', 'user']);
            navigation.replace('LoginScreen');
          }
        }
      ]
    );
  };

  const handlePropertyPress = (propertyId) => {
    navigation.navigate('MaisonDetail', { maisonId: propertyId });
  };

  const getInitials = (name) => {
    if (!name) return '?';
    return name
      .split(' ')
      .map(part => part[0])
      .join('')
      .toUpperCase()
      .substring(0, 2);
  };

  const getAvatarColor = (name) => {
    const colors = [
      '#6C63FF', '#FF6B9D', '#4CAF50', '#2196F3',
      '#FF9800', '#9C27B0', '#00BCD4', '#795548'
    ];
    const index = name ? name.charCodeAt(0) % colors.length : 0;
    return colors[index];
  };

  const formatDate = (dateString) => {
    if (!dateString) return 'N/A';
    const date = new Date(dateString);
    return date.toLocaleDateString('fr-FR', {
      day: 'numeric',
      month: 'long',
      year: 'numeric'
    });
  };

  if (loading && !user) {
    return (
      <View style={styles.loadingContainer}>
        <ActivityIndicator size="large" color="#052c65" />
        <Text style={styles.loadingText}>Chargement du profil...</Text>
      </View>
    );
  }

  if (!user) {
    return null; // Ne devrait pas arriver car redirigé
  }

  return (
    <SafeAreaView style={styles.container}>
      <StatusBar barStyle={isDarkMode ? 'light-content' : 'dark-content'} backgroundColor={theme.background} translucent />
      
      <View style={styles.header}>
        <TouchableOpacity style={styles.backButton} onPress={() => navigation.goBack()}>
          <Ionicons name="arrow-back" size={24} color="#052c65" />
        </TouchableOpacity>
        <Text style={styles.headerTitle}>Mon Profil</Text>
        <View style={styles.headerActions}>
          <TouchableOpacity style={styles.headerButton} onPress={handleEditProfile}>
            <FontAwesome name="pencil" size={20} color="#052c65" />
          </TouchableOpacity>
          <TouchableOpacity style={styles.headerButton} onPress={handleLogout}>
            <MaterialIcons name="logout" size={22} color="#FF3B30" />
          </TouchableOpacity>
        </View>
      </View>

      <ScrollView
        showsVerticalScrollIndicator={false}
        refreshControl={
          <RefreshControl
            refreshing={refreshing}
            onRefresh={onRefresh}
            colors={['#052c65']}
            tintColor="#052c65"
          />
        }
      >
        <View style={styles.profileHeader}>
          <View style={styles.avatarContainer}>
            {user.avatar ? (
              <Image source={{ uri: user.avatar }} style={styles.avatar} />
            ) : (
              <View style={[styles.avatarPlaceholder, { backgroundColor: getAvatarColor(user.username) }]}>
                <Text style={styles.avatarInitials}>{getInitials(user.username)}</Text>
              </View>
            )}
            <TouchableOpacity style={styles.editAvatarButton} onPress={handleEditProfile}>
              <FontAwesome name="camera" size={14} color="#fff" />
            </TouchableOpacity>
          </View>

          <Text style={styles.userName}>{user.username}</Text>
          
          {user.is_proprietaire && (
            <View style={styles.badgeContainer}>
              <View style={styles.proprietaireBadge}>
                <FontAwesome name="check-circle" size={14} color="#4CAF50" />
                <Text style={styles.proprietaireBadgeText}>Propriétaire vérifié</Text>
              </View>
            </View>
          )}

          <View style={styles.statsContainer}>
            <View style={styles.statItem}>
              <Text style={styles.statValue}>{stats.annonces}</Text>
              <Text style={styles.statLabel}>Annonces</Text>
            </View>
            <View style={styles.statDivider} />
            <View style={styles.statItem}>
              <Text style={styles.statValue}>{stats.favoris}</Text>
              <Text style={styles.statLabel}>Favoris</Text>
            </View>
            <View style={styles.statDivider} />
            <View style={styles.statItem}>
              <Text style={styles.statValue}>{user.date_joined ? formatDate(user.date_joined) : 'N/A'}</Text>
              <Text style={styles.statLabel}>Membre depuis</Text>
            </View>
          </View>
        </View>

        <View style={styles.section}>
          <Text style={styles.sectionTitle}>Informations de contact</Text>
          <View style={styles.infoCard}>
            {user.phone_number && (
              <View style={styles.infoRow}>
                <FontAwesome name="phone" size={16} color="#052c65" style={styles.infoIcon} />
                <View style={styles.infoContent}>
                  <Text style={styles.infoLabel}>Téléphone</Text>
                  <Text style={styles.infoValue}>{user.phone_number}</Text>
                </View>
              </View>
            )}
            {user.email && (
              <View style={styles.infoRow}>
                <FontAwesome name="envelope" size={16} color="#052c65" style={styles.infoIcon} />
                <View style={styles.infoContent}>
                  <Text style={styles.infoLabel}>Email</Text>
                  <Text style={styles.infoValue}>{user.email}</Text>
                </View>
              </View>
            )}
          </View>
        </View>

        {userProperties.length > 0 && (
          <View style={styles.section}>
            <View style={styles.sectionHeader}>
              <Text style={styles.sectionTitle}>Mes annonces</Text>
            </View>
            {userProperties.map((property) => (
              <TouchableOpacity
                key={property.id}
                style={styles.propertyCard}
                onPress={() => handlePropertyPress(property.id)}
              >
                <Image
                  source={
                    property.photos && property.photos[0]
                      ? { uri: property.photos[0].photos || property.photos[0] }
                      : require('../assets/placeholder.png')
                  }
                  style={styles.propertyImage}
                />
                <View style={styles.propertyInfo}>
                  <Text style={styles.propertyTitle}>{property.titre || 'Sans titre'}</Text>
                  <Text style={styles.propertyLocation}>
                    <FontAwesome name="map-marker" size={12} color="#666" /> {property.ville}
                  </Text>
                  <Text style={styles.propertyPrice}>{property.prix?.toLocaleString()} fCfa</Text>
                </View>
              </TouchableOpacity>
            ))}
          </View>
        )}
      </ScrollView>
    </SafeAreaView>
  );
};

const styles = StyleSheet.create({
  container: { flex: 1, backgroundColor: '#f8f9fa' },
  loadingContainer: { flex: 1, justifyContent: 'center', alignItems: 'center', backgroundColor: '#fff' },
  loadingText: { marginTop: 15, fontSize: 16, color: '#666' },
  header: { flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', paddingHorizontal: 15, paddingVertical: 12, backgroundColor: '#fff', borderBottomWidth: 1, borderBottomColor: '#e8e8e8' },
  backButton: { width: 40, height: 40, borderRadius: 20, backgroundColor: '#F0F5FF', justifyContent: 'center', alignItems: 'center' },
  headerTitle: { fontSize: 18, fontWeight: 'bold', color: '#333' },
  headerActions: { flexDirection: 'row', alignItems: 'center' },
  headerButton: { width: 40, height: 40, borderRadius: 20, justifyContent: 'center', alignItems: 'center', marginLeft: 8 },
  profileHeader: { backgroundColor: '#fff', paddingVertical: 30, paddingHorizontal: 20, alignItems: 'center', borderBottomWidth: 1, borderBottomColor: '#e8e8e8' },
  avatarContainer: { position: 'relative', marginBottom: 15 },
  avatar: { width: 100, height: 100, borderRadius: 50, borderWidth: 3, borderColor: '#052c65' },
  avatarPlaceholder: { width: 100, height: 100, borderRadius: 50, justifyContent: 'center', alignItems: 'center', borderWidth: 3, borderColor: '#052c65' },
  avatarInitials: { color: '#fff', fontSize: 36, fontWeight: 'bold' },
  editAvatarButton: { position: 'absolute', bottom: 0, right: 0, backgroundColor: '#052c65', width: 30, height: 30, borderRadius: 15, justifyContent: 'center', alignItems: 'center', borderWidth: 2, borderColor: '#fff' },
  userName: { fontSize: 24, fontWeight: 'bold', color: '#333', marginBottom: 8 },
  badgeContainer: { flexDirection: 'row', marginBottom: 15 },
  proprietaireBadge: { flexDirection: 'row', alignItems: 'center', backgroundColor: 'rgba(76, 175, 80, 0.1)', paddingHorizontal: 12, paddingVertical: 6, borderRadius: 20 },
  proprietaireBadgeText: { fontSize: 12, color: '#4CAF50', fontWeight: '600', marginLeft: 6 },
  statsContainer: { flexDirection: 'row', justifyContent: 'space-around', alignItems: 'center', width: '100%', marginTop: 10, paddingTop: 20, borderTopWidth: 1, borderTopColor: '#f0f0f0' },
  statItem: { alignItems: 'center', flex: 1 },
  statValue: { fontSize: 18, fontWeight: 'bold', color: '#333' },
  statLabel: { fontSize: 12, color: '#666', marginTop: 4 },
  statDivider: { width: 1, height: 30, backgroundColor: '#e0e0e0' },
  section: { backgroundColor: '#fff', marginTop: 10, paddingVertical: 20, paddingHorizontal: 20 },
  sectionHeader: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 15 },
  sectionTitle: { fontSize: 18, fontWeight: 'bold', color: '#333' },
  infoCard: { backgroundColor: '#f8f9fa', borderRadius: 12, padding: 15 },
  infoRow: { flexDirection: 'row', alignItems: 'center', paddingVertical: 12, borderBottomWidth: 1, borderBottomColor: '#e8e8e8' },
  infoIcon: { width: 24 },
  infoContent: { flex: 1, marginLeft: 12 },
  infoLabel: { fontSize: 12, color: '#666', marginBottom: 2 },
  infoValue: { fontSize: 16, color: '#333', fontWeight: '500' },
  propertyCard: { flexDirection: 'row', backgroundColor: '#fff', borderRadius: 12, marginBottom: 12, padding: 12, borderWidth: 1, borderColor: '#f0f0f0' },
  propertyImage: { width: 80, height: 80, borderRadius: 8 },
  propertyInfo: { flex: 1, marginLeft: 12 },
  propertyTitle: { fontSize: 16, fontWeight: '600', color: '#333', marginBottom: 4 },
  propertyLocation: { fontSize: 12, color: '#666', marginBottom: 4 },
  propertyPrice: { fontSize: 14, fontWeight: 'bold', color: '#052c65', marginBottom: 4 }
});

export default ProfileScreen;



