import React, { useEffect, useState } from 'react';
import { StyleSheet, Text, View, FlatList, TouchableOpacity, Image, Alert } from 'react-native';
import FontAwesome from 'react-native-vector-icons/FontAwesome';
import axios from 'axios';
import { useNavigation } from '@react-navigation/native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import Config from './Config';
import { useTheme } from '../context/ThemeContext.js';
import { useThemedStyles } from '../hooks/useThemedStyles';

const BandeParcelle = () => {
    const { isDarkMode } = useTheme();
    const { createThemedStyles, theme } = useThemedStyles();
    const styles = createThemedStyles(themedStyles);
    
    const [parcelles, setParcelles] = useState([]);
    const [likes, setLikes] = useState({});
    const [user, setUser] = useState(null);
    const [loading, setLoading] = useState(true);
    const navigation = useNavigation();

    useEffect(() => {
        const fetchUserData = async () => {
            try {
                const userData = await AsyncStorage.getItem('user');
                const token = await AsyncStorage.getItem('access_token');
                if (userData && token) setUser({ ...JSON.parse(userData), token });
            } catch (error) { console.error('Erreur:', error); }
        };
        fetchUserData();
    }, []);

    useEffect(() => {
        const fetchData = async () => {
            try {
                setLoading(true);
                const response = await axios.get(`${Config.BASE_URL}/parcelles/`);
                let parcellesData = [];
                if (response.data?.results) parcellesData = response.data.results;
                else if (Array.isArray(response.data)) parcellesData = response.data;
                
                const initialLikes = {};
                parcellesData.forEach(p => { initialLikes[p.id] = { liked: false, count: 0 }; });
                setLikes(initialLikes);
                setParcelles(parcellesData);
            } catch (error) {
                setParcelles([
                    { id: 'demo1', titre: 'Terrain résidentiel', prix: 25000000, surface: 500, quartier: 'Niamey', ville: 'Niger', type_parcelle: 'residentielle', photos: [], owner: null, description: 'Magnifique terrain pour construction' }
                ]);
            } finally { setLoading(false); }
        };
        fetchData();
    }, []);

    const getImageUri = (item) => {
        if (item.photos?.length > 0) {
            const firstPhoto = item.photos[0];
            if (typeof firstPhoto === "object" && firstPhoto.photos) return firstPhoto.photos;
            if (typeof firstPhoto === "string") return firstPhoto;
        }
        return null;
    };

    const handleItemPress = (item) => {
        navigation.navigate('MaisonDetail', { 
            maisonId: item.id, 
            maison: {
                ...item,
                type: 'parcelle',
                type_maison: 'vente',
                nombre_chambres: 0,
                nombre_salles_de_bain: 0,
                piscine: false,
                jardin: false,
                garage: false,
                climatiseur: false,
                internet: false,
                meuble: false
            }
        });
    };

    const renderParcelleItem = ({ item }) => {
        const imageUri = getImageUri(item);
        return (
            <TouchableOpacity onPress={() => handleItemPress(item)} activeOpacity={0.9}>
                <View style={[styles.parcelleContainer, isDarkMode && styles.darkCard]}>
                    <View style={styles.imageContainer}>
                        <Image source={imageUri ? { uri: imageUri } : require('../assets/icon.png')} style={styles.parcelleImage} resizeMode="cover" />
                        <View style={styles.imageOverlay} />
                        <View style={styles.priceBadge}><Text style={styles.priceText}>{parseFloat(item.prix).toLocaleString('fr-FR')} FCFA</Text></View>
                        <View style={styles.bottomOverlay}>
                            <View style={styles.topRow}>
                                <TouchableOpacity style={styles.profileSection} onPress={() => navigation.navigate('ProfilScreen', { userId: item.owner?.id })}>
                                    <Image source={item.owner?.avatar ? { uri: item.owner.avatar } : require('../assets/profil.jpg')} style={styles.userImage} />
                                    <Text style={styles.ownerName}>{item.owner?.username || 'Propriétaire'}</Text>
                                </TouchableOpacity>
                            </View>
                            <View style={styles.featuresColumn}>
                                <View style={styles.featureItem}><FontAwesome name="expand" size={14} color="#fff" /><Text style={styles.featureText}>{item.surface} m²</Text></View>
                                <View style={styles.featureItem}><FontAwesome name="tag" size={14} color="#fff" /><Text style={styles.featureText}>{item.type_parcelle === 'residentielle' ? 'Résidentielle' : item.type_parcelle}</Text></View>
                                <View style={styles.featureItem}><FontAwesome name="map" size={14} color="#fff" /><Text style={styles.featureText}>{item.ville}</Text></View>
                            </View>
                        </View>
                    </View>
                </View>
            </TouchableOpacity>
        );
    };

    if (loading) return <View style={[styles.loadingContainer, isDarkMode && styles.darkContainer]}><Text style={isDarkMode && styles.darkText}>Chargement des terrains...</Text></View>;

    return (
        <View style={[styles.container, isDarkMode && styles.darkContainer]}>
            <View style={styles.sectionHeader}>
                <Text style={[styles.title, isDarkMode && styles.darkText]}></Text>
                <TouchableOpacity style={styles.seeAllButton} onPress={() => navigation.navigate('AllParcelles')}>
                    <Text style={[styles.seeAllText, isDarkMode && styles.darkText]}>Tout voir</Text>
                    <FontAwesome name="chevron-right" size={14} color={isDarkMode ? '#aaa' : '#052c65'} />
                </TouchableOpacity>
            </View>
            <FlatList 
                data={parcelles} 
                keyExtractor={item => item.id.toString()} 
                horizontal 
                showsHorizontalScrollIndicator={false} 
                renderItem={renderParcelleItem} 
                contentContainerStyle={styles.listContent} 
                ListEmptyComponent={<View style={styles.emptyContainer}><FontAwesome name="tree" size={40} color="#ccc" /><Text style={[styles.emptyText, isDarkMode && styles.darkSubText]}>Aucun terrain</Text></View>} 
            />
        </View>
    );
};

const themedStyles = (theme, isDarkMode, Platform, StatusBar) => StyleSheet.create({
    container: { flex: 1, backgroundColor: theme.background },
    darkContainer: { backgroundColor: '#1a1a1a' },
    darkCard: { backgroundColor: '#2d2d2d' },
    darkText: { color: '#fff' },
    darkSubText: { color: '#aaa' },
    
    sectionHeader: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', paddingHorizontal: 15, marginBottom: 15 },
    title: { fontSize: 22, fontWeight: 'bold', color: theme.primary, letterSpacing: 0.5 },
    seeAllButton: { flexDirection: 'row', alignItems: 'center' },
    seeAllText: { fontSize: 14, fontWeight: '600', marginRight: 5 },
    listContent: { paddingHorizontal: 10, paddingBottom: 10 },
    parcelleContainer: { marginRight: 15, width: 320, backgroundColor: '#fff', borderRadius: 20, overflow: 'hidden', elevation: 3, shadowColor: '#000', shadowOffset: { width: 0, height: 2 }, shadowOpacity: 0.1, shadowRadius: 4 },
    imageContainer: { position: 'relative', height: 220 },
    parcelleImage: { width: '100%', height: '100%' },
    imageOverlay: { position: 'absolute', top: 0, left: 0, right: 0, bottom: 0, backgroundColor: 'rgba(0, 0, 0, 0.4)' },
    priceBadge: { position: 'absolute', top: 10, right: 10, backgroundColor: 'rgba(5, 44, 101, 0.95)', paddingHorizontal: 12, paddingVertical: 6, borderRadius: 15, elevation: 2 },
    priceText: { color: '#fff', fontSize: 14, fontWeight: 'bold' },
    bottomOverlay: { position: 'absolute', bottom: 0, left: 0, right: 0, padding: 15, borderBottomLeftRadius: 20, borderBottomRightRadius: 20 },
    topRow: { flexDirection: 'row', justifyContent: 'space-between', alignItems: 'center', marginBottom: 12 },
    profileSection: { flexDirection: 'row', alignItems: 'center', flex: 1 },
    userImage: { width: 32, height: 32, borderRadius: 16, backgroundColor: '#f0f0f0', borderWidth: 2, borderColor: '#fff', marginRight: 10 },
    ownerName: { fontSize: 13, fontWeight: '600', color: '#fff', marginBottom: 2, textShadowColor: 'rgba(0, 0, 0, 0.5)', textShadowOffset: { width: 1, height: 1 }, textShadowRadius: 2 },
    featuresColumn: { marginTop: 10, alignItems: 'flex-start' },
    featureItem: { flexDirection: 'row', alignItems: 'center', marginBottom: 5 },
    featureText: { fontSize: 12, color: '#fff', marginLeft: 5, textShadowColor: 'rgba(0, 0, 0, 0.5)', textShadowOffset: { width: 1, height: 1 }, textShadowRadius: 2 },
    loadingContainer: { padding: 40, justifyContent: 'center', alignItems: 'center' },
    emptyContainer: { paddingHorizontal: 30, paddingVertical: 40, alignItems: 'center', justifyContent: 'center' },
    emptyText: { fontSize: 16, fontWeight: 'bold', color: '#666', marginTop: 15, textAlign: 'center' },
});

export default BandeParcelle;
