import React, { useState } from 'react';
import {
  View,
  Text,
  StyleSheet,
  ScrollView,
  TouchableOpacity,
  TextInput,
  Alert,
  StatusBar,
  ActivityIndicator
} from 'react-native';
import Ionicons from 'react-native-vector-icons/Ionicons';
import AsyncStorage from '@react-native-async-storage/async-storage';
import axios from 'axios';
import Config from './Config';
import { useTheme } from '../context/ThemeContext.js';
import { useThemedStyles } from '../hooks/useThemedStyles';

const ContactForm = () => {
  const { isDarkMode } = useTheme();
  const { createThemedStyles, theme } = useThemedStyles();
  const styles = createThemedStyles(themedStyles);
  
  const [formData, setFormData] = useState({
    subject: '',
    message: '',
    category: 'general'
  });
  const [loading, setLoading] = useState(false);

  const categories = [
    { id: 'general', label: 'Question générale', icon: 'help' },
    { id: 'technical', label: 'Problème technique', icon: 'bug' },
    { id: 'billing', label: 'Facturation', icon: 'card' },
    { id: 'partnership', label: 'Partenariat', icon: 'handshake' }
  ];

  const handleSubmit = async () => {
    if (!formData.subject || !formData.message) {
      Alert.alert('Erreur', 'Veuillez remplir tous les champs');
      return;
    }

    setLoading(true);
    try {
      const token = await AsyncStorage.getItem('access_token');
      await axios.post(`${Config.BASE_URL}/api/contact/send/`, formData, {
        headers: { Authorization: `Bearer ${token}` }
      });
      
      Alert.alert(
        'Message envoyé',
        'Nous vous répondrons dans les plus brefs délais.',
        [{ text: 'OK', onPress: () => setFormData({ subject: '', message: '', category: 'general' }) }]
      );
    } catch (error) {
      Alert.alert('Erreur', 'Impossible d\'envoyer votre message');
    } finally {
      setLoading(false);
    }
  };

  return (
    <ScrollView style={[styles.container, isDarkMode && styles.darkContainer]}>
      <View style={styles.header}>
        <Text style={[styles.headerTitle, isDarkMode && styles.darkText]}>Nous contacter</Text>
        <Text style={[styles.headerSubtitle, isDarkMode && styles.darkSubText]}>
          Une question ? Un problème ? Écrivez-nous !
        </Text>
      </View>

      <View style={styles.formSection}>
        <View style={styles.formGroup}>
          <Text style={[styles.label, isDarkMode && styles.darkText]}>Catégorie</Text>
          <View style={styles.categoriesGrid}>
            {categories.map((cat) => (
              <TouchableOpacity
                key={cat.id}
                style={[
                  styles.categoryCard,
                  formData.category === cat.id && styles.categorySelected,
                  isDarkMode && styles.darkCard
                ]}
                onPress={() => setFormData({...formData, category: cat.id})}
              >
                <Ionicons 
                  name={cat.icon} 
                  size={24} 
                  color={formData.category === cat.id ? '#fff' : theme.primary} 
                />
                <Text style={[
                  styles.categoryLabel,
                  formData.category === cat.id && styles.categoryLabelSelected,
                  isDarkMode && styles.darkText
                ]}>
                  {cat.label}
                </Text>
              </TouchableOpacity>
            ))}
          </View>
        </View>

        <View style={styles.formGroup}>
          <Text style={[styles.label, isDarkMode && styles.darkText]}>Sujet *</Text>
          <View style={[styles.inputContainer, isDarkMode && styles.darkCard]}>
            <Ionicons name="chatbubble" size={20} color={theme.subText} />
            <TextInput
              style={[styles.input, isDarkMode && styles.darkText]}
              placeholder="Sujet de votre message"
              placeholderTextColor={theme.subText}
              value={formData.subject}
              onChangeText={(text) => setFormData({...formData, subject: text})}
            />
          </View>
        </View>

        <View style={styles.formGroup}>
          <Text style={[styles.label, isDarkMode && styles.darkText]}>Message *</Text>
          <View style={[styles.textAreaContainer, isDarkMode && styles.darkCard]}>
            <TextInput
              style={[styles.textArea, isDarkMode && styles.darkText]}
              placeholder="Décrivez votre demande en détail..."
              placeholderTextColor={theme.subText}
              multiline
              numberOfLines={6}
              value={formData.message}
              onChangeText={(text) => setFormData({...formData, message: text})}
            />
          </View>
        </View>

        <TouchableOpacity 
          style={[styles.submitButton, loading && styles.buttonDisabled]}
          onPress={handleSubmit}
          disabled={loading}
        >
          {loading ? (
            <ActivityIndicator color="#fff" />
          ) : (
            <>
              <Ionicons name="send" size={20} color="#fff" />
              <Text style={styles.submitButtonText}>Envoyer le message</Text>
            </>
          )}
        </TouchableOpacity>
      </View>

      <View style={styles.infoSection}>
        <Text style={[styles.infoTitle, isDarkMode && styles.darkText]}>Autres moyens de contact</Text>
        <View style={styles.infoItem}>
          <Ionicons name="call" size={24} color={theme.primary} />
          <View>
            <Text style={[styles.infoLabel, isDarkMode && styles.darkText]}>Téléphone</Text>
            <Text style={[styles.infoValue, isDarkMode && styles.darkSubText]}>+221 78 123 45 67</Text>
          </View>
        </View>
        <View style={styles.infoItem}>
          <Ionicons name="mail" size={24} color={theme.primary} />
          <View>
            <Text style={[styles.infoLabel, isDarkMode && styles.darkText]}>Email</Text>
            <Text style={[styles.infoValue, isDarkMode && styles.darkSubText]}>contact@villana.com</Text>
          </View>
        </View>
        <View style={styles.infoItem}>
          <Ionicons name="time" size={24} color={theme.primary} />
          <View>
            <Text style={[styles.infoLabel, isDarkMode && styles.darkText]}>Horaires</Text>
            <Text style={[styles.infoValue, isDarkMode && styles.darkSubText]}>Lun-Ven: 9h-18h</Text>
          </View>
        </View>
      </View>
    </ScrollView>
  );
};

const themedStyles = (theme, isDarkMode, Platform, StatusBar) => StyleSheet.create({
  container: {
          flex: 1,
          backgroundColor: theme.background,
          paddingTop: Platform.OS === 'android' ? StatusBar.currentHeight : 0,
        },
  darkContainer: { backgroundColor: '#1a1a1a' },
  darkText: { color: '#fff' },
  darkSubText: { color: '#aaa' },
  darkCard: { backgroundColor: '#2d2d2d' },
  
  header: { padding: 20, backgroundColor: theme.card, marginBottom: 15 },
  headerTitle: { fontSize: 28, fontWeight: 'bold', color: theme.text, marginBottom: 5 },
  headerSubtitle: { fontSize: 14, color: theme.subText },
  
  formSection: { padding: 20 },
  formGroup: { marginBottom: 20 },
  label: { fontSize: 14, fontWeight: '600', color: theme.text, marginBottom: 8 },
  
  categoriesGrid: { flexDirection: 'row', flexWrap: 'wrap', gap: 10 },
  categoryCard: { flex: 1, minWidth: '45%', backgroundColor: theme.card, padding: 12, borderRadius: 10, alignItems: 'center', borderWidth: 1, borderColor: theme.border },
  categorySelected: { backgroundColor: theme.primary, borderColor: theme.primary },
  categoryLabel: { fontSize: 12, marginTop: 5, color: theme.text },
  categoryLabelSelected: { color: '#fff' },
  
  inputContainer: { flexDirection: 'row', alignItems: 'center', backgroundColor: theme.card, borderRadius: 10, paddingHorizontal: 15, borderWidth: 1, borderColor: theme.border },
  input: { flex: 1, paddingVertical: 12, marginLeft: 10, fontSize: 16 },
  textAreaContainer: { backgroundColor: theme.card, borderRadius: 10, borderWidth: 1, borderColor: theme.border, padding: 15 },
  textArea: { fontSize: 16, textAlignVertical: 'top', minHeight: 120 },
  
  submitButton: { backgroundColor: theme.primary, padding: 15, borderRadius: 10, alignItems: 'center', flexDirection: 'row', justifyContent: 'center', gap: 10 },
  buttonDisabled: { opacity: 0.6 },
  submitButtonText: { color: '#fff', fontSize: 16, fontWeight: 'bold' },
  
  infoSection: { margin: 20, padding: 20, backgroundColor: theme.card, borderRadius: 12, gap: 15 },
  infoTitle: { fontSize: 18, fontWeight: 'bold', color: theme.text, marginBottom: 10 },
  infoItem: { flexDirection: 'row', alignItems: 'center', gap: 15 },
  infoLabel: { fontSize: 14, fontWeight: '600', color: theme.text },
  infoValue: { fontSize: 14, color: theme.subText, marginTop: 2 },
});

export default ContactForm;
